const PURIFY_VERSION    = "1.0";
const PURIFY_MAX_PAYLOAD = 500;
const PURIFY_RATE_MS    = 1500;
const PURIFY_SIGNATURE  = "LOVETHAIDEA";
const PURIFY_ALLOWED    = ["SALON","STYLIST","STYLE","CONSULT","CUSTOM"];

// -- Threat severity levels ----------------------------------------------------
const THREAT = {
  CRITICAL: { level:"CRITICAL", color:"#DC2626", bg:"#FEF2F2", border:"#FECACA", icon:"🚨", action:"LOCKDOWN" },
  HIGH:     { level:"HIGH",     color:"#EA580C", bg:"#FFF7ED", border:"#FDBA74", icon:"⚠",  action:"BLOCK"    },
  MEDIUM:   { level:"MEDIUM",   color:"#D97706", bg:"#FFFBEB", border:"#FCD34D", icon:"⚡",  action:"QUARANTINE"},
  LOW:      { level:"LOW",      color:"#0891B2", bg:"#EFF6FF", border:"#BAE6FD", icon:"ℹ",  action:"LOG"      },
};

// -- Global event bus for cross-platform security events ----------------------
const PURIFY_EVENTS = [];
function purifyEmit(event) {
  PURIFY_EVENTS.push({ ...event, ts: new Date().toISOString(), id: Date.now() + Math.random() });
  if (PURIFY_EVENTS.length > 200) PURIFY_EVENTS.shift();
}

// -- Core sanitization ---------------------------------------------------------
function purifyStr(str, maxLen = 200) {
  if (typeof str !== "string") return "";
  return str
    .replace(/</g,  "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g,  "&quot;").replace(/'/g, "&#x27;")
    .replace(/[\x60]/g, "&#x60;")
    .replace(/javascript:/gi, "").replace(/vbscript:/gi, "")
    .replace(/data:/gi,       "").replace(/on\w+\s*=/gi, "")
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, "")
    .trim().slice(0, maxLen);
}

// -- URL safety validator ------------------------------------------------------
function purifyURL(url) {
  try {
    const u = new URL(url);
    return ["https:","http:"].includes(u.protocol) &&
           !u.hostname.includes("javascript") &&
           !u.hostname.includes("data") &&
           u.hostname.length > 0 && u.hostname.length < 100;
  } catch(e) { return false; }
}

// -- Threat intelligence scanner -----------------------------------------------
function purifyAnalyze(payload) {
  if (!payload || typeof payload !== "string") {
    return { safe: false, threats: ["Empty or invalid payload"], severity: THREAT.LOW };
  }

  const threats = [];
  let severity   = THREAT.LOW;

  // CRITICAL  -  code execution
  if (/<script[\s>]|javascript:|vbscript:|eval\s*\(|new\s+Function\s*\(/i.test(payload)) {
    threats.push("Code execution attempt: script injection");
    severity = THREAT.CRITICAL;
  }
  if (/document\.(cookie|domain|write|location)|window\.(location|open)|localStorage|sessionStorage/i.test(payload)) {
    threats.push("DOM manipulation / data exfiltration attempt");
    severity = THREAT.CRITICAL;
  }

  // CRITICAL  -  injection attacks
  if (/union\s+select|drop\s+table|insert\s+into|delete\s+from|exec\s*\(|xp_cmdshell/i.test(payload)) {
    threats.push("SQL / command injection pattern");
    severity = THREAT.CRITICAL;
  }

  // HIGH  -  data attacks
  if (/data:text\/html|data:application\/|base64,[A-Za-z0-9+/]{20}/i.test(payload)) {
    threats.push("Data URI attack  -  encoded payload");
    severity = severity.level === "CRITICAL" ? severity : THREAT.HIGH;
  }
  if (/onerror=|onload=|onclick=|onmouseover=|onfocus=|onblur=/i.test(payload)) {
    threats.push("Event handler injection");
    severity = severity.level === "CRITICAL" ? severity : THREAT.HIGH;
  }
  if (/<iframe|<object|<embed|<link\s+rel|<meta\s+http/i.test(payload)) {
    threats.push("Malicious HTML element injection");
    severity = severity.level === "CRITICAL" ? severity : THREAT.HIGH;
  }

  // HIGH  -  identity spoofing
  if (/l0vethat|lovethat1|1ovethat|lovethatidea\.ru|lovethatidea\.cn/i.test(payload)) {
    threats.push("Spoofed LTI domain  -  phishing attempt");
    severity = severity.level === "CRITICAL" ? severity : THREAT.HIGH;
  }
  if (/[\u0400-\u04FF]/.test(payload) && payload.toUpperCase().includes("LOVETHAIDEA")) {
    threats.push("Cyrillic homoglyph attack on LTI signature");
    severity = severity.level === "CRITICAL" ? severity : THREAT.HIGH;
  }

  // MEDIUM  -  suspicious patterns
  if (payload.includes("\x00") || payload.includes("%00")) {
    threats.push("Null byte injection");
    severity = severity === THREAT.LOW ? THREAT.MEDIUM : severity;
  }
  if (/bit\.ly|tinyurl\.com|t\.co|goo\.gl|ow\.ly|buff\.ly/i.test(payload)) {
    threats.push("Shortened URL  -  destination unknown");
    severity = severity === THREAT.LOW ? THREAT.MEDIUM : severity;
  }
  if (payload.length > PURIFY_MAX_PAYLOAD) {
    threats.push("Oversized payload (" + payload.length + " chars)  -  possible buffer attack");
    severity = severity === THREAT.LOW ? THREAT.MEDIUM : severity;
  }
  if (/(\.\.|\/etc\/passwd|\/etc\/shadow|\.env|\.git\/|wp-admin)/i.test(payload)) {
    threats.push("Path traversal / server probe attempt");
    severity = severity === THREAT.LOW ? THREAT.MEDIUM : severity;
  }

  // LOW  -  reconnaissance
  if (/nmap|nikto|sqlmap|metasploit|burpsuite/i.test(payload)) {
    threats.push("Security tool signature detected");
  }

  if (threats.length === 0) return { safe: true, threats: [], severity: null };
  return { safe: false, threats, severity };
}

// -- Platform-wide input sanitizer ---------------------------------------------
function purifyInput(value, opts = {}) {
  const { maxLen = 500, allowHTML = false, fieldName = "field" } = opts;
  if (!value) return "";
  const str  = String(value);
  const scan = purifyAnalyze(str);
  if (!scan.safe) {
    purifyEmit({ type:"INPUT_THREAT", field: fieldName, threats: scan.threats, severity: scan.severity?.level });
    return "";
  }
  return allowHTML ? str.slice(0, maxLen) : purifyStr(str, maxLen);
}

