// -- Powered by Claude Badge ---------------------------------------------------
function ClaudeBadge({ size = "sm", style = {} }) {
  const configs = {
    sm:  { fontSize:"9px",  padding:"3px 10px 3px 6px",  gap:"4px",  iconSize:12, tagSize:"8px"  },
    md:  { fontSize:"11px", padding:"5px 12px 5px 8px",  gap:"5px",  iconSize:15, tagSize:"9px"  },
    lg:  { fontSize:"13px", padding:"7px 15px 7px 10px", gap:"6px",  iconSize:18, tagSize:"10px" },
  };
  const cfg = configs[size] || configs.sm;
  return (
    <span style={{
      display:"inline-flex", alignItems:"center", gap:cfg.gap,
      background:"linear-gradient(135deg,#C9A84C 0%,#8B6914 60%,#5A4209 100%)",
      color:"#fff", fontSize:cfg.fontSize,
      fontFamily:"'DM Sans','Helvetica Neue',sans-serif",
      fontWeight:"700", padding:cfg.padding,
      borderRadius:"20px", letterSpacing:"0.3px", whiteSpace:"nowrap",
      boxShadow:"0 2px 10px rgba(201,168,76,0.45), 0 0 0 1px rgba(255,220,80,0.25) inset",
      position:"relative", ...style }}>
      <svg width={cfg.iconSize} height={cfg.iconSize} viewBox="0 0 24 24" fill="none">
        <circle cx="12" cy="12" r="9" fill="rgba(255,255,255,0.18)"/>
        <circle cx="12" cy="12" r="5" fill="rgba(255,255,255,0.28)"/>
        <circle cx="12" cy="12" r="2" fill="white"/>
        <path d="M12 3v3M12 18v3M3 12h3M18 12h3M5.6 5.6l2.1 2.1M16.3 16.3l2.1 2.1M5.6 18.4l2.1-2.1M16.3 7.7l2.1-2.1" stroke="rgba(255,255,255,0.55)" strokeWidth="1.2" strokeLinecap="round"/>
      </svg>
      Powered by Claude
      <span style={{
        background:"rgba(255,255,255,0.22)",
        border:"1px solid rgba(255,255,255,0.35)",
        borderRadius:"10px",
        fontSize:cfg.tagSize,
        fontWeight:"900",
        padding:"1px 5px",
        letterSpacing:"0.5px",
        color:"#FFF8DC",
        marginLeft:"2px",
        lineHeight:1.2,
      }}>5G</span>
    </span>
  );
}


function LanguageSelector() {
  const { lang, setLang } = useLang();
  const [open, setOpen]       = useState(false);
  const [search, setSearch]   = useState("");
  const [regionFilter, setRegionFilter] = useState("All");
  const current = LANGUAGES.find(l=>l.code===lang) || LANGUAGES[0];
  const ref = useRef(null);

  useEffect(()=>{
    function handle(e){ if(ref.current&&!ref.current.contains(e.target)) setOpen(false); }
    document.addEventListener("mousedown", handle);
    return ()=>document.removeEventListener("mousedown",handle);
  },[]);

  const regions = ["All",...new Set(LANGUAGES.map(l=>l.region))];
  const filtered = LANGUAGES.filter(l=>{
    if (regionFilter !== "All" && l.region !== regionFilter) return false;
    if (search && !l.name.toLowerCase().includes(search.toLowerCase()) && !l.native.toLowerCase().includes(search.toLowerCase())) return false;
    return true;
  });

  return (
    <div ref={ref} style={{ position:"relative" }}>
      <button onClick={()=>setOpen(o=>!o)}
        style={{ display:"flex", alignItems:"center", gap:"6px", background:open?C.mintLight:C.white, border:`1.5px solid ${open?C.mint:C.border}`, color:C.text, padding:"7px 12px", borderRadius:"8px", fontSize:"12px", fontWeight:"700", cursor:"pointer", transition:"all 0.15s" }}>
        <span style={{ fontSize:"16px" }}>{current.flag}</span>
        <span>{current.native}</span>
        <span style={{ fontSize:"9px", color:C.muted }}>{open?"▲":"▼"}</span>
      </button>

      {open && (
        <div style={{ position:"absolute", top:"calc(100% + 6px)", right:0, background:C.white, border:`1px solid ${C.border}`, borderRadius:"14px", boxShadow:"0 12px 40px rgba(0,0,0,0.15)", zIndex:999, width:"340px", overflow:"hidden" }}>
          {/* Header */}
          <div style={{ padding:"12px 14px", borderBottom:`1px solid ${C.dim}`, background:"linear-gradient(135deg,#0D2818,#1A4A2E)" }}>
            <div style={{ fontSize:"10px", letterSpacing:"3px", color:"rgba(255,255,255,0.5)", fontWeight:"700", marginBottom:"8px" }}>SELECT LANGUAGE AND MARKET</div>
            <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search language..."
              style={{ width:"100%", background:"rgba(255,255,255,0.1)", border:"1px solid rgba(255,255,255,0.15)", color:"#fff", padding:"7px 10px", borderRadius:"8px", fontSize:"12px", boxSizing:"border-box" }}/>
          </div>

          {/* Region filter pills */}
          <div style={{ display:"flex", gap:"4px", padding:"8px 10px", overflowX:"auto", borderBottom:`1px solid ${C.dim}`, flexShrink:0 }}>
            {["All","North America","Latin America / Spain","Africa","Asia","Europe","Middle East","Pacific","Caribbean / Diaspora"].map(r=>(
              <button key={r} onClick={()=>setRegionFilter(r)}
                style={{ background:regionFilter===r?GRAD.hero:"transparent", color:regionFilter===r?"#fff":C.muted, border:`1px solid ${regionFilter===r?C.mint:C.dim}`, padding:"3px 9px", borderRadius:"20px", fontSize:"9px", fontWeight:"700", cursor:"pointer", whiteSpace:"nowrap" }}>
                {r==="All"?"All Regions":r}
              </button>
            ))}
          </div>

          {/* Language list */}
          <div style={{ maxHeight:"380px", overflowY:"auto" }}>
            {filtered.map(l=>(
              <button key={l.code} onClick={()=>{ setLang(l.code); setOpen(false); setSearch(""); setRegionFilter("All"); }}
                style={{ display:"flex", alignItems:"center", gap:"10px", width:"100%", padding:"10px 14px", background:lang===l.code?C.mintLight:"transparent", border:"none", cursor:"pointer", textAlign:"left", borderBottom:`1px solid ${C.dim}`, transition:"background 0.1s" }}
                onMouseEnter={e=>{ if(lang!==l.code) e.currentTarget.style.background=C.bg; }}
                onMouseLeave={e=>{ if(lang!==l.code) e.currentTarget.style.background="transparent"; }}>
                <span style={{ fontSize:"20px", flexShrink:0 }}>{l.flag}</span>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                    <span style={{ fontSize:"13px", color:lang===l.code?C.mintDark:C.text, fontWeight:lang===l.code?"800":"600" }}>{l.native}</span>
                    {l.marketSize && <span style={{ fontSize:"10px", color:C.mint, fontWeight:"700" }}>{l.marketSize}</span>}
                  </div>
                  <div style={{ display:"flex", gap:"6px", alignItems:"center", marginTop:"2px" }}>
                    <span style={{ fontSize:"10px", color:C.muted }}>{l.name}</span>
                    {l.region && <span style={{ fontSize:"9px", color:"rgba(255,255,255,0.0)", background:C.dim, padding:"1px 6px", borderRadius:"10px", color:C.muted }}>{l.region}</span>}
                    {l.dir==="rtl" && <span style={{ fontSize:"9px", color:C.muted, background:"#FEF2F2", padding:"1px 5px", borderRadius:"4px", color:"#DC2626", fontWeight:"700" }}>RTL</span>}
                  </div>
                </div>
                {lang===l.code && <span style={{ color:C.mint, fontWeight:"900", fontSize:"14px", flexShrink:0 }}>&#10003;</span>}
              </button>
            ))}
            {filtered.length === 0 && (
              <div style={{ padding:"20px", textAlign:"center", color:C.muted, fontSize:"13px" }}>No languages match your search</div>
            )}
          </div>

          {/* Footer */}
          <div style={{ padding:"10px 14px", borderTop:`1px solid ${C.dim}`, background:C.bg }}>
            <div style={{ fontSize:"10px", color:C.muted }}>
              {LANGUAGES.length} languages - {LANGUAGES.reduce((s,l)=>s+(l.marketSize?parseInt(l.marketSize.replace(/[$B]/g,""))||0:0),0)}B+ total beauty market
            </div>
          </div>
        </div>
      )}
    </div>
  );
}



