// -- API -----------------------------------------------------------------------
async function callClaude(messages, system) {
  const res = await fetch(CLAUDE_PROXY_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model: "claude-sonnet-4-20250514", max_tokens: 1000, system, messages }),
  });
  const data = await res.json();
  return data.content?.map(b => b.text || "").join("") || "";
}

// -- Shared UI Atoms -----------------------------------------------------------
function Pill({ children, color = C.mint }) {
  return (
    <span style={{ background: color + "18", color, fontSize: "10px", padding: "3px 10px", borderRadius: "20px", border: `1px solid ${color}44`, whiteSpace: "nowrap", fontWeight: "600" }}>
      {children}
    </span>
  );
}

function Avatar({ initials, size = 48, tier }) {
  const t = SKILL_TIERS[tier];
  return (
    <div style={{ width: size, height: size, borderRadius: "50%", background: t.bg, border: `2px solid ${t.border}`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: size * 0.3, color: t.color, fontWeight: "800", flexShrink: 0 }}>
      {initials}
    </div>
  );
}

function TierBadge({ tier }) {
  const t = SKILL_TIERS[tier];
  return (
    <span style={{ background: t.bg, color: t.color, fontSize: "10px", padding: "3px 10px", borderRadius: "20px", border: `1px solid ${t.border}`, fontWeight: "700", letterSpacing: "0.3px" }}>
      {t.icon} {t.label}
    </span>
  );
}

function Stars({ rating }) {
  return (
    <span style={{ color: C.gold, fontSize: "13px" }}>
      {"★".repeat(Math.floor(rating))}<span style={{ color: C.dim }}>{"★".repeat(5 - Math.floor(rating))}</span>
      <span style={{ color: C.muted, fontSize: "11px", marginLeft: "4px" }}>{rating}</span>
    </span>
  );
}

function SideBtn({ label, active, onClick }) {
  return (
    <button onClick={onClick} style={{ display: "block", width: "100%", textAlign: "left", background: active ? C.mintLight : "transparent", border: "none", color: active ? C.mintDark : C.muted, padding: "7px 10px", borderRadius: "6px", fontSize: "12px", cursor: "pointer", marginBottom: "1px", fontWeight: active ? "700" : "400" }}>
      {label}
    </button>
  );
}

function InputField({ value, onChange, onKeyDown, placeholder, multiline, rows = 3 }) {
  const s = { width: "100%", background: C.bg, border: `1.5px solid ${C.border}`, color: C.text, padding: "10px 12px", borderRadius: "8px", fontSize: "13px", boxSizing: "border-box", outline: "none", resize: multiline ? "vertical" : undefined };
  return multiline
    ? <textarea value={value} onChange={onChange} rows={rows} placeholder={placeholder} style={s} />
    : <input value={value} onChange={onChange} onKeyDown={onKeyDown} placeholder={placeholder} style={s} />;
}

function openMaps(pro) {
  window.open(`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(pro.address)}`, "_blank");
}

// -- Booking Modal -------------------------------------------------------------
function BookingModal({ pro, isConsultation, onClose, onBook }) {
  const [step, setStep] = useState(1);
  const [day, setDay] = useState(null);
  const [time, setTime] = useState(null);
  const [service, setService] = useState(Object.keys(pro.price).filter(k => k !== "consultation")[0] || "");
  const [note, setNote] = useState("");
  const [aiTip, setAiTip] = useState("");
  const [aiLoading, setAiLoading] = useState(false);

  const slots = day ? (pro.availability[day] || []) : [];
  const price = isConsultation ? (pro.price.consultation || 0) : (pro.price[service] || 0);

  async function getAiTip() {
    setAiLoading(true);
    const r = await callClaude([{ role: "user", content: `Booking a ${isConsultation ? "consultation" : service} with ${pro.name} (${pro.tier}, ${pro.specialty.join(", ")}). Give 2-3 appointment prep tips.` }], "You are a hair care AI. Be concise, 60 words max.");
    setAiTip(r);
    setAiLoading(false);
  }

  const overlay = { position: "fixed", inset: 0, background: "rgba(20,80,50,0.28)", zIndex: 500, display: "flex", alignItems: "center", justifyContent: "center", padding: "16px" };
  const modal = { background: C.white, borderRadius: "20px", width: "100%", maxWidth: "460px", maxHeight: "90vh", overflowY: "auto", boxShadow: "0 20px 60px rgba(0,0,0,0.12)", border: `1px solid ${C.border}` };

  return (
    <div style={overlay}>
      <div style={modal}>
        <div style={{ height: "5px", background: GRAD.hero, borderRadius: "20px 20px 0 0" }} />
        <div style={{ padding: "20px 24px", borderBottom: `1px solid ${C.dim}`, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <div style={{ fontSize: "10px", letterSpacing: "3px", color: C.mint, fontWeight: "700", marginBottom: "2px" }}>{isConsultation ? "FREE CONSULTATION" : "BOOK APPOINTMENT"}</div>
            <div style={{ fontSize: "18px", color: C.text, fontWeight: "800" }}>{pro.name}</div>
          </div>
          <button onClick={onClose} style={{ background: "none", border: "none", color: C.muted, fontSize: "24px", cursor: "pointer", lineHeight: 1 }}>×</button>
        </div>
        <div style={{ padding: "20px 24px", display: "flex", flexDirection: "column", gap: "16px" }}>
          {!isConsultation && (
            <div>
              <div style={{ fontSize: "10px", letterSpacing: "2px", color: C.muted, fontWeight: "700", marginBottom: "8px" }}>SERVICE</div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: "8px" }}>
                {Object.entries(pro.price).filter(([k]) => k !== "consultation").map(([svc, p]) => (
                  <button key={svc} onClick={() => setService(svc)} style={{ background: service === svc ? C.mint : C.bg, border: `1.5px solid ${service === svc ? C.mint : C.border}`, color: service === svc ? "#fff" : C.sub, padding: "8px 16px", borderRadius: "20px", fontSize: "12px", cursor: "pointer", fontWeight: "600" }}>
                    {svc.charAt(0).toUpperCase() + svc.slice(1)}  -  ${p}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div>
            <div style={{ fontSize: "10px", letterSpacing: "2px", color: C.muted, fontWeight: "700", marginBottom: "8px" }}>SELECT DAY</div>
            <div style={{ display: "flex", gap: "6px", flexWrap: "wrap" }}>
              {DAYS.map(d => {
                const avail = pro.availability[d]?.length > 0;
                const sel = day === d;
                return (
                  <button key={d} disabled={!avail} onClick={() => { setDay(d); setTime(null); setStep(2); }}
                    style={{ padding: "8px 10px", borderRadius: "10px", border: `1.5px solid ${sel ? C.mint : avail ? C.border : C.dim}`, background: sel ? C.mint : avail ? C.bg : "#F8F8F8", color: sel ? "#fff" : avail ? C.text : C.muted, fontSize: "11px", cursor: avail ? "pointer" : "not-allowed", fontWeight: sel ? "700" : "400", minWidth: "44px", textAlign: "center" }}>
                    <div>{d}</div>
                    {avail && <div style={{ fontSize: "9px", marginTop: "2px", opacity: 0.8 }}>{pro.availability[d].length}✓</div>}
                  </button>
                );
              })}
            </div>
          </div>

          {step >= 2 && day && (
            <div>
              <div style={{ fontSize: "10px", letterSpacing: "2px", color: C.muted, fontWeight: "700", marginBottom: "8px" }}>TIME  -  {day}</div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: "6px" }}>
                {slots.map(t => (
                  <button key={t} onClick={() => { setTime(t); setStep(3); }}
                    style={{ padding: "7px 12px", borderRadius: "8px", border: `1.5px solid ${time === t ? C.teal : C.border}`, background: time === t ? C.teal : C.bg, color: time === t ? "#fff" : C.sub, fontSize: "12px", cursor: "pointer", fontWeight: time === t ? "700" : "400" }}>
                    {t}
                  </button>
                ))}
              </div>
            </div>
          )}

          {step >= 3 && time && (
            <>
              <div>
                <div style={{ fontSize: "10px", letterSpacing: "2px", color: C.muted, fontWeight: "700", marginBottom: "6px" }}>NOTES FOR STYLIST</div>
                <InputField value={note} onChange={e => setNote(e.target.value)} placeholder="Hair goals, concerns, inspo..." multiline rows={3} />
              </div>

              <button onClick={getAiTip} disabled={aiLoading}
                style={{ background: aiLoading ? C.dim : C.mintLight, border: `1.5px solid ${C.mint}`, color: C.mintDark, padding: "10px", borderRadius: "10px", fontSize: "12px", cursor: "pointer", fontWeight: "700" }}>
                {aiLoading ? "✦ Getting AI prep tips..." : "✦ Get AI Prep Tips (free)"}
              </button>
              {aiTip && (
                <div style={{ background: C.mintLight, border: `1px solid ${C.border}`, borderRadius: "10px", padding: "13px", fontSize: "13px", color: C.sub, lineHeight: "1.7" }}>{aiTip}</div>
              )}

              <div style={{ background: C.bg, border: `1px solid ${C.border}`, borderRadius: "12px", padding: "14px" }}>
                <div style={{ fontSize: "10px", letterSpacing: "3px", color: C.muted, fontWeight: "700", marginBottom: "10px" }}>BOOKING SUMMARY</div>
                {[["Pro", pro.name], ["Service", isConsultation ? "Free Consultation" : service], ["Day", day], ["Time", time], ["Price", price === 0 ? "FREE" : `$${price}`]].map(([l, v]) => (
                  <div key={l} style={{ display: "flex", justifyContent: "space-between", padding: "5px 0", borderBottom: `1px solid ${C.dim}` }}>
                    <span style={{ fontSize: "12px", color: C.muted }}>{l}</span>
                    <span style={{ fontSize: "13px", color: l === "Price" ? C.amber : C.text, fontWeight: l === "Price" ? "800" : "600" }}>{v}</span>
                  </div>
                ))}
              </div>

              <button onClick={() => { onBook({ id: Date.now(), proId: pro.id, proName: pro.name, day, time, service: isConsultation ? "Consultation" : service, price, note, type: isConsultation ? "consultation" : "appointment" }); onClose(); }}
                style={{ background: GRAD.hero, color: "#fff", border: "none", padding: "13px", borderRadius: "10px", fontSize: "14px", fontWeight: "800", cursor: "pointer", letterSpacing: "0.5px" }}>
                ✓ Confirm Booking
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

// -- Pro Detail Panel ----------------------------------------------------------
