async function callClaudeSimple(prompt, sys) {
  const res = await fetch(CLAUDE_PROXY_URL,{
    method:"POST", headers:{"Content-Type":"application/json"},
    body: JSON.stringify({ model:"claude-sonnet-4-20250514", max_tokens:600, system:sys||"You are an expert hair salon AI assistant. Be concise and professional.", messages:[{role:"user",content:prompt}] })
  });
  const d = await res.json();
  return d.content?.map(b=>b.text||"").join("")||"";
}

function ClientsTab() {
  const [clients, setClients] = useState(SAMPLE_CLIENTS);
  const [selected, setSelected] = useState(null);
  const [search, setSearch] = useState("");
  const [filterStatus, setFilterStatus] = useState("all");
  const [filterTag, setFilterTag] = useState("all");
  const [showAddForm, setShowAddForm] = useState(false);
  const [aiNote, setAiNote] = useState(""); const [aiLoading, setAiLoading] = useState(false);
  const [newClient, setNewClient] = useState({ name:"", phone:"", email:"", hairType:"", stylist:"", notes:"", tags:"" });
  const [editNote, setEditNote] = useState("");
  const [showNoteEdit, setShowNoteEdit] = useState(false);

  const allTags = [...new Set(clients.flatMap(c=>c.tags))];
  const filtered = clients.filter(c => {
    if (filterStatus!=="all" && c.status!==filterStatus) return false;
    if (filterTag!=="all" && !c.tags.includes(filterTag)) return false;
    if (search && !c.name.toLowerCase().includes(search.toLowerCase()) && !c.phone.includes(search)) return false;
    return true;
  });

  const stats = {
    total: clients.length,
    active: clients.filter(c=>c.status==="active").length,
    inactive: clients.filter(c=>c.status==="inactive").length,
    totalRevenue: clients.reduce((s,c)=>s+c.totalSpent,0),
    avgSpend: Math.round(clients.reduce((s,c)=>s+c.totalSpent,0)/clients.length),
    vip: clients.filter(c=>c.tags.includes("VIP")).length,
  };

  async function getAIInsight(client) {
    setAiLoading(true); setAiNote("");
    const r = await callClaudeSimple(
      `Client: ${client.name}, hair: ${client.hairType}, ${client.visits} visits, $${client.totalSpent} spent, last: ${client.lastVisit}, fav styles: ${client.favoriteStyles.join(", ")}, notes: ${client.notes}. Give 2 retention tips and 1 upsell.`,
      "You are a salon business AI. Give actionable specific advice. Under 120 words."
    );
    setAiNote(r); setAiLoading(false);
  }

  function addClient() {
    const colors = ["#FF6B6B","#4ECDC4","#A78BFA","#FCD34D","#34D399","#F59E0B"];
    setClients(prev=>[...prev,{
      ...newClient, id:Date.now(),
      avatar: newClient.name.split(" ").map(w=>w[0]).join("").slice(0,2).toUpperCase(),
      color: colors[Math.floor(Math.random()*colors.length)],
      lastVisit: new Date().toISOString().split("T")[0],
      nextAppt:null, totalSpent:0, visits:0, status:"active",
      tags: newClient.tags.split(",").map(t=>t.trim()).filter(Boolean),
      favoriteStyles:[]
    }]);
    setNewClient({name:"",phone:"",email:"",hairType:"",stylist:"",notes:"",tags:""});
    setShowAddForm(false);
  }

  const IS = { width:"100%", background:C.bg, border:`1.5px solid ${C.border}`, color:C.text, padding:"9px 11px", borderRadius:"8px", fontSize:"13px", boxSizing:"border-box" };
  const LS = { display:"block", fontSize:"10px", letterSpacing:"2px", color:C.muted, fontWeight:"700", marginBottom:"4px" };

  return (
    <div style={{flex:1,display:"flex",overflow:"hidden",background:C.bg}}>
      <aside style={{width:"210px",minWidth:"210px",background:C.white,borderRight:`1px solid ${C.border}`,display:"flex",flexDirection:"column",overflowY:"auto"}}>
        <div style={{padding:"12px",borderBottom:`1px solid ${C.dim}`}}>
          <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search clients..." style={{...IS,padding:"8px 10px",fontSize:"12px"}}/>
        </div>
        <div style={{padding:"10px 12px",borderBottom:`1px solid ${C.dim}`}}>
          <div style={{fontSize:"9px",letterSpacing:"3px",color:C.muted,fontWeight:"700",marginBottom:"6px"}}>STATUS</div>
          {[["all","All"],["active","Active"],["inactive","Inactive"]].map(([v,l])=>(
            <button key={v} onClick={()=>setFilterStatus(v)} style={{display:"block",width:"100%",textAlign:"left",background:filterStatus===v?C.mintLight:"transparent",border:"none",color:filterStatus===v?C.mintDark:C.muted,padding:"6px 8px",borderRadius:"6px",fontSize:"12px",cursor:"pointer",fontWeight:filterStatus===v?"700":"400",marginBottom:"1px"}}>{l}</button>
          ))}
        </div>
        <div style={{padding:"10px 12px",flex:1,overflowY:"auto"}}>
          <div style={{fontSize:"9px",letterSpacing:"3px",color:C.muted,fontWeight:"700",marginBottom:"6px"}}>TAGS</div>
          {["all",...allTags].map(t=>(
            <button key={t} onClick={()=>setFilterTag(t)} style={{display:"block",width:"100%",textAlign:"left",background:filterTag===t?C.mintLight:"transparent",border:"none",color:filterTag===t?C.mintDark:C.muted,padding:"6px 8px",borderRadius:"6px",fontSize:"12px",cursor:"pointer",fontWeight:filterTag===t?"700":"400",marginBottom:"1px"}}>{t==="all"?"All Tags":t}</button>
          ))}
        </div>
        <div style={{padding:"12px",borderTop:`1px solid ${C.dim}`}}>
          <button onClick={()=>setShowAddForm(true)} style={{width:"100%",background:GRAD.hero,color:"#fff",border:"none",padding:"10px",borderRadius:"10px",fontSize:"13px",fontWeight:"800",cursor:"pointer"}}>+ New Client</button>
        </div>
      </aside>

      <div style={{flex:1,display:"flex",overflow:"hidden"}}>
        <div style={{flex:1,overflowY:"auto",padding:"20px"}}>
          <div style={{display:"grid",gridTemplateColumns:"repeat(6,1fr)",gap:"10px",marginBottom:"20px"}}>
            {[["Total",stats.total,"👥",C.mint],["Active",stats.active,"✓",C.teal],["Inactive",stats.inactive,"–",C.muted],["Revenue","$"+stats.totalRevenue.toLocaleString(),"💰",C.amber],["Avg Spend","$"+stats.avgSpend,"📊",C.gold],["VIP",stats.vip,"⭐",C.amber]].map(([l,v,ic,color])=>(
              <div key={l} style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"12px",padding:"12px",textAlign:"center"}}>
                <div style={{fontSize:"16px",marginBottom:"2px"}}>{ic}</div>
                <div style={{fontSize:"18px",fontWeight:"900",color}}>{v}</div>
                <div style={{fontSize:"10px",color:C.muted,fontWeight:"600"}}>{l}</div>
              </div>
            ))}
          </div>
          <div style={{fontSize:"13px",color:C.muted,fontWeight:"600",marginBottom:"12px"}}>{filtered.length} clients</div>
          <div style={{display:"flex",flexDirection:"column",gap:"10px"}}>
            {filtered.map(client=>(
              <div key={client.id} onClick={()=>setSelected(client)}
                style={{background:C.white,border:`1.5px solid ${selected?.id===client.id?C.mint:C.border}`,borderRadius:"14px",padding:"16px",cursor:"pointer",transition:"all 0.2s",boxShadow:selected?.id===client.id?"0 4px 16px rgba(39,174,120,0.15)":"0 2px 6px rgba(0,0,0,0.05)"}}
                onMouseEnter={e=>{e.currentTarget.style.transform="translateX(3px)";e.currentTarget.style.borderColor=C.mint;}}
                onMouseLeave={e=>{e.currentTarget.style.transform="translateX(0)";e.currentTarget.style.borderColor=selected?.id===client.id?C.mint:C.border;}}>
                <div style={{display:"flex",gap:"14px",alignItems:"center"}}>
                  <div style={{width:"48px",height:"48px",borderRadius:"50%",background:client.color+"22",border:`2px solid ${client.color}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:"14px",fontWeight:"800",color:client.color,flexShrink:0}}>{client.avatar}</div>
                  <div style={{flex:1}}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}>
                      <div>
                        <div style={{fontSize:"15px",fontWeight:"800",color:C.text}}>{client.name}</div>
                        <div style={{fontSize:"11px",color:C.muted}}>{client.phone} · {client.hairType}</div>
                      </div>
                      <div style={{textAlign:"right"}}>
                        <div style={{fontSize:"15px",fontWeight:"900",color:C.amber}}>${client.totalSpent}</div>
                        <div style={{fontSize:"10px",color:C.muted}}>{client.visits} visits</div>
                      </div>
                    </div>
                    <div style={{display:"flex",gap:"5px",flexWrap:"wrap",marginTop:"8px"}}>
                      <span style={{background:client.status==="active"?C.mintLight:"#F3F4F6",color:client.status==="active"?C.mintDark:C.muted,fontSize:"10px",padding:"2px 8px",borderRadius:"20px",fontWeight:"700"}}>{client.status==="active"?"Active":"Inactive"}</span>
                      {client.tags.slice(0,2).map(tag=><span key={tag} style={{background:"#F3F4F6",color:C.sub,fontSize:"10px",padding:"2px 8px",borderRadius:"20px"}}>#{tag}</span>)}
                      {client.nextAppt&&<span style={{marginLeft:"auto",fontSize:"11px",color:C.teal,fontWeight:"700"}}>Next: {client.nextAppt}</span>}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {selected && (
          <aside style={{width:"300px",minWidth:"300px",background:C.white,borderLeft:`1px solid ${C.border}`,overflowY:"auto"}}>
            <div style={{height:"5px",background:`linear-gradient(90deg,${selected.color},${selected.color}88)`}} />
            <div style={{padding:"18px"}}>
              <div style={{display:"flex",justifyContent:"space-between",marginBottom:"14px"}}>
                <div style={{display:"flex",gap:"12px",alignItems:"center"}}>
                  <div style={{width:"50px",height:"50px",borderRadius:"50%",background:selected.color+"22",border:`2px solid ${selected.color}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:"15px",fontWeight:"900",color:selected.color}}>{selected.avatar}</div>
                  <div>
                    <div style={{fontSize:"16px",fontWeight:"900",color:C.text}}>{selected.name}</div>
                    <span style={{background:selected.status==="active"?C.mintLight:"#F3F4F6",color:selected.status==="active"?C.mint:C.muted,fontSize:"10px",padding:"2px 9px",borderRadius:"20px",fontWeight:"700"}}>{selected.status}</span>
                  </div>
                </div>
                <button onClick={()=>setSelected(null)} style={{background:"none",border:"none",color:C.muted,fontSize:"22px",cursor:"pointer"}}>×</button>
              </div>
              <div style={{background:C.bg,borderRadius:"10px",padding:"12px",marginBottom:"12px"}}>
                <div style={{fontSize:"9px",letterSpacing:"3px",color:C.muted,fontWeight:"700",marginBottom:"8px"}}>CONTACT</div>
                {[["📞",selected.phone],["✉",selected.email],["💇",selected.stylist]].map(([ic,v])=>(
                  <div key={ic} style={{display:"flex",gap:"8px",marginBottom:"5px",fontSize:"12px",color:C.sub}}><span>{ic}</span>{v}</div>
                ))}
              </div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:"8px",marginBottom:"12px"}}>
                {[["Visits",selected.visits,"👥"],["Spent","$"+selected.totalSpent,"💰"],["Last",(selected.lastVisit||"–").slice(5)||"–","📅"]].map(([l,v,ic])=>(
                  <div key={l} style={{background:C.bg,borderRadius:"10px",padding:"10px",textAlign:"center"}}>
                    <div style={{fontSize:"13px"}}>{ic}</div>
                    <div style={{fontSize:"14px",fontWeight:"900",color:C.text}}>{v}</div>
                    <div style={{fontSize:"9px",color:C.muted}}>{l}</div>
                  </div>
                ))}
              </div>
              {selected.favoriteStyles.length>0&&(
                <div style={{marginBottom:"12px"}}>
                  <div style={{fontSize:"9px",letterSpacing:"3px",color:C.muted,fontWeight:"700",marginBottom:"7px"}}>FAVORITE STYLES</div>
                  <div style={{display:"flex",flexWrap:"wrap",gap:"5px"}}>
                    {selected.favoriteStyles.map(s=><span key={s} style={{background:C.bg,color:C.sub,fontSize:"11px",padding:"4px 10px",borderRadius:"20px",border:`1px solid ${C.border}`}}>{s}</span>)}
                  </div>
                </div>
              )}
              <div style={{marginBottom:"12px"}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:"7px"}}>
                  <div style={{fontSize:"9px",letterSpacing:"3px",color:C.muted,fontWeight:"700"}}>PRO NOTES</div>
                  <button onClick={()=>{setEditNote(selected.notes);setShowNoteEdit(true);}} style={{background:"none",border:`1px solid ${C.border}`,color:C.muted,padding:"3px 8px",borderRadius:"6px",fontSize:"10px",cursor:"pointer"}}>Edit</button>
                </div>
                <div style={{background:C.bg,borderRadius:"10px",padding:"11px",fontSize:"12px",color:C.sub,lineHeight:"1.6"}}>{selected.notes||"No notes yet."}</div>
              </div>
              <div style={{display:"flex",gap:"8px",marginBottom:"14px"}}>
                <button onClick={()=>setSelected(s=>({...s,status:s.status==="active"?"inactive":"active"}))} style={{flex:1,background:"#F9F9F9",border:`1px solid ${C.border}`,color:C.sub,padding:"9px",borderRadius:"8px",fontSize:"12px",fontWeight:"700",cursor:"pointer"}}>
                  {selected.status==="active"?"Mark Inactive":"Mark Active"}
                </button>
                <button onClick={()=>setSelected(s=>({...s,visits:s.visits+1,lastVisit:new Date().toISOString().split("T")[0]}))} style={{flex:1,background:GRAD.hero,color:"#fff",border:"none",padding:"9px",borderRadius:"8px",fontSize:"12px",fontWeight:"700",cursor:"pointer"}}>Log Visit</button>
              </div>
              <div style={{borderTop:`1px solid ${C.dim}`,paddingTop:"14px"}}>
                <div style={{display:"flex",alignItems:"center",gap:"8px",marginBottom:"10px"}}><div style={{fontSize:"10px",letterSpacing:"3px",color:C.mint,fontWeight:"700"}}>AI CLIENT INSIGHT</div><ClaudeBadge size="sm" /></div>
                <button onClick={()=>getAIInsight(selected)} disabled={aiLoading} style={{width:"100%",background:C.mintLight,border:`1.5px solid ${C.mint}`,color:C.mintDark,padding:"9px",borderRadius:"8px",fontSize:"12px",fontWeight:"700",cursor:"pointer"}}>
                  {aiLoading?"Analyzing...":"Get Retention & Upsell Tips"}
                </button>
                {aiNote&&<div style={{marginTop:"10px",background:C.bg,borderRadius:"8px",padding:"12px",fontSize:"12px",color:C.sub,lineHeight:"1.7"}}>{aiNote}</div>}
              </div>
            </div>
          </aside>
        )}
      </div>

      {showAddForm&&(
        <div style={{position:"fixed",inset:0,background:"rgba(20,80,50,0.28)",zIndex:400,display:"flex",alignItems:"center",justifyContent:"center",padding:"16px"}}>
          <div style={{background:C.white,borderRadius:"20px",width:"100%",maxWidth:"480px",maxHeight:"90vh",overflowY:"auto",boxShadow:"0 20px 60px rgba(0,0,0,0.12)",border:`1px solid ${C.border}`}}>
            <div style={{height:"5px",background:GRAD.hero,borderRadius:"20px 20px 0 0"}} />
            <div style={{padding:"20px 24px",borderBottom:`1px solid ${C.dim}`,display:"flex",justifyContent:"space-between"}}>
              <div style={{fontSize:"17px",fontWeight:"900",color:C.text}}>New Client</div>
              <button onClick={()=>setShowAddForm(false)} style={{background:"none",border:"none",color:C.muted,fontSize:"22px",cursor:"pointer"}}>×</button>
            </div>
            <div style={{padding:"20px 24px",display:"flex",flexDirection:"column",gap:"12px"}}>
              {[["Full Name","name","text"],["Phone","phone","tel"],["Email","email","email"],["Hair Type","hairType","text"],["Preferred Stylist","stylist","text"]].map(([l,k,t])=>(
                <div key={k}><label style={LS}>{l.toUpperCase()}</label><input type={t} value={newClient[k]} onChange={e=>setNewClient(p=>({...p,[k]:e.target.value}))} style={IS}/></div>
              ))}
              <div><label style={LS}>NOTES</label><textarea value={newClient.notes} onChange={e=>setNewClient(p=>({...p,notes:e.target.value}))} rows={3} style={{...IS,resize:"vertical"}}/></div>
              <div><label style={LS}>TAGS</label><input value={newClient.tags} onChange={e=>setNewClient(p=>({...p,tags:e.target.value}))} placeholder="VIP, regular..." style={IS}/></div>
              <div style={{display:"flex",gap:"8px"}}>
                <button onClick={addClient} style={{flex:1,background:GRAD.hero,color:"#fff",border:"none",padding:"12px",borderRadius:"10px",fontSize:"13px",fontWeight:"800",cursor:"pointer"}}>Add Client</button>
                <button onClick={()=>setShowAddForm(false)} style={{background:C.bg,color:C.muted,border:`1px solid ${C.border}`,padding:"12px 18px",borderRadius:"10px",fontSize:"13px",cursor:"pointer"}}>Cancel</button>
              </div>
            </div>
          </div>
        </div>
      )}
      {showNoteEdit&&(
        <div style={{position:"fixed",inset:0,background:"rgba(20,80,50,0.28)",zIndex:400,display:"flex",alignItems:"center",justifyContent:"center",padding:"16px"}}>
          <div style={{background:C.white,borderRadius:"16px",padding:"24px",width:"100%",maxWidth:"420px"}}>
            <div style={{fontSize:"16px",fontWeight:"800",color:C.text,marginBottom:"12px"}}>Edit Notes</div>
            <textarea value={editNote} onChange={e=>setEditNote(e.target.value)} rows={5} style={{...IS,resize:"vertical",marginBottom:"12px"}}/>
            <div style={{display:"flex",gap:"8px"}}>
              <button onClick={()=>{setSelected(s=>({...s,notes:editNote}));setClients(prev=>prev.map(c=>c.id===selected.id?{...c,notes:editNote}:c));setShowNoteEdit(false);}} style={{flex:1,background:GRAD.hero,color:"#fff",border:"none",padding:"11px",borderRadius:"10px",fontSize:"13px",fontWeight:"800",cursor:"pointer"}}>Save</button>
              <button onClick={()=>setShowNoteEdit(false)} style={{background:C.bg,color:C.muted,border:`1px solid ${C.border}`,padding:"11px 18px",borderRadius:"10px",fontSize:"13px",cursor:"pointer"}}>Cancel</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

