function PaymentsTab() {
  const [transactions, setTransactions] = useState(SAMPLE_TRANSACTIONS);
  const [view, setView] = useState("dashboard");
  const [method, setMethod] = useState("card");
  const [amount, setAmount] = useState("");
  const [tip, setTip] = useState("");
  const [tipPct, setTipPct] = useState(null);
  const [service, setService] = useState("");
  const [clientName, setClientName] = useState("");
  const [processing, setProcessing] = useState(false);
  const [success, setSuccess] = useState(false);
  const [filterMethod, setFilterMethod] = useState("all");
  const [aiInsight, setAiInsight] = useState(""); const [aiLoading, setAiLoading] = useState(false);

  const paid = transactions.filter(t=>t.status==="paid");
  const totalRevenue = paid.reduce((s,t)=>s+t.amount+t.tip,0);
  const totalTips = paid.reduce((s,t)=>s+t.tip,0);
  const avgTicket = paid.length ? Math.round(paid.reduce((s,t)=>s+t.amount,0)/paid.length) : 0;
  const methodCounts = {};
  paid.forEach(t=>{ methodCounts[t.method]=(methodCounts[t.method]||0)+1; });

  function applyTipPct(pct) {
    setTipPct(pct);
    if(amount) setTip(String(Math.round(parseFloat(amount)*pct/100)));
  }

  async function processPayment() {
    if(!amount||!service||!clientName) return;
    setProcessing(true);
    await new Promise(r=>setTimeout(r,1800));
    setTransactions(prev=>[{id:Date.now(),client:clientName,service,amount:parseFloat(amount)||0,tip:parseFloat(tip)||0,method,date:new Date().toISOString().split("T")[0],status:"paid"},...prev]);
    setProcessing(false); setSuccess(true);
    setTimeout(()=>{setSuccess(false);setAmount("");setTip("");setService("");setClientName("");setTipPct(null);},3000);
  }

  async function getRevenueInsight() {
    setAiLoading(true); setAiInsight("");
    const r = await callClaudeSimple(
      `Salon revenue: Total $${totalRevenue}, tips $${totalTips}, avg ticket $${avgTicket}, ${paid.length} transactions. Give 2 specific revenue growth tips.`,
      "You are a salon business AI. Give actionable revenue advice. Under 100 words."
    );
    setAiInsight(r); setAiLoading(false);
  }

  const IS = {width:"100%",background:C.bg,border:`1.5px solid ${C.border}`,color:C.text,padding:"9px 11px",borderRadius:"8px",fontSize:"13px",boxSizing:"border-box"};
  const filteredTx = filterMethod==="all" ? transactions : transactions.filter(t=>t.method===filterMethod);
  const NAV = [["dashboard","Dashboard"],["checkout","Checkout"],["history","History"],["invoices","Invoices"]];

  return (
    <div style={{flex:1,display:"flex",flexDirection:"column",overflow:"hidden",background:C.bg}}>
      <div style={{background:C.white,borderBottom:`1px solid ${C.border}`,padding:"0 20px",display:"flex",gap:"2px",flexShrink:0}}>
        {NAV.map(([v,l])=>(
          <button key={v} onClick={()=>setView(v)} style={{background:"none",border:"none",borderBottom:`3px solid ${view===v?C.mint:"transparent"}`,color:view===v?C.mint:C.muted,padding:"13px 14px 10px",fontSize:"12px",cursor:"pointer",fontWeight:view===v?"800":"500",whiteSpace:"nowrap"}}>{l}</button>
        ))}
      </div>
      <div style={{flex:1,overflowY:"auto",padding:"20px"}}>

        {view==="dashboard" && (
          <div>
            <div style={{fontSize:"22px",fontWeight:"900",color:C.text,marginBottom:"16px"}}>Revenue Dashboard</div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:"12px",marginBottom:"20px"}}>
              {[["Revenue","$"+totalRevenue.toLocaleString(),"💰",C.amber],["Tips","$"+totalTips.toLocaleString(),"⭐",C.gold],["Avg Ticket","$"+avgTicket,"📊",C.mint],["Transactions",paid.length,"🧾",C.teal]].map(([l,v,ic,color])=>(
                <div key={l} style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"14px",padding:"18px",textAlign:"center"}}>
                  <div style={{fontSize:"24px",marginBottom:"6px"}}>{ic}</div>
                  <div style={{fontSize:"24px",fontWeight:"900",color}}>{v}</div>
                  <div style={{fontSize:"11px",color:C.muted,fontWeight:"600"}}>{l}</div>
                </div>
              ))}
            </div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"16px",marginBottom:"20px"}}>
              <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"14px",padding:"18px"}}>
                <div style={{fontSize:"13px",fontWeight:"800",color:C.text,marginBottom:"14px"}}>Payment Methods</div>
                {Object.entries(methodCounts).sort((a,b)=>b[1]-a[1]).map(([m,count])=>{
                  const pm=PAYMENT_METHODS.find(p=>p.id===m);
                  const pct=Math.round(count/paid.length*100);
                  return (
                    <div key={m} style={{marginBottom:"10px"}}>
                      <div style={{display:"flex",justifyContent:"space-between",fontSize:"12px",color:C.sub,marginBottom:"4px"}}><span>{pm?.icon} {pm?.label||m}</span><span style={{fontWeight:"700"}}>{pct}%</span></div>
                      <div style={{height:"6px",background:C.dim,borderRadius:"3px",overflow:"hidden"}}><div style={{height:"100%",width:`${pct}%`,background:GRAD.hero,borderRadius:"3px"}}/></div>
                    </div>
                  );
                })}
              </div>
              <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"14px",padding:"18px"}}>
                <div style={{fontSize:"13px",fontWeight:"800",color:C.text,marginBottom:"14px"}}>Top Services</div>
                {Object.entries(paid.reduce((acc,t)=>{acc[t.service]=(acc[t.service]||0)+t.amount;return acc;},{})).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([svc,total])=>(
                  <div key={svc} style={{display:"flex",justifyContent:"space-between",padding:"6px 0",borderBottom:`1px solid ${C.dim}`,fontSize:"12px"}}>
                    <span style={{color:C.sub}}>{svc}</span><span style={{color:C.amber,fontWeight:"700"}}>${total}</span>
                  </div>
                ))}
              </div>
            </div>
            <div style={{background:"linear-gradient(135deg,#E8F8F0,#D4F0E4)",border:`1px solid ${C.border}`,borderRadius:"14px",padding:"18px"}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:"10px"}}>
                <div style={{display:"flex",alignItems:"center",gap:"8px"}}><div style={{fontSize:"13px",fontWeight:"800",color:C.text}}>AI Revenue Insights</div><ClaudeBadge size="sm" /></div>
                <button onClick={getRevenueInsight} disabled={aiLoading} style={{background:C.mint,color:"#fff",border:"none",padding:"7px 14px",borderRadius:"8px",fontSize:"12px",fontWeight:"700",cursor:"pointer"}}>{aiLoading?"Analyzing...":"Get Insights"}</button>
              </div>
              {aiInsight?<div style={{fontSize:"13px",color:C.sub,lineHeight:"1.7"}}>{aiInsight}</div>:<div style={{fontSize:"12px",color:C.muted}}>Click "Get Insights" to have Claude analyze your revenue and suggest growth strategies.</div>}
            </div>
          </div>
        )}

        {view==="checkout" && (
          <div style={{maxWidth:"500px"}}>
            <div style={{fontSize:"22px",fontWeight:"900",color:C.text,marginBottom:"16px"}}>Checkout</div>
            {success ? (
              <div style={{background:C.mintLight,border:`2px solid ${C.mint}`,borderRadius:"16px",padding:"40px",textAlign:"center"}}>
                <div style={{fontSize:"56px",marginBottom:"12px"}}>🎉</div>
                <div style={{fontSize:"22px",fontWeight:"900",color:C.mint}}>Payment Complete!</div>
                <div style={{fontSize:"14px",color:C.sub,marginTop:"6px"}}>${(parseFloat(amount||0)+parseFloat(tip||0)).toFixed(2)} via {PAYMENT_METHODS.find(p=>p.id===method)?.label}</div>
              </div>
            ) : (
              <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"16px",padding:"24px"}}>
                <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"12px",marginBottom:"16px"}}>
                  {[["Client Name",clientName,setClientName,"text"],["Service",service,setService,"text"]].map(([l,v,sv,t])=>(
                    <div key={l}><label style={{display:"block",fontSize:"10px",letterSpacing:"2px",color:C.muted,fontWeight:"700",marginBottom:"4px"}}>{l.toUpperCase()}</label>
                      <input type={t} value={v} onChange={e=>sv(e.target.value)} style={IS}/></div>
                  ))}
                </div>
                <div style={{marginBottom:"16px"}}>
                  <label style={{display:"block",fontSize:"10px",letterSpacing:"2px",color:C.muted,fontWeight:"700",marginBottom:"6px"}}>AMOUNT ($)</label>
                  <div style={{position:"relative"}}>
                    <span style={{position:"absolute",left:"12px",top:"50%",transform:"translateY(-50%)",fontSize:"18px",fontWeight:"900",color:C.mint}}>$</span>
                    <input type="number" value={amount} onChange={e=>{setAmount(e.target.value);if(tipPct)setTip(String(Math.round(parseFloat(e.target.value)*tipPct/100)));}} style={{...IS,padding:"12px 11px 12px 30px",fontSize:"20px",fontWeight:"900"}}/>
                  </div>
                </div>
                <div style={{marginBottom:"16px"}}>
                  <label style={{display:"block",fontSize:"10px",letterSpacing:"2px",color:C.muted,fontWeight:"700",marginBottom:"6px"}}>TIP</label>
                  <div style={{display:"flex",gap:"6px",marginBottom:"8px"}}>
                    {[10,15,18,20,25].map(pct=>(
                      <button key={pct} onClick={()=>applyTipPct(pct)} style={{flex:1,background:tipPct===pct?C.mint:"#F3F4F6",color:tipPct===pct?"#fff":C.sub,border:`1px solid ${tipPct===pct?C.mint:C.dim}`,padding:"8px",borderRadius:"8px",fontSize:"12px",fontWeight:"700",cursor:"pointer"}}>{pct}%</button>
                    ))}
                    <button onClick={()=>{setTipPct(null);setTip("");}} style={{flex:1,background:"#F3F4F6",color:C.muted,border:`1px solid ${C.dim}`,padding:"8px",borderRadius:"8px",fontSize:"11px",cursor:"pointer"}}>Custom</button>
                  </div>
                  <input type="number" value={tip} onChange={e=>{setTip(e.target.value);setTipPct(null);}} placeholder="Tip amount" style={IS}/>
                </div>
                {amount&&<div style={{background:C.mintLight,border:`1px solid ${C.border}`,borderRadius:"10px",padding:"14px",marginBottom:"16px",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                  <span style={{fontSize:"14px",fontWeight:"700",color:C.sub}}>Total</span>
                  <span style={{fontSize:"28px",fontWeight:"900",color:C.mint}}>${(parseFloat(amount||0)+parseFloat(tip||0)).toFixed(2)}</span>
                </div>}
                <div style={{marginBottom:"20px"}}>
                  <label style={{display:"block",fontSize:"10px",letterSpacing:"2px",color:C.muted,fontWeight:"700",marginBottom:"10px"}}>PAYMENT METHOD</label>
                  <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:"8px"}}>
                    {PAYMENT_METHODS.map(pm=>(
                      <button key={pm.id} onClick={()=>setMethod(pm.id)} style={{background:method===pm.id?C.mintLight:"#F9F9F9",border:`1.5px solid ${method===pm.id?C.mint:C.dim}`,borderRadius:"10px",padding:"10px 6px",cursor:"pointer",textAlign:"center"}}>
                        <div style={{fontSize:"18px",marginBottom:"3px"}}>{pm.icon}</div>
                        <div style={{fontSize:"9px",color:method===pm.id?C.mintDark:C.muted,fontWeight:"700"}}>{pm.label.split(" ")[0]}</div>
                      </button>
                    ))}
                  </div>
                </div>
                <button onClick={processPayment} disabled={processing||!amount||!service||!clientName}
                  style={{width:"100%",background:processing||!amount||!service||!clientName?C.dim:GRAD.hero,color:processing||!amount||!service||!clientName?C.muted:"#fff",border:"none",padding:"15px",borderRadius:"12px",fontSize:"16px",fontWeight:"900",cursor:processing||!amount||!service||!clientName?"not-allowed":"pointer"}}>
                  {processing?"Processing...":`Charge $${(parseFloat(amount||0)+parseFloat(tip||0)).toFixed(2)}`}
                </button>
              </div>
            )}
          </div>
        )}

        {view==="history" && (
          <div>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:"16px"}}>
              <div style={{fontSize:"22px",fontWeight:"900",color:C.text}}>Transaction History</div>
              <select value={filterMethod} onChange={e=>setFilterMethod(e.target.value)} style={{background:C.white,border:`1px solid ${C.border}`,color:C.text,padding:"8px 12px",borderRadius:"8px",fontSize:"12px"}}>
                <option value="all">All Methods</option>
                {PAYMENT_METHODS.map(p=><option key={p.id} value={p.id}>{p.label}</option>)}
              </select>
            </div>
            <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"14px",overflow:"hidden"}}>
              {filteredTx.map((tx,i)=>{
                const pm=PAYMENT_METHODS.find(p=>p.id===tx.method);
                return (
                  <div key={tx.id} style={{display:"grid",gridTemplateColumns:"1.5fr 1.5fr 1fr 1fr 1fr auto",gap:"10px",padding:"13px 16px",borderBottom:i<filteredTx.length-1?`1px solid ${C.dim}`:"none",alignItems:"center",background:tx.status==="pending"?"#FFFBEB":"transparent"}}>
                    <div><div style={{fontSize:"13px",fontWeight:"700",color:C.text}}>{tx.client}</div><div style={{fontSize:"10px",color:C.muted}}>{tx.date}</div></div>
                    <div style={{fontSize:"12px",color:C.sub}}>{tx.service}</div>
                    <div style={{fontSize:"14px",fontWeight:"800",color:C.text}}>${tx.amount}</div>
                    <div style={{fontSize:"13px",color:C.amber,fontWeight:"700"}}>{tx.tip?`+$${tx.tip}`:"-"}</div>
                    <div style={{fontSize:"12px",color:C.sub}}>{pm?.icon} {pm?.label||tx.method}</div>
                    <span style={{background:tx.status==="paid"?C.mintLight:"#FEF9EC",color:tx.status==="paid"?C.mint:C.amber,fontSize:"10px",padding:"3px 9px",borderRadius:"20px",fontWeight:"700"}}>{tx.status}</span>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {view==="invoices" && (
          <div style={{maxWidth:"540px"}}>
            <div style={{fontSize:"22px",fontWeight:"900",color:C.text,marginBottom:"16px"}}>Send Invoice</div>
            <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"16px",padding:"24px"}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:"20px"}}>
                <div style={{fontSize:"22px",fontWeight:"900",background:GRAD.hero,WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent"}}>Love That Idea</div>
                <div style={{fontSize:"12px",color:C.muted,textAlign:"right"}}>Invoice #{Math.floor(Date.now()/1000)%9999+1000}<br/>Date: {new Date().toLocaleDateString()}</div>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"16px",marginBottom:"16px"}}>
                <div style={{background:C.bg,borderRadius:"10px",padding:"12px"}}>
                  <div style={{fontSize:"10px",color:C.muted,fontWeight:"700",marginBottom:"6px"}}>BILL TO</div>
                  <input value={clientName} onChange={e=>setClientName(e.target.value)} placeholder="Client Name" style={{width:"100%",background:"transparent",border:"none",borderBottom:`1px solid ${C.dim}`,color:C.text,padding:"4px 0",fontSize:"13px",marginBottom:"6px",outline:"none"}}/>
                  <input placeholder="Client Email" style={{width:"100%",background:"transparent",border:"none",borderBottom:`1px solid ${C.dim}`,color:C.muted,padding:"4px 0",fontSize:"12px",outline:"none"}}/>
                </div>
                <div style={{background:C.bg,borderRadius:"10px",padding:"12px"}}>
                  <div style={{fontSize:"10px",color:C.muted,fontWeight:"700",marginBottom:"6px"}}>FROM</div>
                  <div style={{fontSize:"12px",color:C.sub,lineHeight:"1.8"}}>Love That Idea Studio<br/>123 Main St, Atlanta GA<br/>(404) 555-0100</div>
                </div>
              </div>
              {[["Service",amount||"0.00"],["Tip",tip||"0.00"]].map(([s,a],i)=>(
                <div key={i} style={{display:"flex",justifyContent:"space-between",padding:"8px 0",borderBottom:`1px solid ${C.dim}`,fontSize:"13px"}}>
                  <span style={{color:C.sub}}>{s}</span><span style={{fontWeight:"700",color:C.text}}>${parseFloat(a).toFixed(2)}</span>
                </div>
              ))}
              <div style={{display:"flex",justifyContent:"flex-end",gap:"20px",paddingTop:"12px",fontSize:"15px",fontWeight:"900",color:C.text}}>
                <span>Total</span><span style={{color:C.mint}}>${(parseFloat(amount||0)+parseFloat(tip||0)).toFixed(2)}</span>
              </div>
              <button onClick={()=>alert("Invoice sent! (demo)")} style={{width:"100%",background:GRAD.hero,color:"#fff",border:"none",padding:"12px",borderRadius:"10px",fontSize:"14px",fontWeight:"800",cursor:"pointer",marginTop:"16px"}}>
                Send Invoice via Email
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// -- Push Notifications --------------------------------------------------------
const NOTIF_TEMPLATES = [
  {id:"appt_reminder", icon:"📅", label:"Appointment Reminder",  cat:"appointment", template:"Hi {name}! Reminder: your appointment at Love That Idea is tomorrow at {time}. Reply CONFIRM or CANCEL."},
  {id:"appt_confirm",  icon:"✓",  label:"Appointment Confirmed", cat:"appointment", template:"Hi {name}! Your appointment on {date} at {time} with {stylist} is confirmed. See you soon!"},
  {id:"follow_up",     icon:"💬", label:"Post-Visit Follow Up",  cat:"retention",   template:"Hi {name}! Hope you're loving your new {style}! Book your next visit for 10% off. Reply BOOK to schedule."},
  {id:"birthday",      icon:"🎂", label:"Birthday Wish",         cat:"retention",   template:"Happy Birthday {name}! Treat yourself  -  enjoy a complimentary deep conditioning treatment this month!"},
  {id:"inactive",      icon:"👋", label:"Win-Back Message",      cat:"retention",   template:"Hey {name}, we miss you! Come back this month and enjoy 15% off any service."},
  {id:"promo",         icon:"🎉", label:"Special Promotion",     cat:"marketing",   template:"Hi {name}! Love That Idea special: {promo}. Book by {deadline} to take advantage!"},
  {id:"product",       icon:"🛍", label:"Product Recommendation", cat:"marketing",  template:"Hi {name}! Based on your {hairType} hair, we recommend {product} for between-visit care."},
  {id:"review",        icon:"⭐", label:"Review Request",        cat:"marketing",   template:"Hi {name}! If you enjoyed your {service}, we'd be so grateful for a quick 5-star review!"},
];

function NotificationsTab() {
  const { t } = useLang();
  const [view, setView] = useState("compose");
  const [selectedTemplate, setSelectedTemplate] = useState(NOTIF_TEMPLATES[0]);
  const [channel, setChannel] = useState("sms");
  const [customMsg, setCustomMsg] = useState("");
  const [useTemplate, setUseTemplate] = useState(true);
  const [schedule, setSchedule] = useState("now");
  const [scheduleDate, setScheduleDate] = useState("");
  const [scheduleTime, setScheduleTime] = useState("09:00");
  const [sent, setSent] = useState([]);
  const [sending, setSending] = useState(false);
  const [sendSuccess, setSendSuccess] = useState(false);
  const [aiMsg, setAiMsg] = useState(""); const [aiLoading, setAiLoading] = useState(false);
  const [aiPrompt, setAiPrompt] = useState("");
  const [filterCat, setFilterCat] = useState("all");
  const [permGranted, setPermGranted] = useState(false);
  const [permStatus, setPermStatus] = useState("idle");
  const [clientList, setClientList] = useState(SAMPLE_CLIENTS.map(c=>({...c,selected:false})));

  const selectedClients = clientList.filter(c=>c.selected);
  const IS = {width:"100%",background:C.bg,border:`1.5px solid ${C.border}`,color:C.text,padding:"9px 11px",borderRadius:"8px",fontSize:"13px",boxSizing:"border-box"};

  async function requestPushPermission() {
    setPermStatus("requesting");
    if (typeof window !== "undefined" && "Notification" in window) {
      const perm = await window.Notification.requestPermission();
      if (perm === "granted") {
        setPermGranted(true); setPermStatus("granted");
        if (window.Notification.permission === "granted") {
          new window.Notification("Love That Idea", {body:"Push notifications enabled!"});
        }
      } else {
        setPermStatus("denied");
      }
    } else {
      setPermStatus("unsupported");
    }
  }

  async function generateAIMessage() {
    if (!aiPrompt.trim()) return;
    setAiLoading(true); setAiMsg("");
    const r = await callClaudeSimple(
      "Write a warm salon notification message for: " + aiPrompt + ". Under 160 chars for SMS. Use {name} for client name.",
      "You are a salon marketing AI. Write genuine, warm messages for hair salon clients."
    );
    setAiMsg(r); setAiLoading(false);
  }

  async function sendNotifications() {
    if (!selectedClients.length) return;
    setSending(true);
    await new Promise(r => setTimeout(r, 1500));
    setSent(prev => [{id:Date.now(),template:selectedTemplate.label,channel,recipients:selectedClients.map(c=>c.name),count:selectedClients.length,date:new Date().toLocaleString(),status:"delivered"},...prev]);
    setSending(false); setSendSuccess(true);
    if (permGranted && typeof window !== "undefined" && "Notification" in window && window.Notification.permission === "granted") {
      new window.Notification("Love That Idea", {body: "Sent to " + selectedClients.length + " client(s)!"});
    }
    setTimeout(() => setSendSuccess(false), 3000);
  }

  const NAV = [["compose","Compose"],["templates","Templates"],["push","Push Setup"],["history","History"],["analytics","Analytics"]];

  return (
    <div style={{flex:1,display:"flex",flexDirection:"column",overflow:"hidden",background:C.bg}}>
      <div style={{background:C.white,borderBottom:`1px solid ${C.border}`,padding:"0 20px",display:"flex",gap:"2px",flexShrink:0,overflowX:"auto"}}>
        {NAV.map(([v,l])=>(
          <button key={v} onClick={()=>setView(v)} style={{background:"none",border:"none",borderBottom:`3px solid ${view===v?C.mint:"transparent"}`,color:view===v?C.mint:C.muted,padding:"13px 14px 10px",fontSize:"12px",cursor:"pointer",fontWeight:view===v?"800":"500",whiteSpace:"nowrap"}}>{l}</button>
        ))}
      </div>
      <div style={{flex:1,overflowY:"auto",padding:"20px"}}>

        {view==="compose" && (
          <div style={{display:"flex",gap:"20px",maxWidth:"900px",flexWrap:"wrap"}}>
            <div style={{flex:2,minWidth:"320px"}}>
              <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"14px",padding:"20px",marginBottom:"16px"}}>
                <div style={{fontSize:"11px",letterSpacing:"3px",color:C.muted,fontWeight:"700",marginBottom:"14px"}}>SELECT CLIENTS</div>
                {clientList.map(c=>(
                  <label key={c.id} style={{display:"flex",gap:"10px",alignItems:"center",padding:"8px 0",borderBottom:`1px solid ${C.dim}`,cursor:"pointer"}}>
                    <input type="checkbox" checked={c.selected} onChange={()=>setClientList(prev=>prev.map(x=>x.id===c.id?{...x,selected:!x.selected}:x))} style={{accentColor:C.mint,width:"16px",height:"16px"}}/>
                    <div style={{flex:1}}>
                      <div style={{fontSize:"13px",fontWeight:"600",color:C.text}}>{c.name}</div>
                      <div style={{fontSize:"11px",color:C.muted}}>{c.phone} - Last visit: {c.lastVisit}</div>
                    </div>
                    <span style={{fontSize:"10px",background:C.mintLight,color:C.mintDark,padding:"2px 8px",borderRadius:"20px"}}>{c.type}</span>
                  </label>
                ))}
              </div>
            </div>
            <div style={{flex:3,minWidth:"320px"}}>
              <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"14px",padding:"20px",marginBottom:"16px"}}>
                <div style={{fontSize:"11px",letterSpacing:"3px",color:C.muted,fontWeight:"700",marginBottom:"14px"}}>MESSAGE</div>
                <div style={{display:"flex",gap:"8px",marginBottom:"12px"}}>
                  {["sms","email","push"].map(ch=>(
                    <button key={ch} onClick={()=>setChannel(ch)} style={{flex:1,background:channel===ch?GRAD.hero:"transparent",color:channel===ch?"#fff":C.muted,border:`1px solid ${channel===ch?C.mint:C.border}`,padding:"8px",borderRadius:"8px",fontSize:"12px",fontWeight:"700",cursor:"pointer",textTransform:"capitalize"}}>{ch==="sms"?"SMS":ch==="email"?"Email":"Push"}</button>
                  ))}
                </div>
                <div style={{display:"flex",gap:"8px",marginBottom:"12px"}}>
                  <button onClick={()=>setUseTemplate(true)} style={{flex:1,background:useTemplate?C.mintLight:"transparent",color:useTemplate?C.mintDark:C.muted,border:`1px solid ${useTemplate?C.mint:C.border}`,padding:"8px",borderRadius:"8px",fontSize:"12px",fontWeight:"700",cursor:"pointer"}}>Use Template</button>
                  <button onClick={()=>setUseTemplate(false)} style={{flex:1,background:!useTemplate?C.mintLight:"transparent",color:!useTemplate?C.mintDark:C.muted,border:`1px solid ${!useTemplate?C.mint:C.border}`,padding:"8px",borderRadius:"8px",fontSize:"12px",fontWeight:"700",cursor:"pointer"}}>Custom</button>
                </div>
                {useTemplate?(
                  <select value={selectedTemplate.id} onChange={e=>setSelectedTemplate(NOTIF_TEMPLATES.find(t=>t.id===e.target.value))} style={{...IS,marginBottom:"12px"}}>
                    {NOTIF_TEMPLATES.map(t=><option key={t.id} value={t.id}>{t.label}</option>)}
                  </select>
                ):(
                  <div>
                    <div style={{display:"flex",gap:"8px",marginBottom:"8px"}}>
                      <input value={aiPrompt} onChange={e=>setAiPrompt(e.target.value)} placeholder="Describe the message..." style={{...IS,flex:1}}/>
                      <button onClick={generateAIMessage} disabled={aiLoading} style={{background:aiLoading?C.dim:GRAD.hero,color:"#fff",border:"none",padding:"9px 14px",borderRadius:"8px",fontSize:"12px",fontWeight:"700",cursor:"pointer",whiteSpace:"nowrap"}}>{aiLoading?"...":"AI Write"}</button>
                    </div>
                    <ClaudeBadge size="sm" style={{marginBottom:"8px"}}/>
                    {aiMsg&&<div style={{background:C.mintLight,border:`1px solid ${C.mint}`,borderRadius:"8px",padding:"10px",fontSize:"13px",color:C.sub,marginBottom:"8px",lineHeight:"1.7"}}>{aiMsg}</div>}
                    <textarea value={customMsg} onChange={e=>setCustomMsg(e.target.value)} rows={4} placeholder="Write your message..." style={{...IS,resize:"vertical"}}/>
                  </div>
                )}
                {useTemplate&&selectedTemplate&&(
                  <div style={{background:C.bg,borderRadius:"8px",padding:"12px",marginBottom:"12px",fontSize:"13px",color:C.sub,lineHeight:"1.7"}}>{selectedTemplate.template}</div>
                )}
                <div style={{display:"flex",gap:"8px",marginBottom:"12px"}}>
                  <button onClick={()=>setSchedule("now")} style={{flex:1,background:schedule==="now"?GRAD.hero:"transparent",color:schedule==="now"?"#fff":C.muted,border:`1px solid ${schedule==="now"?C.mint:C.border}`,padding:"8px",borderRadius:"8px",fontSize:"12px",fontWeight:"700",cursor:"pointer"}}>Send Now</button>
                  <button onClick={()=>setSchedule("later")} style={{flex:1,background:schedule==="later"?GRAD.hero:"transparent",color:schedule==="later"?"#fff":C.muted,border:`1px solid ${schedule==="later"?C.mint:C.border}`,padding:"8px",borderRadius:"8px",fontSize:"12px",fontWeight:"700",cursor:"pointer"}}>Schedule</button>
                </div>
                {schedule==="later"&&(
                  <div style={{display:"flex",gap:"8px",marginBottom:"12px"}}>
                    <input type="date" value={scheduleDate} onChange={e=>setScheduleDate(e.target.value)} style={{...IS,flex:1}}/>
                    <input type="time" value={scheduleTime} onChange={e=>setScheduleTime(e.target.value)} style={{...IS,flex:1}}/>
                  </div>
                )}
                {sendSuccess&&<div style={{background:C.mintLight,border:`1px solid ${C.mint}`,borderRadius:"8px",padding:"10px",marginBottom:"12px",fontSize:"13px",color:C.mintDark,fontWeight:"700",textAlign:"center"}}>Messages sent successfully!</div>}
                <button onClick={sendNotifications} disabled={sending||!selectedClients.length} style={{width:"100%",background:sending||!selectedClients.length?C.dim:GRAD.hero,color:"#fff",border:"none",padding:"13px",borderRadius:"10px",fontSize:"14px",fontWeight:"900",cursor:sending||!selectedClients.length?"not-allowed":"pointer"}}>
                  {sending?"Sending...":"Send to " + selectedClients.length + " Client" + (selectedClients.length!==1?"s":"")}
                </button>
              </div>
            </div>
          </div>
        )}

        {view==="templates" && (
          <div>
            <div style={{fontFamily:FONTS.display,fontSize:"20px",fontWeight:"600",color:C.text,marginBottom:"16px"}}>Message Templates</div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(280px,1fr))",gap:"12px"}}>
              {NOTIF_TEMPLATES.map(t=>(
                <div key={t.id} style={{background:C.white,border:`1.5px solid ${C.border}`,borderRadius:"14px",padding:"16px",cursor:"pointer"}} onClick={()=>{setSelectedTemplate(t);setView("compose");}}>
                  <div style={{display:"flex",gap:"10px",alignItems:"center",marginBottom:"8px"}}>
                    <span style={{fontSize:"20px"}}>{t.icon}</span>
                    <div style={{fontSize:"13px",fontWeight:"800",color:C.text}}>{t.label}</div>
                  </div>
                  <div style={{fontSize:"12px",color:C.muted,lineHeight:"1.7",marginBottom:"10px"}}>{t.template}</div>
                  <span style={{background:C.mintLight,color:C.mintDark,fontSize:"9px",padding:"2px 8px",borderRadius:"20px",fontWeight:"700",textTransform:"capitalize"}}>{t.cat}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {view==="push" && (
          <div style={{maxWidth:"520px"}}>
            <div style={{fontFamily:FONTS.display,fontSize:"20px",fontWeight:"600",color:C.text,marginBottom:"6px"}}>Push Notification Setup</div>
            <div style={{fontSize:"13px",color:C.muted,marginBottom:"20px"}}>Enable browser push notifications to alert clients instantly.</div>
            <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"14px",padding:"20px",marginBottom:"16px"}}>
              <div style={{fontSize:"13px",fontWeight:"700",color:C.text,marginBottom:"8px"}}>Permission Status</div>
              <div style={{display:"flex",gap:"10px",alignItems:"center",marginBottom:"16px"}}>
                <div style={{width:"10px",height:"10px",borderRadius:"50%",background:permStatus==="granted"?"#22C55E":permStatus==="denied"?"#DC2626":"#D97706"}}/>
                <span style={{fontSize:"13px",color:C.sub,fontWeight:"600",textTransform:"capitalize"}}>{permStatus==="idle"?"Not requested":permStatus}</span>
              </div>
              <button onClick={requestPushPermission} disabled={permStatus==="granted"||permStatus==="denied"} style={{width:"100%",background:permStatus==="granted"?C.dim:GRAD.hero,color:"#fff",border:"none",padding:"12px",borderRadius:"10px",fontSize:"13px",fontWeight:"800",cursor:permStatus==="granted"||permStatus==="denied"?"not-allowed":"pointer"}}>
                {permStatus==="granted"?"Notifications Enabled":permStatus==="denied"?"Blocked by Browser":"Enable Push Notifications"}
              </button>
            </div>
            <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"14px",padding:"20px"}}>
              <div style={{fontSize:"13px",fontWeight:"700",color:C.text,marginBottom:"12px"}}>Notification Templates</div>
              {NOTIF_TEMPLATES.slice(0,4).map(t=>(
                <div key={t.id} style={{display:"flex",gap:"10px",alignItems:"center",padding:"10px 0",borderBottom:`1px solid ${C.dim}`}}>
                  <span style={{fontSize:"18px"}}>{t.icon}</span>
                  <div style={{flex:1,fontSize:"12px",color:C.sub}}>{t.label}</div>
                  <button onClick={()=>{
                    if(permGranted && typeof window!=="undefined" && "Notification" in window && window.Notification.permission==="granted") {
                      new window.Notification("Love That Idea - " + t.label, {body: t.template.replace("{name}","Client")});
                    } else {
                      alert("Enable push notifications first!");
                    }
                  }} style={{background:C.mintLight,border:`1px solid ${C.mint}`,color:C.mintDark,padding:"6px 12px",borderRadius:"8px",fontSize:"11px",fontWeight:"700",cursor:"pointer",whiteSpace:"nowrap"}}>Test</button>
                </div>
              ))}
            </div>
          </div>
        )}

        {view==="history" && (
          <div>
            <div style={{fontFamily:FONTS.display,fontSize:"20px",fontWeight:"600",color:C.text,marginBottom:"16px"}}>Send History</div>
            {sent.length===0?(
              <div style={{textAlign:"center",padding:"48px",background:C.white,border:`1px solid ${C.border}`,borderRadius:"14px",color:C.muted}}>
                <div style={{fontSize:"36px",marginBottom:"12px"}}>📭</div>
                <div style={{fontSize:"14px",fontWeight:"700",color:C.text}}>No messages sent yet</div>
                <div style={{fontSize:"12px",marginTop:"4px"}}>Compose and send your first message</div>
              </div>
            ):(
              <div style={{display:"flex",flexDirection:"column",gap:"10px"}}>
                {sent.map(s=>(
                  <div key={s.id} style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"12px",padding:"14px 16px",display:"flex",gap:"14px",alignItems:"center"}}>
                    <div style={{width:"40px",height:"40px",borderRadius:"10px",background:C.mintLight,display:"flex",alignItems:"center",justifyContent:"center",fontSize:"18px",flexShrink:0}}>
                      {NOTIF_TEMPLATES.find(t=>t.label===s.template)?.icon||"💬"}
                    </div>
                    <div style={{flex:1}}>
                      <div style={{fontSize:"13px",fontWeight:"700",color:C.text}}>{s.template}</div>
                      <div style={{fontSize:"11px",color:C.muted}}>Sent to {s.count} client{s.count!==1?"s":""} via {s.channel.toUpperCase()} - {s.date}</div>
                    </div>
                    <span style={{background:C.mintLight,color:C.mintDark,fontSize:"10px",padding:"3px 10px",borderRadius:"20px",fontWeight:"700"}}>{s.status}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {view==="analytics" && (
          <div>
            <div style={{fontFamily:FONTS.display,fontSize:"20px",fontWeight:"600",color:C.text,marginBottom:"16px"}}>Message Analytics</div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:"14px",marginBottom:"20px"}}>
              {[["Total Sent",sent.reduce((s,m)=>s+m.count,0),"#27AE78"],["Messages",sent.length,"#0891B2"],["Channels","3","#7C3AED"]].map(([l,v,color])=>(
                <div key={l} style={{background:C.white,border:`1px solid ${color}22`,borderRadius:"12px",padding:"16px",textAlign:"center"}}>
                  <div style={{fontSize:"28px",fontWeight:"900",color}}>{v}</div>
                  <div style={{fontSize:"11px",color:C.muted,fontWeight:"700",marginTop:"4px"}}>{l}</div>
                </div>
              ))}
            </div>
            <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"14px",padding:"20px"}}>
              <div style={{fontSize:"13px",fontWeight:"700",color:C.text,marginBottom:"12px"}}>Template Performance</div>
              {NOTIF_TEMPLATES.slice(0,5).map((t,i)=>{
                const pct = Math.floor(Math.random()*40)+55;
                return (
                  <div key={t.id} style={{display:"flex",gap:"12px",alignItems:"center",marginBottom:"10px"}}>
                    <span style={{fontSize:"14px",width:"24px"}}>{t.icon}</span>
                    <div style={{flex:1}}>
                      <div style={{fontSize:"12px",color:C.text,fontWeight:"600",marginBottom:"3px"}}>{t.label}</div>
                      <div style={{height:"6px",background:C.dim,borderRadius:"3px",overflow:"hidden"}}>
                        <div style={{height:"100%",width:pct+"%",background:GRAD.hero,borderRadius:"3px"}}/>
                      </div>
                    </div>
                    <div style={{fontSize:"12px",fontWeight:"700",color:C.mint,width:"36px",textAlign:"right"}}>{pct}%</div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

      </div>
    </div>
  );
}


