function HairHealthTab() {
  const [view, setView] = useState("pre"); // pre | post | types | scalp | ai | checklist
  const [selectedType, setSelectedType] = useState(null);
  const [selectedScalp, setSelectedScalp] = useState(null);
  const [expandedPractice, setExpandedPractice] = useState(null);
  const [checklistPre, setChecklistPre] = useState({});
  const [checklistPost, setChecklistPost] = useState({});
  const [aiQ, setAiQ] = useState(""); const [aiHistory, setAiHistory] = useState([]); const [aiLoading, setAiLoading] = useState(false);
  const [hairType, setHairType] = useState("4C Coily");
  const [upcomingService, setUpcomingService] = useState("Braids");
  const [customPlan, setCustomPlan] = useState("");
  const [planLoading, setPlanLoading] = useState(false);
  const [printMode, setPrintMode] = useState(false);

  const NAV = [
    ["pre",       "📋", "Pre-Appointment"],
    ["post",      "🌟", "Post-Appointment"],
    ["types",     "💇", "By Hair Type"],
    ["scalp",     "🧬", "Scalp Health"],
    ["checklist", "✅", "My Checklist"],
    ["ai",        "✦",  "AI Hair Coach"],
  ];

  async function askAI() {
    if(!aiQ.trim()) return;
    setAiLoading(true);
    const msgs = [...aiHistory, {role:"user", content:aiQ}];
    const sys = `You are an expert certified trichologist and hair care AI coach for Love That Idea. You specialize in healthy hair practices before and after salon appointments for all hair types (1A–4C), textures, and cultural backgrounds. Give specific, science-backed, actionable advice. Reference specific products, techniques, and timing when relevant. Be warm, professional, and encouraging. Under 200 words.`;
    try {
      const res = await fetch(CLAUDE_PROXY_URL, {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({ model:"claude-sonnet-4-20250514", max_tokens:800, system:sys, messages:msgs })
      });
      const d = await res.json();
      const ans = d.content?.map(b=>b.text||"").join("")||"";
      setAiHistory([...msgs, {role:"assistant", content:ans}]);
    } catch(e) { setAiHistory(prev=>[...prev,{role:"assistant",content:"Connection error. Try again."}]); }
    setAiQ(""); setAiLoading(false);
  }

  async function generatePersonalPlan() {
    setPlanLoading(true); setCustomPlan("");
    const sys = `You are an expert hair care AI. Generate a personalized pre- and post-appointment healthy hair care plan. Be specific with timing, products types, and techniques. Format with clear sections: PRE-APPOINTMENT (1 week, 2-3 days, night before, day of) and POST-APPOINTMENT (24 hrs, first week, ongoing). Under 300 words.`;
    try {
      const res = await fetch(CLAUDE_PROXY_URL, {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({ model:"claude-sonnet-4-20250514", max_tokens:1000, system:sys,
          messages:[{role:"user", content:`Create a personalized hair health plan for: Hair type: ${hairType}, Upcoming service: ${upcomingService}. Include specific timing, product types, and techniques for this exact combination.`}]
        })
      });
      const d = await res.json();
      setCustomPlan(d.content?.map(b=>b.text||"").join("")||"");
    } catch(e) { setCustomPlan("Connection error. Try again."); }
    setPlanLoading(false);
  }

  const PracticeCard = ({ p, idx, section }) => {
    const key = `${section}-${idx}`;
    const isOpen = expandedPractice === key;
    const checked = section==="pre" ? checklistPre[key] : checklistPost[key];
    return (
      <div style={{background:C.white, border:`1.5px solid ${isOpen?C.mint:C.border}`, borderRadius:"12px", overflow:"hidden", marginBottom:"10px", transition:"all 0.2s", opacity:checked?0.7:1}}>
        <div onClick={()=>setExpandedPractice(isOpen?null:key)}
          style={{display:"flex", gap:"12px", alignItems:"center", padding:"14px 16px", cursor:"pointer"}}>
          <span style={{fontSize:"22px", flexShrink:0}}>{p.icon}</span>
          <div style={{flex:1}}>
            <div style={{fontSize:"14px", fontWeight:"800", color:checked?C.muted:C.text, textDecoration:checked?"line-through":"none"}}>{p.title}</div>
            {!isOpen && <div style={{fontSize:"11px", color:C.muted, marginTop:"2px"}}>{p.detail.slice(0,70)}...</div>}
          </div>
          <div style={{display:"flex", gap:"8px", alignItems:"center", flexShrink:0}}>
            <button onClick={e=>{e.stopPropagation(); if(section==="pre") setChecklistPre(prev=>({...prev,[key]:!prev[key]})); else setChecklistPost(prev=>({...prev,[key]:!prev[key]}));}}
              style={{width:"24px", height:"24px", borderRadius:"50%", background:checked?C.mint:C.bg, border:`2px solid ${checked?C.mint:C.border}`, color:"#fff", fontSize:"13px", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0}}>
              {checked?"✓":""}
            </button>
            <span style={{color:C.muted, fontSize:"14px"}}>{isOpen?"▲":"▼"}</span>
          </div>
        </div>
        {isOpen && (
          <div style={{padding:"0 16px 16px 52px", borderTop:`1px solid ${C.dim}`}}>
            <p style={{fontSize:"13px", color:C.sub, lineHeight:"1.8", margin:"12px 0 10px"}}>{p.detail}</p>
            <div style={{background:C.mintLight, border:`1px solid ${C.border}`, borderRadius:"8px", padding:"10px 12px", display:"flex", gap:"8px", alignItems:"flex-start"}}>
              <span style={{color:C.mint, fontWeight:"900", flexShrink:0}}>Pro tip:</span>
              <span style={{fontSize:"12px", color:C.sub, lineHeight:"1.6"}}>{p.tip}</span>
            </div>
          </div>
        )}
      </div>
    );
  };

  const preData = PRE_APPT_DATA["All Hair Types"];
  const postData = POST_APPT_DATA["All Hair Types"];
  const totalPreItems = preData.days_before.reduce((s,d)=>s+d.practices.length,0);
  const totalPostItems = postData.phases.reduce((s,p)=>s+p.practices.length,0);
  const preChecked = Object.values(checklistPre).filter(Boolean).length;
  const postChecked = Object.values(checklistPost).filter(Boolean).length;

  return (
    <div style={{flex:1, display:"flex", flexDirection:"column", overflow:"hidden", background:C.bg}}>
      {/* Sub-nav */}
      <div style={{background:C.white, borderBottom:`1px solid ${C.border}`, padding:"0 20px", display:"flex", gap:"2px", flexShrink:0, overflowX:"auto"}}>
        {NAV.map(([v,icon,label])=>(
          <button key={v} onClick={()=>setView(v)} style={{background:"none", border:"none", borderBottom:`3px solid ${view===v?C.mint:"transparent"}`, color:view===v?C.mint:C.muted, padding:"13px 14px 10px", fontSize:"12px", cursor:"pointer", fontWeight:view===v?"800":"500", whiteSpace:"nowrap"}}>
            {icon} {label}
          </button>
        ))}
      </div>

      <div style={{flex:1, overflowY:"auto", padding:"20px"}}>

        {/* -- PRE-APPOINTMENT -- */}
        {view==="pre" && (
          <div>
            {/* Hero */}
            <div style={{background:`linear-gradient(135deg, #E8F8F0, #D4F0E4)`, border:`1px solid ${C.border}`, borderRadius:"16px", padding:"24px", marginBottom:"24px"}}>
              <div style={{display:"flex", justifyContent:"space-between", alignItems:"flex-start", flexWrap:"wrap", gap:"12px"}}>
                <div>
                  <div style={{fontSize:"10px", letterSpacing:"3px", color:C.mint, fontWeight:"800", marginBottom:"6px"}}>BEFORE YOUR APPOINTMENT</div>
                  <div style={{fontSize:"26px", fontWeight:"900", color:C.text, marginBottom:"6px"}}>Pre-Appointment Hair Health</div>
                  <div style={{fontSize:"13px", color:C.sub, lineHeight:"1.7", maxWidth:"540px"}}>
                    What you do in the days leading up to your appointment directly impacts your results, your stylist's ability to deliver quality work, and your hair's overall health. Prepared hair = better service.
                  </div>
                </div>
                <div style={{background:C.white, borderRadius:"14px", padding:"16px", minWidth:"160px", textAlign:"center", border:`1px solid ${C.border}`}}>
                  <div style={{fontSize:"32px", fontWeight:"900", color:C.mint}}>{preChecked}/{totalPreItems}</div>
                  <div style={{fontSize:"11px", color:C.muted, fontWeight:"700"}}>Steps Completed</div>
                  <div style={{height:"6px", background:C.dim, borderRadius:"3px", marginTop:"8px", overflow:"hidden"}}>
                    <div style={{height:"100%", width:`${totalPreItems?Math.round(preChecked/totalPreItems*100):0}%`, background:GRAD.hero, borderRadius:"3px", transition:"width 0.4s"}}/>
                  </div>
                </div>
              </div>
            </div>

            {/* Golden rules */}
            <div style={{display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(220px,1fr))", gap:"10px", marginBottom:"24px"}}>
              {[
                ["Arrive Clean", "Hair washed 1–2 days before, not soaking wet day-of", "#27AE78"],
                ["No Heavy Products", "Avoid butters & waxes 5–7 days before chemical services", "#0D9488"],
                ["Detangled Always", "Never arrive matted  -  detangle section by section first", "#7C3AED"],
                ["Eat Before Going", "Long services (4–8hrs) require a real meal beforehand", "#F59E0B"],
                ["Share Concerns", "Tell your stylist about scalp issues, breakage, or changes", "#EC4899"],
                ["Wear Easy Clothes", "Button-down or zip-up so style stays intact when leaving", "#0891B2"],
              ].map(([title,desc,color])=>(
                <div key={title} style={{background:C.white, border:`1.5px solid ${color}33`, borderRadius:"12px", padding:"14px", borderLeft:`4px solid ${color}`}}>
                  <div style={{fontSize:"13px", fontWeight:"800", color:C.text, marginBottom:"4px"}}>{title}</div>
                  <div style={{fontSize:"11px", color:C.muted, lineHeight:"1.5"}}>{desc}</div>
                </div>
              ))}
            </div>

            {/* Timeline practices */}
            {preData.days_before.map((phase, pi)=>(
              <div key={pi} style={{marginBottom:"28px"}}>
                <div style={{display:"flex", alignItems:"center", gap:"10px", marginBottom:"14px"}}>
                  <div style={{width:"36px", height:"36px", borderRadius:"50%", background:phase.accent+"18", border:`2px solid ${phase.accent}`, display:"flex", alignItems:"center", justifyContent:"center", fontSize:"14px", flexShrink:0}}>{phase.icon}</div>
                  <div style={{fontSize:"17px", fontWeight:"900", color:phase.accent}}>{phase.timeframe}</div>
                  <div style={{height:"1px", flex:1, background:phase.accent+"33"}}/>
                </div>
                {phase.practices.map((p,i)=>(
                  <PracticeCard key={i} p={p} idx={pi*10+i} section="pre" />
                ))}
              </div>
            ))}
          </div>
        )}

        {/* -- POST-APPOINTMENT -- */}
        {view==="post" && (
          <div>
            {/* Hero */}
            <div style={{background:`linear-gradient(135deg, #E6FAF8, #CCFBEF)`, border:`1px solid #6ECFC9`, borderRadius:"16px", padding:"24px", marginBottom:"24px"}}>
              <div style={{display:"flex", justifyContent:"space-between", alignItems:"flex-start", flexWrap:"wrap", gap:"12px"}}>
                <div>
                  <div style={{fontSize:"10px", letterSpacing:"3px", color:C.teal, fontWeight:"800", marginBottom:"6px"}}>AFTER YOUR APPOINTMENT</div>
                  <div style={{fontSize:"26px", fontWeight:"900", color:C.text, marginBottom:"6px"}}>Post-Appointment Hair Health</div>
                  <div style={{fontSize:"13px", color:C.sub, lineHeight:"1.7", maxWidth:"540px"}}>
                    The 24–72 hours after your appointment are critical. How you care for your hair after leaving the salon determines how long your results last and how healthy your hair grows between visits.
                  </div>
                </div>
                <div style={{background:C.white, borderRadius:"14px", padding:"16px", minWidth:"160px", textAlign:"center", border:`1px solid ${C.border}`}}>
                  <div style={{fontSize:"32px", fontWeight:"900", color:C.teal}}>{postChecked}/{totalPostItems}</div>
                  <div style={{fontSize:"11px", color:C.muted, fontWeight:"700"}}>Steps Completed</div>
                  <div style={{height:"6px", background:C.dim, borderRadius:"3px", marginTop:"8px", overflow:"hidden"}}>
                    <div style={{height:"100%", width:`${totalPostItems?Math.round(postChecked/totalPostItems*100):0}%`, background:`linear-gradient(90deg,${C.teal},${C.mint})`, borderRadius:"3px", transition:"width 0.4s"}}/>
                  </div>
                </div>
              </div>
            </div>

            {/* The 3 rules */}
            <div style={{display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:"12px", marginBottom:"24px"}}>
              {[
                ["🚫 Don't Wash", "Wait the full window your stylist specified before shampooing", "#E53E3E"],
                ["😴 Protect Nightly", "Satin/silk bonnet or pillowcase  -  every single night without exception", "#7C3AED"],
                ["💧 Moisturize Daily", "LOC or LCO method daily or every other day to seal in hydration", "#27AE78"],
              ].map(([title,desc,color])=>(
                <div key={title} style={{background:C.white, border:`2px solid ${color}22`, borderRadius:"14px", padding:"18px", textAlign:"center"}}>
                  <div style={{fontSize:"22px", marginBottom:"8px"}}>{title.split(" ")[0]}</div>
                  <div style={{fontSize:"14px", fontWeight:"800", color, marginBottom:"6px"}}>{title.split(" ").slice(1).join(" ")}</div>
                  <div style={{fontSize:"12px", color:C.muted, lineHeight:"1.6"}}>{desc}</div>
                </div>
              ))}
            </div>

            {/* Phase practices */}
            {postData.phases.map((phase,pi)=>(
              <div key={pi} style={{marginBottom:"28px"}}>
                <div style={{display:"flex", alignItems:"center", gap:"10px", marginBottom:"14px"}}>
                  <div style={{width:"36px", height:"36px", borderRadius:"50%", background:phase.accent+"18", border:`2px solid ${phase.accent}`, display:"flex", alignItems:"center", justifyContent:"center", fontSize:"14px", flexShrink:0}}>{phase.icon}</div>
                  <div style={{fontSize:"17px", fontWeight:"900", color:phase.accent}}>{phase.timeframe}</div>
                  <div style={{height:"1px", flex:1, background:phase.accent+"33"}}/>
                </div>
                {phase.practices.map((p,i)=>(
                  <PracticeCard key={i} p={p} idx={pi*10+i} section="post" />
                ))}
              </div>
            ))}
          </div>
        )}

        {/* -- BY HAIR TYPE -- */}
        {view==="types" && (
          <div>
            <div style={{fontSize:"22px", fontWeight:"900", color:C.text, marginBottom:"4px"}}>Practices By Hair Type</div>
            <div style={{fontSize:"13px", color:C.muted, marginBottom:"20px"}}>Tailored pre and post-appointment care based on your specific hair type and texture.</div>
            {!selectedType ? (
              <div style={{display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(260px,1fr))", gap:"14px"}}>
                {HAIR_TYPE_GUIDES.map(guide=>(
                  <div key={guide.type} onClick={()=>setSelectedType(guide)}
                    style={{background:C.white, border:`1.5px solid ${C.border}`, borderRadius:"14px", padding:"20px", cursor:"pointer", transition:"all 0.2s"}}
                    onMouseEnter={e=>{e.currentTarget.style.borderColor=guide.color;e.currentTarget.style.transform="translateY(-2px)";e.currentTarget.style.boxShadow=`0 8px 20px ${guide.color}22`;}}
                    onMouseLeave={e=>{e.currentTarget.style.borderColor=C.border;e.currentTarget.style.transform="translateY(0)";e.currentTarget.style.boxShadow="none";}}>
                    <div style={{height:"4px", background:guide.color, borderRadius:"4px", marginBottom:"14px"}}/>
                    <div style={{fontSize:"28px", marginBottom:"6px"}}>{guide.icon}</div>
                    <div style={{fontSize:"16px", fontWeight:"900", color:guide.color, marginBottom:"8px"}}>{guide.type}</div>
                    <div style={{display:"flex", gap:"8px"}}>
                      <span style={{background:guide.color+"18", color:guide.color, fontSize:"10px", padding:"3px 10px", borderRadius:"20px", fontWeight:"700"}}>{guide.pre.length} pre tips</span>
                      <span style={{background:guide.color+"18", color:guide.color, fontSize:"10px", padding:"3px 10px", borderRadius:"20px", fontWeight:"700"}}>{guide.post.length} post tips</span>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div>
                <button onClick={()=>setSelectedType(null)} style={{background:C.white, border:`1px solid ${C.border}`, color:C.muted, padding:"8px 16px", borderRadius:"8px", fontSize:"12px", cursor:"pointer", fontWeight:"700", marginBottom:"16px"}}>← All Hair Types</button>
                <div style={{background:C.white, border:`2px solid ${selectedType.color}`, borderRadius:"16px", overflow:"hidden"}}>
                  <div style={{height:"6px", background:selectedType.color}}/>
                  <div style={{padding:"24px"}}>
                    <div style={{fontSize:"28px", marginBottom:"6px"}}>{selectedType.icon}</div>
                    <div style={{fontSize:"22px", fontWeight:"900", color:selectedType.color, marginBottom:"20px"}}>{selectedType.type}</div>
                    <div style={{display:"grid", gridTemplateColumns:"1fr 1fr", gap:"24px"}}>
                      <div>
                        <div style={{fontSize:"10px", letterSpacing:"3px", color:C.muted, fontWeight:"700", marginBottom:"12px", display:"flex", alignItems:"center", gap:"8px"}}><span style={{background:selectedType.color, color:"#fff", padding:"3px 8px", borderRadius:"6px", fontSize:"9px"}}>PRE</span> BEFORE APPOINTMENT</div>
                        <div style={{display:"flex", flexDirection:"column", gap:"8px"}}>
                          {selectedType.pre.map((tip,i)=>(
                            <div key={i} style={{display:"flex", gap:"10px", alignItems:"flex-start", background:selectedType.color+"0D", borderRadius:"10px", padding:"12px"}}>
                              <span style={{color:selectedType.color, fontWeight:"900", fontSize:"14px", flexShrink:0}}>✓</span>
                              <span style={{fontSize:"13px", color:C.sub, lineHeight:"1.6"}}>{tip}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                      <div>
                        <div style={{fontSize:"10px", letterSpacing:"3px", color:C.muted, fontWeight:"700", marginBottom:"12px", display:"flex", alignItems:"center", gap:"8px"}}><span style={{background:C.teal, color:"#fff", padding:"3px 8px", borderRadius:"6px", fontSize:"9px"}}>POST</span> AFTER APPOINTMENT</div>
                        <div style={{display:"flex", flexDirection:"column", gap:"8px"}}>
                          {selectedType.post.map((tip,i)=>(
                            <div key={i} style={{display:"flex", gap:"10px", alignItems:"flex-start", background:C.teal+"0D", borderRadius:"10px", padding:"12px"}}>
                              <span style={{color:C.teal, fontWeight:"900", fontSize:"14px", flexShrink:0}}>✓</span>
                              <span style={{fontSize:"13px", color:C.sub, lineHeight:"1.6"}}>{tip}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {/* -- SCALP HEALTH -- */}
        {view==="scalp" && (
          <div>
            <div style={{fontSize:"22px", fontWeight:"900", color:C.text, marginBottom:"4px"}}>Scalp Health Guide</div>
            <div style={{fontSize:"13px", color:C.muted, marginBottom:"20px"}}>A healthy scalp is the foundation of healthy hair. Identify your scalp condition and follow targeted pre and post-appointment care.</div>
            {!selectedScalp ? (
              <div style={{display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(280px,1fr))", gap:"14px"}}>
                {SCALP_HEALTH.map(s=>(
                  <div key={s.condition} onClick={()=>setSelectedScalp(s)}
                    style={{background:C.white, border:`1.5px solid ${C.border}`, borderRadius:"14px", padding:"18px", cursor:"pointer", transition:"all 0.2s"}}
                    onMouseEnter={e=>{e.currentTarget.style.borderColor=s.color;e.currentTarget.style.transform="translateY(-2px)";}}
                    onMouseLeave={e=>{e.currentTarget.style.borderColor=C.border;e.currentTarget.style.transform="translateY(0)";}}>
                    <div style={{height:"4px", background:s.color, borderRadius:"4px", marginBottom:"14px"}}/>
                    <div style={{fontSize:"16px", fontWeight:"900", color:s.color, marginBottom:"6px"}}>{s.condition}</div>
                    <div style={{fontSize:"12px", color:C.muted, marginBottom:"10px", fontStyle:"italic"}}>Signs: {s.signs}</div>
                    <div style={{fontSize:"11px", color:C.muted}}>Tap for pre and post care plan</div>
                  </div>
                ))}
              </div>
            ) : (
              <div>
                <button onClick={()=>setSelectedScalp(null)} style={{background:C.white, border:`1px solid ${C.border}`, color:C.muted, padding:"8px 16px", borderRadius:"8px", fontSize:"12px", cursor:"pointer", fontWeight:"700", marginBottom:"16px"}}>← All Conditions</button>
                <div style={{background:C.white, border:`2px solid ${selectedScalp.color}`, borderRadius:"16px", overflow:"hidden"}}>
                  <div style={{height:"6px", background:selectedScalp.color}}/>
                  <div style={{padding:"24px"}}>
                    <div style={{fontSize:"22px", fontWeight:"900", color:selectedScalp.color, marginBottom:"6px"}}>{selectedScalp.condition}</div>
                    <div style={{fontSize:"13px", color:C.muted, marginBottom:"20px", fontStyle:"italic"}}>Signs: {selectedScalp.signs}</div>
                    <div style={{display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:"16px"}}>
                      {[["Before Appointment", selectedScalp.pre, "#27AE78"],["After Appointment", selectedScalp.post, "#0D9488"],["Always Avoid", selectedScalp.avoid, "#E53E3E"]].map(([label,content,color])=>(
                        <div key={label} style={{background:color+"0D", border:`1px solid ${color}33`, borderRadius:"12px", padding:"16px"}}>
                          <div style={{fontSize:"11px", letterSpacing:"2px", color, fontWeight:"800", marginBottom:"10px"}}>{label.toUpperCase()}</div>
                          <div style={{fontSize:"13px", color:C.sub, lineHeight:"1.7"}}>{content}</div>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {/* -- CHECKLIST -- */}
        {view==="checklist" && (
          <div style={{maxWidth:"700px"}}>
            <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"16px"}}>
              <div>
                <div style={{fontSize:"22px", fontWeight:"900", color:C.text}}>My Hair Health Checklist</div>
                <div style={{fontSize:"13px", color:C.muted}}>Track your pre and post-appointment practices</div>
              </div>
              <button onClick={()=>window.print()} style={{background:C.mintLight, border:`1.5px solid ${C.mint}`, color:C.mintDark, padding:"9px 18px", borderRadius:"8px", fontSize:"12px", fontWeight:"700", cursor:"pointer"}}>Print Checklist</button>
            </div>

            {/* Pre checklist summary */}
            <div style={{background:C.white, border:`1px solid ${C.border}`, borderRadius:"14px", padding:"18px", marginBottom:"16px"}}>
              <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"14px"}}>
                <div style={{fontSize:"14px", fontWeight:"800", color:C.text}}>Before Appointment</div>
                <div style={{fontSize:"13px", color:C.mint, fontWeight:"700"}}>{preChecked}/{totalPreItems} done</div>
              </div>
              <div style={{height:"8px", background:C.dim, borderRadius:"4px", overflow:"hidden", marginBottom:"16px"}}>
                <div style={{height:"100%", width:`${totalPreItems?Math.round(preChecked/totalPreItems*100):0}%`, background:GRAD.hero, borderRadius:"4px", transition:"width 0.4s"}}/>
              </div>
              {preData.days_before.map((phase,pi)=>(
                <div key={pi} style={{marginBottom:"12px"}}>
                  <div style={{fontSize:"11px", color:phase.accent, fontWeight:"800", letterSpacing:"2px", marginBottom:"6px"}}>{phase.timeframe.toUpperCase()}</div>
                  {phase.practices.map((p,i)=>{
                    const key=`pre-${pi*10+i}`;
                    return (
                      <label key={i} style={{display:"flex", gap:"10px", alignItems:"flex-start", padding:"8px 0", borderBottom:`1px solid ${C.dim}`, cursor:"pointer"}}>
                        <input type="checkbox" checked={!!checklistPre[key]} onChange={()=>setChecklistPre(prev=>({...prev,[key]:!prev[key]}))} style={{accentColor:C.mint, marginTop:"2px", flexShrink:0}}/>
                        <div>
                          <div style={{fontSize:"13px", color:checklistPre[key]?C.muted:C.text, fontWeight:"600", textDecoration:checklistPre[key]?"line-through":"none"}}>{p.title}</div>
                          <div style={{fontSize:"11px", color:C.muted, marginTop:"2px"}}>{p.tip}</div>
                        </div>
                      </label>
                    );
                  })}
                </div>
              ))}
            </div>

            {/* Post checklist summary */}
            <div style={{background:C.white, border:`1px solid ${C.border}`, borderRadius:"14px", padding:"18px"}}>
              <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"14px"}}>
                <div style={{fontSize:"14px", fontWeight:"800", color:C.text}}>After Appointment</div>
                <div style={{fontSize:"13px", color:C.teal, fontWeight:"700"}}>{postChecked}/{totalPostItems} done</div>
              </div>
              <div style={{height:"8px", background:C.dim, borderRadius:"4px", overflow:"hidden", marginBottom:"16px"}}>
                <div style={{height:"100%", width:`${totalPostItems?Math.round(postChecked/totalPostItems*100):0}%`, background:`linear-gradient(90deg,${C.teal},${C.mint})`, borderRadius:"4px", transition:"width 0.4s"}}/>
              </div>
              {postData.phases.map((phase,pi)=>(
                <div key={pi} style={{marginBottom:"12px"}}>
                  <div style={{fontSize:"11px", color:phase.accent, fontWeight:"800", letterSpacing:"2px", marginBottom:"6px"}}>{phase.timeframe.toUpperCase()}</div>
                  {phase.practices.map((p,i)=>{
                    const key=`post-${pi*10+i}`;
                    return (
                      <label key={i} style={{display:"flex", gap:"10px", alignItems:"flex-start", padding:"8px 0", borderBottom:`1px solid ${C.dim}`, cursor:"pointer"}}>
                        <input type="checkbox" checked={!!checklistPost[key]} onChange={()=>setChecklistPost(prev=>({...prev,[key]:!prev[key]}))} style={{accentColor:C.teal, marginTop:"2px", flexShrink:0}}/>
                        <div>
                          <div style={{fontSize:"13px", color:checklistPost[key]?C.muted:C.text, fontWeight:"600", textDecoration:checklistPost[key]?"line-through":"none"}}>{p.title}</div>
                          <div style={{fontSize:"11px", color:C.muted, marginTop:"2px"}}>{p.tip}</div>
                        </div>
                      </label>
                    );
                  })}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* -- AI HAIR COACH -- */}
        {view==="ai" && (
          <div style={{display:"grid", gridTemplateColumns:"1fr 360px", gap:"20px", alignItems:"start"}}>
            {/* Chat */}
            <div>
              <div style={{fontSize:"22px", fontWeight:"900", color:C.text, marginBottom:"4px"}}>AI Hair Health Coach</div>
              <div style={{fontSize:"13px", color:C.muted, marginBottom:"16px"}}>Ask a certified trichologist AI anything about healthy hair practices before and after your appointment.</div>
              <div style={{display:"flex", gap:"6px", flexWrap:"wrap", marginBottom:"14px"}}>
                {["What should I do the night before braids?", "How do I maintain color after salon?", "Best post-relaxer care routine?", "How to reduce tension headaches from braids?", "When should I deep condition?"].map(q=>(
                  <button key={q} onClick={()=>setAiQ(q)} style={{background:C.white, border:`1px solid ${C.border}`, color:C.sub, padding:"6px 13px", borderRadius:"20px", fontSize:"11px", cursor:"pointer", fontWeight:"600"}}>{q}</button>
                ))}
              </div>
              <div style={{background:C.white, border:`1px solid ${C.border}`, borderRadius:"14px", padding:"16px", minHeight:"320px", maxHeight:"450px", overflowY:"auto", marginBottom:"12px", display:"flex", flexDirection:"column", gap:"10px"}}>
                {aiHistory.length===0 && (
                  <div style={{textAlign:"center", color:C.muted, padding:"50px 0"}}>
                    <div style={{fontSize:"36px", marginBottom:"12px"}}>🌿</div>
                    <div style={{fontSize:"15px", fontWeight:"700"}}>Your AI Hair Health Coach</div>
                    <div style={{fontSize:"12px", marginTop:"4px"}}>Ask anything about pre and post-appointment hair care</div>
                  </div>
                )}
                {aiHistory.map((m,i)=>(
                  <div key={i} style={{display:"flex", justifyContent:m.role==="user"?"flex-end":"flex-start", minWidth:0 }}>
                    <div style={{maxWidth:"85%", padding:"11px 15px", borderRadius:m.role==="user"?"16px 16px 4px 16px":"16px 16px 16px 4px", background:m.role==="user"?GRAD.hero:C.bg, color:m.role==="user"?"#fff":C.text, fontSize:"13px",wordBreak:"break-word",overflowWrap:"break-word",whiteSpace:"pre-wrap", lineHeight:"1.7", border:m.role==="assistant"?`1px solid ${C.border}`:"none"}}>
                      {m.content}
                    </div>
                  </div>
                ))}
                {aiLoading && (
                  <div style={{display:"flex", gap:"5px", padding:"12px 15px", background:C.bg, border:`1px solid ${C.border}`, borderRadius:"16px 16px 16px 4px", width:"fit-content"}}>
                    {[0,1,2].map(i=><div key={i} style={{width:"7px", height:"7px", borderRadius:"50%", background:C.mint, animation:`pulse 1s ease ${i*.2}s infinite`}}/>)}
                  </div>
                )}
              </div>
              <div style={{display:"flex", gap:"8px"}}>
                <input value={aiQ} onChange={e=>setAiQ(e.target.value)} onKeyDown={e=>e.key==="Enter"&&askAI()} placeholder="Ask about healthy hair practices..." style={{flex:1, background:C.white, border:`1.5px solid ${C.border}`, color:C.text, padding:"11px 14px", borderRadius:"10px", fontSize:"13px"}}/>
                <button onClick={askAI} disabled={aiLoading} style={{background:aiLoading?C.dim:GRAD.hero, color:"#fff", border:"none", padding:"11px 20px", borderRadius:"10px", fontSize:"13px", fontWeight:"800", cursor:aiLoading?"not-allowed":"pointer"}}>Ask</button>
                {aiHistory.length>0&&<button onClick={()=>setAiHistory([])} style={{background:C.white, border:`1px solid ${C.border}`, color:C.muted, padding:"11px 14px", borderRadius:"10px", fontSize:"12px", cursor:"pointer"}}>Clear</button>}
              </div>
            </div>

            {/* Personalized Plan Generator */}
            <div style={{position:"sticky", top:"20px"}}>
              <div style={{background:"linear-gradient(135deg,#E8F8F0,#D4F0E4)", border:`1px solid ${C.border}`, borderRadius:"16px", padding:"20px", marginBottom:"14px"}}>
                <div style={{fontSize:"13px", fontWeight:"800", color:C.text, marginBottom:"14px"}}>Generate My Personal Plan</div>
                <div style={{marginBottom:"10px"}}>
                  <label style={{display:"block", fontSize:"10px", letterSpacing:"2px", color:C.muted, fontWeight:"700", marginBottom:"4px"}}>YOUR HAIR TYPE</label>
                  <select value={hairType} onChange={e=>setHairType(e.target.value)} style={{width:"100%", background:C.white, border:`1.5px solid ${C.border}`, color:C.text, padding:"9px 11px", borderRadius:"8px", fontSize:"13px", boxSizing:"border-box"}}>
                    {["1A–1C Straight","2A–2C Wavy","3A–3B Curly","3C–4A Coily","4B Coily","4C Kinky-Coily","Chemically Relaxed","Color-Treated","Natural Locs"].map(h=><option key={h}>{h}</option>)}
                  </select>
                </div>
                <div style={{marginBottom:"14px"}}>
                  <label style={{display:"block", fontSize:"10px", letterSpacing:"2px", color:C.muted, fontWeight:"700", marginBottom:"4px"}}>UPCOMING SERVICE</label>
                  <select value={upcomingService} onChange={e=>setUpcomingService(e.target.value)} style={{width:"100%", background:C.white, border:`1.5px solid ${C.border}`, color:C.text, padding:"9px 11px", borderRadius:"8px", fontSize:"13px", boxSizing:"border-box"}}>
                    {["Braids / Box Braids","Knotless Braids","Cornrows","Locs / Loc Retwist","Silk Press","Natural Wash & Style","Balayage / Highlights","Full Color","Relaxer","Keratin Treatment","Haircut / Trim","Updo / Formal Style","Natural Twist Out","Weave / Extensions"].map(s=><option key={s}>{s}</option>)}
                  </select>
                </div>
                <button onClick={generatePersonalPlan} disabled={planLoading} style={{width:"100%", background:planLoading?C.dim:GRAD.hero, color:"#fff", border:"none", padding:"12px", borderRadius:"10px", fontSize:"13px", fontWeight:"800", cursor:planLoading?"not-allowed":"pointer"}}>
                  {planLoading?"Generating Plan...":"Generate My Plan"}
                </button>
              </div>
              {customPlan && (
                <div style={{background:C.white, border:`1px solid ${C.border}`, borderRadius:"14px", padding:"18px", maxHeight:"420px", overflowY:"auto"}}>
                  <div style={{fontSize:"11px", letterSpacing:"3px", color:C.mint, fontWeight:"800", marginBottom:"12px"}}>YOUR PERSONALIZED PLAN</div>
                  <div style={{fontSize:"12px", color:C.sub, lineHeight:"1.9", whiteSpace:"pre-wrap"}}>{customPlan}</div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

