const MOBILE_RESOURCES = [
  { name:"Go&Style", desc:"In-home hair styling service connecting mobile stylists with clients", url:"https://www.goandstyled.com", icon:"🏠" },
  { name:"Glamsquad", desc:"Luxury in-home hair, makeup and nail services", url:"https://www.glamsquad.com", icon:"✨" },
  { name:"Google: Mobile Stylists", desc:"Search for mobile and home-visit beauty professionals near you", url:"https://www.google.com/maps/search/mobile+hair+stylist+near+me", icon:"🔍" },
  { name:"Google: Accessible Salons", desc:"Find wheelchair-accessible and sensory-friendly salons", url:"https://www.google.com/maps/search/wheelchair+accessible+hair+salon+near+me", icon:"♿" },
  { name:"ADA National Network", desc:"Free ADA guidance, accommodation resources, and legal info", url:"https://adata.org", icon:"🏛" },
  { name:"DisabilityRights.gov", desc:"Official US government disability rights resource hub", url:"https://www.disabilityrights.gov", icon:"🏛" },
];

function AccessibilityTab() {
  const [view, setView] = useState("ai"); // ai | checklist | finder | resources | templates
  const [selectedNeed, setSelectedNeed] = useState(null);
  const [selectedScenario, setSelectedScenario] = useState(MESSAGE_SCENARIOS[0]);
  const [selectedPrompt, setSelectedPrompt] = useState("");
  const [customContext, setCustomContext] = useState("");
  const [clientName, setClientName] = useState("");
  const [salonName, setSalonName] = useState("Love That Idea Studio");
  const [stylistName, setStylistName] = useState("");
  const [tone, setTone] = useState("warm");
  const [generatedMsg, setGeneratedMsg] = useState(""); const [msgLoading, setMsgLoading] = useState(false);
  const [copied, setCopied] = useState(false);
  const [aiQ, setAiQ] = useState(""); const [aiHistory, setAiHistory] = useState([]); const [aiLoading, setAiLoading] = useState(false);
  const [checkedItems, setCheckedItems] = useState({});
  const [salonLocation, setSalonLocation] = useState("");
  const [geoStatus, setGeoStatus] = useState("idle");
  const [selectedNeeds, setSelectedNeeds] = useState([]);

  const NAV = [
    ["ai",        "✦",  "AI Hair Coach"],
    ["templates", "💬", "Message Generator"],
    ["checklist", "✅", "ADA Checklist"],
    ["finder",    "📍", "Accessible Salons"],
    ["resources", "📚", "Resources"],
  ];

  const totalChecked = Object.values(checkedItems).filter(Boolean).length;
  const totalItems = ADA_CHECKLIST.reduce((s,c)=>s+c.items.length,0);
  const compliancePct = Math.round(totalChecked/totalItems*100);

  function toggleNeed(id) {
    setSelectedNeeds(prev => prev.includes(id) ? prev.filter(n=>n!==id) : [...prev, id]);
  }

  function getLocation() {
    setGeoStatus("loading");
    navigator.geolocation.getCurrentPosition(
      pos=>{ setSalonLocation(`${pos.coords.latitude.toFixed(4)},${pos.coords.longitude.toFixed(4)}`); setGeoStatus("ok"); },
      ()=>setGeoStatus("error")
    );
  }

  function findAccessibleSalons() {
    const query = encodeURIComponent(`wheelchair accessible hair salon ${salonLocation || "near me"}`);
    window.open(`https://www.google.com/maps/search/${query}`, "_blank");
  }

  async function generateMessage() {
    if(!selectedPrompt && !customContext) return;
    setMsgLoading(true); setGeneratedMsg("");

    const needs = selectedNeeds.map(id=>ACCESS_NEEDS.find(n=>n.id===id)?.label).filter(Boolean).join(", ");
    const context = [
      selectedPrompt && `Scenario: ${selectedPrompt}`,
      customContext && `Additional context: ${customContext}`,
      clientName && `Client name: ${clientName}`,
      salonName && `Salon name: ${salonName}`,
      stylistName && `Stylist name: ${stylistName}`,
      needs && `Accessibility needs: ${needs}`,
    ].filter(Boolean).join(". ");

    const sys = `You are an expert hair salon accessibility AI communication assistant for Love That Idea. You help stylists, salon owners, and clients communicate clearly, warmly, and professionally about disability accommodations, accessibility features, and inclusive salon practices.

Write in a ${tone} tone. Be specific, empathetic, and actionable. Include all relevant accommodation details. Do not use jargon. Write as if the sender genuinely cares about inclusion.

For ${selectedScenario.label} messages:
- Be direct about what is needed or available
- Include practical next steps
- Express genuine welcome and care
- Keep it concise but complete (100–200 words)

Never use phrases like "differently abled" or "special needs"  -  use direct language like "wheelchair user," "Deaf," "blind," etc.`;

    const prompt = `Write a ${selectedScenario.label} message. ${context}`;

    try {
      const res = await fetch(CLAUDE_PROXY_URL, {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({ model:"claude-sonnet-4-20250514", max_tokens:600, system:sys, messages:[{role:"user",content:prompt}] })
      });
      const d = await res.json();
      setGeneratedMsg(d.content?.map(b=>b.text||"").join("")||"");
    } catch(e) { setGeneratedMsg("Connection error. Please try again."); }
    setMsgLoading(false);
  }

  async function askAccessAI() {
    if(!aiQ.trim()) return;
    setAiLoading(true);
    const needs = selectedNeeds.map(id=>ACCESS_NEEDS.find(n=>n.id===id)?.label).filter(Boolean);
    const msgs = [...aiHistory, {role:"user", content:aiQ}];
    const sys = `You are an expert Hair Coach AI specializing in disability inclusion, accessibility accommodations, and adaptive hair care for Love That Idea. You help:

1. STYLISTS understand how to adapt techniques and environments for clients with disabilities
2. CLIENTS with disabilities communicate their needs to salons confidently
3. SALON OWNERS implement ADA compliance and create genuinely welcoming spaces
4. CAREGIVERS advocate for their clients' hair care needs

You know: ADA requirements for salons, adaptive styling techniques, wheelchair-accessible shampoo bowl setups, sensory-friendly practices, communication strategies for Deaf/HoH clients, mobile styling services, and how to create trauma-informed, disability-affirming salon experiences.

${needs.length ? `The user has indicated these accessibility needs: ${needs.join(", ")}.` : ""}

Be warm, specific, and empowering. Use direct disability language. Under 220 words.`;

    try {
      const res = await fetch(CLAUDE_PROXY_URL, {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({ model:"claude-sonnet-4-20250514", max_tokens:800, system:sys, messages:msgs })
      });
      const d = await res.json();
      const ans = d.content?.map(b=>b.text||"").join("")||"";
      setAiHistory([...msgs, {role:"assistant",content:ans}]);
    } catch(e) { setAiHistory(prev=>[...prev,{role:"assistant",content:"Connection error. Try again."}]); }
    setAiQ(""); setAiLoading(false);
  }

  function copyMessage() {
    navigator.clipboard?.writeText(generatedMsg).then(()=>{setCopied(true);setTimeout(()=>setCopied(false),2000);});
  }

  const Box = ({ children, style = {} }) => (
    <div style={{background:C.white, border:`1px solid ${C.border}`, borderRadius:"14px", padding:"18px", ...style}}>{children}</div>
  );

  return (
    <div style={{flex:1, display:"flex", flexDirection:"column", overflow:"hidden", background:C.bg}}>
      {/* Sub-nav */}
      <div style={{background:C.white, borderBottom:`1px solid ${C.border}`, padding:"0 20px", display:"flex", gap:"2px", flexShrink:0, overflowX:"auto"}}>
        {NAV.map(([v,icon,label])=>(
          <button key={v} onClick={()=>setView(v)} style={{background:"none", border:"none", borderBottom:`3px solid ${view===v?C.mint:"transparent"}`, color:view===v?C.mint:C.muted, padding:"13px 14px 10px", fontSize:"12px", cursor:"pointer", fontWeight:view===v?"800":"500", whiteSpace:"nowrap"}}>
            {icon} {label}
          </button>
        ))}
      </div>

      <div style={{flex:1, overflowY:"auto", padding:"20px"}}>

        {/* -- AI HAIR COACH -- */}
        {view==="ai" && (
          <div style={{display:"grid", gridTemplateColumns:"1fr 320px", gap:"20px", alignItems:"start"}}>
            <div>
              {/* Hero */}
              <div style={{background:`linear-gradient(135deg, #1A3D2B, #0D6644)`, borderRadius:"16px", padding:"24px", marginBottom:"20px", color:"#fff"}}>
                <div style={{fontSize:"10px", letterSpacing:"3px", color:"rgba(255,255,255,0.6)", marginBottom:"8px"}}>POWERED BY CLAUDE AI</div>
                <div style={{fontSize:"24px", fontWeight:"900", marginBottom:"8px"}}>♿ Hair Coach  -  Accessibility Assistant</div>
                <div style={{fontSize:"13px", color:"rgba(255,255,255,0.8)", lineHeight:"1.7", maxWidth:"500px"}}>
                  Your AI Hair Coach specializes in helping stylists adapt their craft, clients communicate their needs, and salons become genuinely accessible spaces for everyone.
                </div>
              </div>

              {/* Quick prompts by role */}
              <Box style={{marginBottom:"16px"}}>
                <div style={{fontSize:"10px", letterSpacing:"3px", color:C.muted, fontWeight:"700", marginBottom:"12px"}}>QUICK QUESTIONS BY ROLE</div>
                <div style={{display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:"10px"}}>
                  {[
                    {role:"I'm a Client", color:"#0891B2", prompts:["How do I tell a salon I use a wheelchair?","What questions should I ask before booking?","How can I get a mobile stylist?","What are my rights if a salon won't accommodate me?"]},
                    {role:"I'm a Stylist", color:"#27AE78", prompts:["How do I shampoo a wheelchair user?","How do I make my station accessible?","How do I communicate with a Deaf client?","What do I do if I don't know how to help?"]},
                    {role:"I'm a Salon Owner", color:"#7C3AED", prompts:["What ADA requirements apply to my salon?","How do I train my staff on disability inclusion?","How do I market my salon as accessible?","How do I handle an accessibility complaint?"]},
                  ].map(cat=>(
                    <div key={cat.role} style={{background:cat.color+"0D", border:`1px solid ${cat.color}33`, borderRadius:"10px", padding:"12px"}}>
                      <div style={{fontSize:"12px", fontWeight:"800", color:cat.color, marginBottom:"8px"}}>{cat.role}</div>
                      {cat.prompts.map(p=>(
                        <button key={p} onClick={()=>setAiQ(p)} style={{display:"block", width:"100%", textAlign:"left", background:"rgba(255,255,255,0.7)", border:`1px solid ${cat.color}22`, borderRadius:"6px", padding:"6px 9px", fontSize:"11px", color:C.sub, cursor:"pointer", marginBottom:"4px", lineHeight:"1.4"}}>{p}</button>
                      ))}
                    </div>
                  ))}
                </div>
              </Box>

              {/* Chat */}
              <div style={{background:C.white, border:`1px solid ${C.border}`, borderRadius:"14px", padding:"16px", minHeight:"300px", maxHeight:"420px", overflowY:"auto", marginBottom:"12px", display:"flex", flexDirection:"column", gap:"10px"}}>
                {aiHistory.length===0 && (
                  <div style={{textAlign:"center", color:C.muted, padding:"50px 0"}}>
                    <div style={{fontSize:"40px", marginBottom:"12px"}}>♿</div>
                    <div style={{fontSize:"15px", fontWeight:"700", color:C.text}}>Accessible Hair Care Coach</div>
                    <div style={{fontSize:"12px", marginTop:"6px", lineHeight:"1.7"}}>Ask anything about accommodating disability in the salon  -  for clients, stylists, and owners.</div>
                  </div>
                )}
                {aiHistory.map((m,i)=>(
                  <div key={i} style={{display:"flex", justifyContent:m.role==="user"?"flex-end":"flex-start", minWidth:0 }}>
                    <div style={{maxWidth:"86%", padding:"11px 15px", borderRadius:m.role==="user"?"16px 16px 4px 16px":"16px 16px 16px 4px", background:m.role==="user"?GRAD.hero:C.bg, color:m.role==="user"?"#fff":C.text, fontSize:"13px",wordBreak:"break-word",overflowWrap:"break-word",whiteSpace:"pre-wrap", lineHeight:"1.7", border:m.role==="assistant"?`1px solid ${C.border}`:"none"}}>
                      {m.content}
                    </div>
                  </div>
                ))}
                {aiLoading && (
                  <div style={{display:"flex", gap:"5px", padding:"12px", background:C.bg, border:`1px solid ${C.border}`, borderRadius:"16px 16px 16px 4px", width:"fit-content"}}>
                    {[0,1,2].map(i=><div key={i} style={{width:"7px", height:"7px", borderRadius:"50%", background:C.mint, animation:`pulse 1s ease ${i*.2}s infinite`}}/>)}
                  </div>
                )}
              </div>
              <div style={{display:"flex", gap:"8px"}}>
                <input value={aiQ} onChange={e=>setAiQ(e.target.value)} onKeyDown={e=>e.key==="Enter"&&askAccessAI()} placeholder="Ask about accessibility, accommodations, or inclusive hair care..."
                  style={{flex:1, background:C.white, border:`1.5px solid ${C.border}`, color:C.text, padding:"11px 14px", borderRadius:"10px", fontSize:"13px"}}/>
                <button onClick={askAccessAI} disabled={aiLoading} style={{background:aiLoading?C.dim:GRAD.hero, color:"#fff", border:"none", padding:"11px 20px", borderRadius:"10px", fontSize:"13px", fontWeight:"800", cursor:aiLoading?"not-allowed":"pointer"}}>Ask</button>
                {aiHistory.length>0&&<button onClick={()=>setAiHistory([])} style={{background:C.white, border:`1px solid ${C.border}`, color:C.muted, padding:"11px 14px", borderRadius:"10px", fontSize:"12px", cursor:"pointer"}}>Clear</button>}
              </div>
            </div>

            {/* Right: My Needs selector */}
            <div style={{position:"sticky", top:"20px"}}>
              <Box style={{marginBottom:"14px"}}>
                <div style={{fontSize:"13px", fontWeight:"800", color:C.text, marginBottom:"4px"}}>My Accessibility Profile</div>
                <div style={{fontSize:"11px", color:C.muted, marginBottom:"12px"}}>Select your needs  -  the AI will personalize its responses.</div>
                <div style={{display:"flex", flexDirection:"column", gap:"6px"}}>
                  {ACCESS_NEEDS.map(need=>{
                    const sel = selectedNeeds.includes(need.id);
                    return (
                      <button key={need.id} onClick={()=>toggleNeed(need.id)}
                        style={{display:"flex", gap:"10px", alignItems:"center", background:sel?need.color+"14":C.bg, border:`1.5px solid ${sel?need.color:C.border}`, borderRadius:"10px", padding:"10px 12px", cursor:"pointer", textAlign:"left", transition:"all 0.15s"}}>
                        <span style={{fontSize:"18px", flexShrink:0}}>{need.icon}</span>
                        <div style={{flex:1}}>
                          <div style={{fontSize:"12px", fontWeight:"700", color:sel?need.color:C.text}}>{need.label}</div>
                          <div style={{fontSize:"10px", color:C.muted, lineHeight:"1.3", marginTop:"1px"}}>{need.desc.split(",")[0]}</div>
                        </div>
                        {sel && <span style={{color:need.color, fontWeight:"900", fontSize:"14px", flexShrink:0}}>✓</span>}
                      </button>
                    );
                  })}
                </div>
                {selectedNeeds.length>0 && (
                  <button onClick={()=>setSelectedNeeds([])} style={{width:"100%", background:"transparent", border:`1px solid ${C.dim}`, color:C.muted, padding:"7px", borderRadius:"8px", fontSize:"11px", cursor:"pointer", marginTop:"8px"}}>Clear Selection</button>
                )}
              </Box>

              {/* Adaptive styling tips */}
              <Box>
                <div style={{fontSize:"10px", letterSpacing:"3px", color:C.mint, fontWeight:"700", marginBottom:"10px"}}>ADAPTIVE STYLING TIPS</div>
                {[
                  ["Wheelchair Shampoo","Use a portable shampoo basin or recline the client. Drape towels for comfort. Adjust station height."],
                  ["Sensory Clients","Warn before touching. Use unscented products. Offer noise-canceling headphones. Allow extra breaks."],
                  ["Deaf Clients","Face them when speaking. Write key info. Use mirrors to maintain eye contact. Learn 5–10 basic ASL signs."],
                  ["Fatigue / Chronic Illness","Shorter sessions with breaks. Reclining option. Prioritize client comfort over speed."],
                ].map(([title,tip])=>(
                  <div key={title} style={{marginBottom:"10px", paddingBottom:"10px", borderBottom:`1px solid ${C.dim}`}}>
                    <div style={{fontSize:"12px", fontWeight:"700", color:C.text, marginBottom:"3px"}}>{title}</div>
                    <div style={{fontSize:"11px", color:C.muted, lineHeight:"1.5"}}>{tip}</div>
                  </div>
                ))}
              </Box>
            </div>
          </div>
        )}

        {/* -- MESSAGE GENERATOR -- */}
        {view==="templates" && (
          <div style={{display:"grid", gridTemplateColumns:"1fr 380px", gap:"20px", alignItems:"start"}}>
            <div>
              <div style={{fontSize:"22px", fontWeight:"900", color:C.text, marginBottom:"4px"}}>Accessibility Message Generator</div>
              <div style={{fontSize:"13px", color:C.muted, marginBottom:"20px"}}>Claude writes clear, warm, professional messages about accessibility needs between clients, stylists, and salon owners.</div>

              {/* Scenario selector */}
              <Box style={{marginBottom:"16px"}}>
                <div style={{fontSize:"10px", letterSpacing:"3px", color:C.muted, fontWeight:"700", marginBottom:"10px"}}>WHO IS SENDING?</div>
                <div style={{display:"grid", gridTemplateColumns:"1fr 1fr", gap:"8px"}}>
                  {MESSAGE_SCENARIOS.map(s=>(
                    <button key={s.id} onClick={()=>{setSelectedScenario(s);setSelectedPrompt("");setGeneratedMsg("");}}
                      style={{background:selectedScenario.id===s.id?s.color+"18":C.bg, border:`1.5px solid ${selectedScenario.id===s.id?s.color:C.border}`, borderRadius:"10px", padding:"12px", cursor:"pointer", textAlign:"left", transition:"all 0.15s"}}>
                      <div style={{display:"flex", gap:"8px", alignItems:"center", marginBottom:"4px"}}>
                        <span style={{fontSize:"18px"}}>{s.icon}</span>
                        <div style={{fontSize:"12px", fontWeight:"800", color:selectedScenario.id===s.id?s.color:C.text}}>{s.label}</div>
                      </div>
                      <div style={{fontSize:"10px", color:C.muted, lineHeight:"1.4"}}>{s.desc}</div>
                    </button>
                  ))}
                </div>
              </Box>

              {/* Prompt selection */}
              <Box style={{marginBottom:"16px"}}>
                <div style={{fontSize:"10px", letterSpacing:"3px", color:C.muted, fontWeight:"700", marginBottom:"10px"}}>CHOOSE A SCENARIO OR DESCRIBE YOUR OWN</div>
                <div style={{display:"flex", flexDirection:"column", gap:"6px", marginBottom:"12px"}}>
                  {selectedScenario.prompts.map(p=>(
                    <button key={p} onClick={()=>setSelectedPrompt(p)}
                      style={{background:selectedPrompt===p?selectedScenario.color+"18":C.bg, border:`1.5px solid ${selectedPrompt===p?selectedScenario.color:C.border}`, borderRadius:"8px", padding:"10px 13px", cursor:"pointer", textAlign:"left", fontSize:"13px", color:selectedPrompt===p?selectedScenario.color:C.sub, fontWeight:selectedPrompt===p?"700":"400", transition:"all 0.15s"}}>
                      {p}
                    </button>
                  ))}
                </div>
                <div>
                  <label style={{display:"block", fontSize:"10px", letterSpacing:"2px", color:C.muted, fontWeight:"700", marginBottom:"5px"}}>ADD YOUR SPECIFIC DETAILS</label>
                  <textarea value={customContext} onChange={e=>setCustomContext(e.target.value)} placeholder="e.g. I use an electric wheelchair and need the shampoo bowl to be at accessible height. My appointment is Tuesday at 2pm..." rows={3}
                    style={{width:"100%", background:C.bg, border:`1.5px solid ${C.border}`, color:C.text, padding:"10px 12px", borderRadius:"8px", fontSize:"13px", boxSizing:"border-box", resize:"vertical"}}/>
                </div>
              </Box>

              {/* Personalization */}
              <Box style={{marginBottom:"16px"}}>
                <div style={{fontSize:"10px", letterSpacing:"3px", color:C.muted, fontWeight:"700", marginBottom:"10px"}}>PERSONALIZE</div>
                <div style={{display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:"10px", marginBottom:"12px"}}>
                  {[["Client Name",clientName,setClientName],["Salon Name",salonName,setSalonName],["Stylist Name",stylistName,setStylistName]].map(([l,v,sv])=>(
                    <div key={l}>
                      <label style={{display:"block", fontSize:"10px", color:C.muted, fontWeight:"700", marginBottom:"4px"}}>{l.toUpperCase()}</label>
                      <input value={v} onChange={e=>sv(e.target.value)} style={{width:"100%", background:C.bg, border:`1.5px solid ${C.border}`, color:C.text, padding:"8px 10px", borderRadius:"8px", fontSize:"12px", boxSizing:"border-box"}}/>
                    </div>
                  ))}
                </div>
                <div>
                  <label style={{display:"block", fontSize:"10px", color:C.muted, fontWeight:"700", marginBottom:"6px"}}>TONE</label>
                  <div style={{display:"flex", gap:"8px"}}>
                    {[["warm","Warm & Friendly"],["professional","Professional"],["formal","Formal / Legal"],["direct","Direct & Clear"]].map(([v,l])=>(
                      <button key={v} onClick={()=>setTone(v)} style={{flex:1, background:tone===v?C.mint:"#F9F9F9", color:tone===v?"#fff":C.muted, border:`1px solid ${tone===v?C.mint:C.dim}`, padding:"7px 6px", borderRadius:"8px", fontSize:"11px", fontWeight:"700", cursor:"pointer"}}>{l}</button>
                    ))}
                  </div>
                </div>
              </Box>

              {/* Accessibility needs */}
              <Box style={{marginBottom:"16px"}}>
                <div style={{fontSize:"10px", letterSpacing:"3px", color:C.muted, fontWeight:"700", marginBottom:"10px"}}>ACCESSIBILITY NEEDS TO INCLUDE</div>
                <div style={{display:"flex", gap:"7px", flexWrap:"wrap"}}>
                  {ACCESS_NEEDS.map(n=>{
                    const sel=selectedNeeds.includes(n.id);
                    return (
                      <button key={n.id} onClick={()=>toggleNeed(n.id)}
                        style={{background:sel?n.color+"18":"#F9F9F9", border:`1px solid ${sel?n.color:C.dim}`, color:sel?n.color:C.muted, padding:"6px 13px", borderRadius:"20px", fontSize:"11px", fontWeight:"700", cursor:"pointer"}}>
                        {n.icon} {n.label}
                      </button>
                    );
                  })}
                </div>
              </Box>

              <button onClick={generateMessage} disabled={msgLoading||(!selectedPrompt&&!customContext)}
                style={{width:"100%", background:msgLoading||(!selectedPrompt&&!customContext)?C.dim:GRAD.hero, color:msgLoading||(!selectedPrompt&&!customContext)?C.muted:"#fff", border:"none", padding:"14px", borderRadius:"12px", fontSize:"15px", fontWeight:"900", cursor:msgLoading||(!selectedPrompt&&!customContext)?"not-allowed":"pointer"}}>
                {msgLoading?"✦ Writing your message...":"✦ Generate Message with AI"}
              </button>
            </div>

            {/* Generated message preview */}
            <div style={{position:"sticky", top:"20px"}}>
              {generatedMsg ? (
                <div style={{background:C.white, border:`2px solid ${C.mint}`, borderRadius:"16px", overflow:"hidden", boxShadow:"0 4px 20px rgba(39,174,120,0.15)"}}>
                  <div style={{height:"5px", background:GRAD.hero}}/>
                  <div style={{padding:"20px"}}>
                    <div style={{display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:"14px"}}>
                      <div>
                        <div style={{fontSize:"10px", letterSpacing:"3px", color:C.mint, fontWeight:"700"}}>GENERATED MESSAGE</div>
                        <div style={{fontSize:"12px", color:C.muted, marginTop:"2px"}}>{selectedScenario.label} · {tone} tone</div>
                      </div>
                      <button onClick={copyMessage} style={{background:copied?C.mintLight:C.bg, border:`1.5px solid ${copied?C.mint:C.border}`, color:copied?C.mintDark:C.muted, padding:"7px 14px", borderRadius:"8px", fontSize:"12px", fontWeight:"700", cursor:"pointer"}}>
                        {copied?"Copied!":"Copy"}
                      </button>
                    </div>
                    <div style={{background:C.bg, borderRadius:"10px", padding:"16px", fontSize:"13px", color:C.text, lineHeight:"1.9", whiteSpace:"pre-wrap", marginBottom:"14px"}}>
                      {generatedMsg}
                    </div>
                    <div style={{display:"grid", gridTemplateColumns:"1fr 1fr", gap:"8px"}}>
                      <button onClick={()=>{setSelectedScenario(prev=>({...prev}));generateMessage();}} style={{background:C.mintLight, border:`1.5px solid ${C.mint}`, color:C.mintDark, padding:"9px", borderRadius:"8px", fontSize:"12px", fontWeight:"700", cursor:"pointer"}}>Regenerate</button>
                      <button onClick={()=>{ const blob=new Blob([generatedMsg],{type:"text/plain"}); const a=document.createElement("a"); a.href=URL.createObjectURL(blob); a.download="accessibility-message.txt"; a.click(); }} style={{background:C.bg, border:`1px solid ${C.border}`, color:C.sub, padding:"9px", borderRadius:"8px", fontSize:"12px", fontWeight:"600", cursor:"pointer"}}>Download .txt</button>
                    </div>
                  </div>
                </div>
              ) : (
                <div style={{background:C.white, border:`1px solid ${C.border}`, borderRadius:"16px", padding:"40px 24px", textAlign:"center"}}>
                  <div style={{fontSize:"40px", marginBottom:"12px"}}>💬</div>
                  <div style={{fontSize:"15px", fontWeight:"700", color:C.text, marginBottom:"6px"}}>Your message will appear here</div>
                  <div style={{fontSize:"12px", color:C.muted, lineHeight:"1.7"}}>Select a scenario and prompt on the left, then click Generate.</div>
                </div>
              )}

              {/* Sending channels */}
              {generatedMsg && (
                <Box style={{marginTop:"14px"}}>
                  <div style={{fontSize:"10px", letterSpacing:"3px", color:C.muted, fontWeight:"700", marginBottom:"10px"}}>SEND VIA</div>
                  <div style={{display:"grid", gridTemplateColumns:"1fr 1fr", gap:"8px"}}>
                    {[["📱 SMS", ()=>window.open(`sms:?body=${encodeURIComponent(generatedMsg)}`)],["✉ Email", ()=>window.open(`mailto:?body=${encodeURIComponent(generatedMsg)}&subject=${encodeURIComponent("Accessibility Accommodation Request")}`)],["💬 Copy", copyMessage],["📄 Print", ()=>window.print()]].map(([label,action])=>(
                      <button key={label} onClick={action} style={{background:C.bg, border:`1px solid ${C.border}`, color:C.sub, padding:"9px", borderRadius:"8px", fontSize:"12px", fontWeight:"600", cursor:"pointer"}}>{label}</button>
                    ))}
                  </div>
                </Box>
              )}
            </div>
          </div>
        )}

        {/* -- ADA CHECKLIST -- */}
        {view==="checklist" && (
          <div>
            <div style={{display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:"20px", flexWrap:"wrap", gap:"12px"}}>
              <div>
                <div style={{fontSize:"22px", fontWeight:"900", color:C.text, marginBottom:"4px"}}>ADA Accessibility Checklist</div>
                <div style={{fontSize:"13px", color:C.muted}}>For salon owners and stylists  -  evaluate your space against ADA standards.</div>
              </div>
              <div style={{background:C.white, border:`1px solid ${C.border}`, borderRadius:"14px", padding:"16px", textAlign:"center", minWidth:"160px"}}>
                <div style={{fontSize:"32px", fontWeight:"900", color:compliancePct>=80?C.mint:compliancePct>=50?C.amber:"#E53E3E"}}>{compliancePct}%</div>
                <div style={{fontSize:"11px", color:C.muted, fontWeight:"700"}}>Accessibility Score</div>
                <div style={{fontSize:"10px", color:C.muted, marginTop:"2px"}}>{totalChecked}/{totalItems} items</div>
                <div style={{height:"6px", background:C.dim, borderRadius:"3px", marginTop:"8px", overflow:"hidden"}}>
                  <div style={{height:"100%", width:`${compliancePct}%`, background:GRAD.hero, borderRadius:"3px", transition:"width 0.4s"}}/>
                </div>
              </div>
            </div>

            {/* Score feedback */}
            <div style={{background:compliancePct>=80?C.mintLight:compliancePct>=50?"#FFFBEB":"#FEF2F2", border:`1px solid ${compliancePct>=80?C.mint:compliancePct>=50?"#FCD34D":"#FECACA"}`, borderRadius:"12px", padding:"14px 18px", marginBottom:"20px", fontSize:"13px", color:compliancePct>=80?C.mintDark:compliancePct>=50?"#92400E":"#DC2626"}}>
              {compliancePct>=80 ? "Excellent! Your salon demonstrates strong accessibility commitment. Share your score to attract clients with disabilities."
               : compliancePct>=50 ? "Good progress. Several areas still need attention. Use this checklist as a priority roadmap for improvements."
               : totalChecked===0 ? "Start checking items to evaluate your salon's accessibility. Every improvement makes a real difference for clients."
               : "Your salon has significant accessibility gaps. Prioritize entrance, movement, and styling station items first. Consider consulting an ADA specialist."}
            </div>

            {ADA_CHECKLIST.map((cat,ci)=>(
              <div key={ci} style={{background:C.white, border:`1px solid ${C.border}`, borderRadius:"14px", padding:"18px", marginBottom:"14px"}}>
                <div style={{display:"flex", alignItems:"center", gap:"10px", marginBottom:"14px"}}>
                  <span style={{fontSize:"22px"}}>{cat.icon}</span>
                  <div style={{fontSize:"15px", fontWeight:"800", color:C.text}}>{cat.category}</div>
                  <div style={{marginLeft:"auto", fontSize:"11px", color:C.muted}}>
                    {cat.items.filter((_,ii)=>checkedItems[`${ci}-${ii}`]).length}/{cat.items.length} done
                  </div>
                </div>
                <div style={{display:"flex", flexDirection:"column", gap:"6px"}}>
                  {cat.items.map((item,ii)=>{
                    const key=`${ci}-${ii}`;
                    const checked=!!checkedItems[key];
                    return (
                      <label key={ii} style={{display:"flex", gap:"12px", alignItems:"flex-start", padding:"10px 12px", background:checked?C.mintLight:C.bg, borderRadius:"8px", cursor:"pointer", border:`1px solid ${checked?C.mint:C.dim}`, transition:"all 0.15s"}}>
                        <input type="checkbox" checked={checked} onChange={()=>setCheckedItems(prev=>({...prev,[key]:!prev[key]}))} style={{accentColor:C.mint, marginTop:"2px", flexShrink:0, width:"16px", height:"16px"}}/>
                        <span style={{fontSize:"13px", color:checked?C.mintDark:C.sub, textDecoration:checked?"line-through":"none", lineHeight:"1.5"}}>{item}</span>
                      </label>
                    );
                  })}
                </div>
              </div>
            ))}

            <div style={{background:C.white, border:`1px solid ${C.border}`, borderRadius:"14px", padding:"18px", marginBottom:"14px"}}>
              <div style={{fontSize:"13px", fontWeight:"800", color:C.text, marginBottom:"10px"}}>Next Steps</div>
              {[
                {label:"Get a Free ADA Consultation", url:"https://adata.org/techassist", desc:"Free technical assistance from the ADA National Network"},
                {label:"Find an ADA Consultant", url:"https://www.access-board.gov", desc:"US Access Board  -  federal standards and guidance"},
                {label:"ADA Tax Incentives for Small Business", url:"https://www.ada.gov/resources/disability-tax-incentives/", desc:"Up to $5,000 tax credit for accessibility improvements"},
              ].map(r=>(
                <button key={r.label} onClick={()=>window.open(r.url,"_blank")} style={{display:"flex", gap:"12px", alignItems:"center", width:"100%", background:C.bg, border:`1px solid ${C.border}`, borderRadius:"10px", padding:"12px 14px", cursor:"pointer", marginBottom:"8px", textAlign:"left"}}>
                  <div style={{flex:1}}>
                    <div style={{fontSize:"13px", fontWeight:"700", color:C.text}}>{r.label}</div>
                    <div style={{fontSize:"11px", color:C.muted, marginTop:"2px"}}>{r.desc}</div>
                  </div>
                  <span style={{color:C.mint, fontWeight:"700", fontSize:"14px"}}>→</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* -- FIND ACCESSIBLE SALONS -- */}
        {view==="finder" && (
          <div>
            <div style={{fontSize:"22px", fontWeight:"900", color:C.text, marginBottom:"4px"}}>Find Accessible Salons Near You</div>
            <div style={{fontSize:"13px", color:C.muted, marginBottom:"20px"}}>Search for wheelchair accessible salons and mobile stylists in your area.</div>

            {/* Location */}
            <Box style={{marginBottom:"16px"}}>
              <div style={{fontSize:"13px", fontWeight:"800", color:C.text, marginBottom:"12px"}}>Your Location</div>
              <div style={{display:"flex", gap:"10px", marginBottom:"12px"}}>
                <input value={salonLocation} onChange={e=>setSalonLocation(e.target.value)} placeholder="City, state or zip code..."
                  style={{flex:1, background:C.bg, border:`1.5px solid ${C.border}`, color:C.text, padding:"10px 14px", borderRadius:"8px", fontSize:"13px"}}/>
                <button onClick={getLocation} style={{background:geoStatus==="ok"?C.mintLight:GRAD.hero, color:geoStatus==="ok"?C.mintDark:"#fff", border:geoStatus==="ok"?`1.5px solid ${C.mint}`:"none", padding:"10px 18px", borderRadius:"8px", fontSize:"12px", fontWeight:"700", cursor:"pointer", whiteSpace:"nowrap"}}>
                  {geoStatus==="loading"?"Locating...":geoStatus==="ok"?"GPS Active":"Use GPS"}
                </button>
              </div>
              <div style={{fontSize:"10px", letterSpacing:"2px", color:C.muted, fontWeight:"700", marginBottom:"8px"}}>SPECIFIC NEEDS TO SEARCH FOR</div>
              <div style={{display:"flex", gap:"7px", flexWrap:"wrap"}}>
                {ACCESS_NEEDS.slice(0,5).map(n=>{
                  const sel=selectedNeeds.includes(n.id);
                  return (
                    <button key={n.id} onClick={()=>toggleNeed(n.id)} style={{background:sel?n.color+"18":"#F9F9F9", border:`1px solid ${sel?n.color:C.dim}`, color:sel?n.color:C.muted, padding:"6px 13px", borderRadius:"20px", fontSize:"11px", fontWeight:"700", cursor:"pointer"}}>
                      {n.icon} {n.label}
                    </button>
                  );
                })}
              </div>
            </Box>

            {/* Search buttons */}
            <div style={{display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:"12px", marginBottom:"20px"}}>
              {[
                {label:"Wheelchair Accessible Salons", icon:"♿", action:()=>window.open(`https://www.google.com/maps/search/${encodeURIComponent("wheelchair accessible hair salon "+(salonLocation||"near me"))}`,"_blank"), color:"#0891B2"},
                {label:"Mobile Stylists Near Me", icon:"🏠", action:()=>window.open(`https://www.google.com/maps/search/${encodeURIComponent("mobile hair stylist home visit "+(salonLocation||"near me"))}`,"_blank"), color:"#27AE78"},
                {label:"Sensory-Friendly Salons", icon:"🌀", action:()=>window.open(`https://www.google.com/maps/search/${encodeURIComponent("sensory friendly quiet hair salon "+(salonLocation||"near me"))}`,"_blank"), color:"#EC4899"},
              ].map(btn=>(
                <button key={btn.label} onClick={btn.action}
                  style={{background:C.white, border:`1.5px solid ${btn.color}33`, borderRadius:"14px", padding:"20px 16px", cursor:"pointer", textAlign:"center", transition:"all 0.15s"}}
                  onMouseEnter={e=>{e.currentTarget.style.borderColor=btn.color;e.currentTarget.style.background=btn.color+"0D";e.currentTarget.style.transform="translateY(-2px)";}}
                  onMouseLeave={e=>{e.currentTarget.style.borderColor=btn.color+"33";e.currentTarget.style.background=C.white;e.currentTarget.style.transform="translateY(0)";}}>
                  <div style={{fontSize:"28px", marginBottom:"8px"}}>{btn.icon}</div>
                  <div style={{fontSize:"13px", fontWeight:"800", color:C.text, marginBottom:"4px"}}>{btn.label}</div>
                  <div style={{fontSize:"10px", color:btn.color, fontWeight:"700"}}>Search Google Maps →</div>
                </button>
              ))}
            </div>

            {/* Questions to ask a salon */}
            <Box style={{marginBottom:"16px"}}>
              <div style={{fontSize:"13px", fontWeight:"800", color:C.text, marginBottom:"14px"}}>Questions to Ask a Salon Before Booking</div>
              <div style={{display:"grid", gridTemplateColumns:"1fr 1fr", gap:"8px"}}>
                {[
                  "Is your entrance wheelchair accessible with no steps?",
                  "Can I remain in my wheelchair for the service?",
                  "Do you have an accessible shampoo bowl or portable basin?",
                  "Can you accommodate a service animal?",
                  "Do you offer fragrance-free or unscented products?",
                  "Do you have quiet hours or a private room option?",
                  "Is there accessible parking within 60 feet of your door?",
                  "Can a caregiver or companion accompany me?",
                  "Do you have staff who can communicate in ASL or writing?",
                  "Do you offer mobile or in-home appointments?",
                ].map((q,i)=>(
                  <button key={i} onClick={()=>{setSelectedPrompt(q);setView("templates");setSelectedScenario(MESSAGE_SCENARIOS[0]);}}
                    style={{background:C.bg, border:`1px solid ${C.border}`, borderRadius:"8px", padding:"10px 13px", cursor:"pointer", textAlign:"left", fontSize:"12px", color:C.sub, lineHeight:"1.5", transition:"all 0.15s"}}
                    onMouseEnter={e=>{e.currentTarget.style.borderColor=C.mint;e.currentTarget.style.color=C.text;}}
                    onMouseLeave={e=>{e.currentTarget.style.borderColor=C.border;e.currentTarget.style.color=C.sub;}}>
                    "{q}"
                    <div style={{fontSize:"10px", color:C.mint, marginTop:"4px", fontWeight:"700"}}>Generate message →</div>
                  </button>
                ))}
              </div>
            </Box>
          </div>
        )}

        {/* -- RESOURCES -- */}
        {view==="resources" && (
          <div>
            <div style={{fontSize:"22px", fontWeight:"900", color:C.text, marginBottom:"4px"}}>Accessibility Resources</div>
            <div style={{fontSize:"13px", color:C.muted, marginBottom:"20px"}}>Organizations, mobile services, legal rights, and guides for accessible hair care.</div>

            <div style={{display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(280px,1fr))", gap:"14px", marginBottom:"24px"}}>
              {MOBILE_RESOURCES.map(r=>(
                <button key={r.name} onClick={()=>window.open(r.url,"_blank")}
                  style={{background:C.white, border:`1.5px solid ${C.border}`, borderRadius:"14px", padding:"18px", cursor:"pointer", textAlign:"left", transition:"all 0.2s"}}
                  onMouseEnter={e=>{e.currentTarget.style.borderColor=C.mint;e.currentTarget.style.transform="translateY(-2px)";e.currentTarget.style.boxShadow=`0 8px 20px rgba(39,174,120,0.12)`;}}
                  onMouseLeave={e=>{e.currentTarget.style.borderColor=C.border;e.currentTarget.style.transform="translateY(0)";e.currentTarget.style.boxShadow="none";}}>
                  <div style={{fontSize:"28px", marginBottom:"8px"}}>{r.icon}</div>
                  <div style={{fontSize:"14px", fontWeight:"800", color:C.text, marginBottom:"4px"}}>{r.name}</div>
                  <div style={{fontSize:"12px", color:C.muted, lineHeight:"1.5", marginBottom:"10px"}}>{r.desc}</div>
                  <div style={{fontSize:"11px", color:C.mint, fontWeight:"700"}}>Open Resource →</div>
                </button>
              ))}
            </div>

            {/* Know your rights */}
            <Box style={{marginBottom:"16px"}}>
              <div style={{fontSize:"14px", fontWeight:"800", color:C.text, marginBottom:"14px"}}>Know Your Rights  -  ADA and Hair Salons</div>
              {[
                {q:"Can a salon refuse to serve me because I use a wheelchair?", a:"No. Under Title III of the ADA, places of public accommodation (including hair salons) must not discriminate against people with disabilities. They must make reasonable modifications to policies and practices to serve you."},
                {q:"What counts as a 'reasonable modification' for a salon?", a:"Moving a chair to accommodate a wheelchair, using a portable shampoo basin, allowing a caregiver to accompany you, providing written consultation, or permitting a service animal are all reasonable modifications."},
                {q:"Can I file a complaint if a salon denies me service?", a:"Yes. File with the US Department of Justice (ADA.gov), your state's civil rights division, or consult a disability rights attorney. The DOJ accepts online ADA complaints."},
                {q:"Does the ADA require salons to make physical changes to their building?", a:"Yes  -  if 'readily achievable' (i.e., not too costly or difficult). Small salons may face less obligation than large chains. Barrier removal is required when it can be accomplished without much difficulty or expense."},
                {q:"Are mobile stylists covered under the ADA?", a:"When a mobile stylist operates as a public accommodation, ADA protections apply. They must not refuse service based on disability and must make reasonable accommodations."},
              ].map((item,i)=>(
                <div key={i} style={{marginBottom:"12px", padding:"14px", background:C.bg, borderRadius:"10px", borderLeft:`4px solid ${C.mint}`}}>
                  <div style={{fontSize:"13px", fontWeight:"700", color:C.text, marginBottom:"6px"}}>{item.q}</div>
                  <div style={{fontSize:"12px", color:C.sub, lineHeight:"1.7"}}>{item.a}</div>
                </div>
              ))}
              <button onClick={()=>window.open("https://www.ada.gov/topics/title-iii-public-accommodations/","_blank")} style={{width:"100%", background:GRAD.hero, color:"#fff", border:"none", padding:"12px", borderRadius:"10px", fontSize:"13px", fontWeight:"800", cursor:"pointer", marginTop:"8px"}}>
                Read Full ADA Title III Guide →
              </button>
            </Box>

            {/* For stylists */}
            <Box>
              <div style={{fontSize:"14px", fontWeight:"800", color:C.text, marginBottom:"14px"}}>For Stylists  -  Adaptive Techniques Quick Reference</div>
              <div style={{display:"grid", gridTemplateColumns:"1fr 1fr", gap:"12px"}}>
                {[
                  {title:"Wheelchair Shampooing", steps:["Remove or slide back styling chair","Position client's chair at bowl angle or use portable basin","Drape extra towels for comfort and waterproofing","Use a detachable sprayer for better control","Take breaks  -  let client rest their neck if needed"]},
                  {title:"Serving Deaf / HoH Clients", steps:["Face the client directly  -  never talk behind them","Write key information (price, time, steps) on paper","Use the mirror to maintain eye contact while styling","Learn 5–10 basic ASL signs (good, great, done, hurt, soft, ok)","Ask at start: 'Do you lip-read or prefer written notes?'"]},
                  {title:"Sensory-Sensitive Clients", steps:["Ask before touching  -  especially the scalp and neck","Warn before using dryer, clippers, or strong products","Offer noise-canceling headphones or quiet areas","Use unscented or fragrance-free products on request","Allow extra time  -  no rushed transitions between steps"]},
                  {title:"Fatigue / Chronic Illness", steps:["Offer reclined chair or additional neck pillows","Break the service into multiple short sessions if needed","Let client dictate pace  -  they know their energy limits","Have water and snacks nearby","Avoid scheduling back-to-back with complex services  -  allow rest time"]},
                ].map(g=>(
                  <div key={g.title} style={{background:C.bg, borderRadius:"10px", padding:"14px"}}>
                    <div style={{fontSize:"13px", fontWeight:"800", color:C.text, marginBottom:"8px"}}>{g.title}</div>
                    {g.steps.map((s,i)=>(
                      <div key={i} style={{display:"flex", gap:"8px", fontSize:"12px", color:C.sub, marginBottom:"5px", lineHeight:"1.5"}}>
                        <span style={{color:C.mint, fontWeight:"900", flexShrink:0}}>{i+1}.</span>{s}
                      </div>
                    ))}
                  </div>
                ))}
              </div>
            </Box>
          </div>
        )}
      </div>
    </div>
  );
}

