// ═══════════════════════════════════════════════════════════════════════════════
//  NAIL 3D RENDER VIEW — Photo upload → AI analysis → Three.js 3D preview
//  Embedded as a view inside NailTechTab
// ═══════════════════════════════════════════════════════════════════════════════
function NailRenderView() {
  const FOREST="#0D2818",MINT="#27AE78",GOLD="#C9A84C",ROSE="#C4896B",
        PINK="#DB2777",PURPLE="#7C3AED";

  const [photo, setPhoto]           = React.useState(null);
  const [photoFile, setPhotoFile]   = React.useState(null);
  const [analysis, setAnalysis]     = React.useState(null);
  const [analyzing, setAnalyzing]   = React.useState(false);
  const [logLines, setLogLines]     = React.useState([]);
  const [shape, setShape]           = React.useState("almond");
  const [length, setLength]         = React.useState("medium");
  const [finish, setFinish]         = React.useState("gel");
  const [rotating, setRotating]     = React.useState(false);
  const [rotX, setRotX]             = React.useState(0.3);
  const [rotY, setRotY]             = React.useState(0);
  const [saved, setSaved]           = React.useState(false);
  const fileRef   = React.useRef();
  const canvasRef = React.useRef();
  const mountRef  = React.useRef();
  const dragRef   = React.useRef({ active:false, lastX:0, lastY:0 });
  const threeRef  = React.useRef({});

  const SHAPES = [
    {id:"square",   label:"Square"},   {id:"squoval",  label:"Squoval"},
    {id:"oval",     label:"Oval"},     {id:"almond",   label:"Almond"},
    {id:"coffin",   label:"Coffin"},   {id:"stiletto", label:"Stiletto"},
  ];
  const LENGTHS  = [{id:"short",label:"Short"},{id:"medium",label:"Medium"},
                    {id:"long",label:"Long"},{id:"xl",label:"XL"}];
  const FINISHES = [
    {id:"gel",label:"💅 Gel",spec:0.9,rough:0.05},
    {id:"matte",label:"✨ Matte",spec:0.05,rough:0.9},
    {id:"chrome",label:"🪞 Chrome",spec:1.0,rough:0.0},
    {id:"glitter",label:"✨ Glitter",spec:0.7,rough:0.3},
    {id:"french",label:"🤍 French",spec:0.8,rough:0.1},
  ];

  const SCAN_LOG = [
    "📸  Loading nail art image...",
    "🎨  Detecting primary and accent colors...",
    "💅  Identifying nail art technique...",
    "✨  Analyzing finish type and texture...",
    "📐  Determining design complexity...",
    "🖼   Building 3D render parameters...",
    "✅  Ready to render!",
  ];

  // ── Three.js 3D nail renderer ───────────────────────────────────────────────
  React.useEffect(() => {
    if (!mountRef.current) return;
    const THREE = window.THREE;
    if (!THREE) return;

    const W = mountRef.current.clientWidth || 320;
    const H = 260;

    const scene    = new THREE.Scene();
    scene.background = new THREE.Color(0x0A1A10);
    const camera   = new THREE.PerspectiveCamera(45, W/H, 0.1, 100);
    camera.position.set(0, 0.5, 3.5);
    camera.lookAt(0, 0, 0);

    const renderer = new THREE.WebGLRenderer({ antialias:true });
    renderer.setSize(W, H);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    mountRef.current.innerHTML = "";
    mountRef.current.appendChild(renderer.domElement);

    // ── Lighting ──────────────────────────────────────────────────────────────
    const ambient = new THREE.AmbientLight(0xffffff, 0.4);
    scene.add(ambient);
    const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
    keyLight.position.set(2, 3, 2);
    scene.add(keyLight);
    const rimLight = new THREE.DirectionalLight(0xffd0e0, 0.6);
    rimLight.position.set(-2, 1, -1);
    scene.add(rimLight);
    const fillLight = new THREE.PointLight(0xffffff, 0.5, 8);
    fillLight.position.set(0, 2, 1);
    scene.add(fillLight);

    // ── Nail geometry (changes with shape/length) ─────────────────────────────
    function buildNail(shp, lng, clr, fnsh) {
      scene.children = scene.children.filter(c => c.isLight || c.isAmbientLight);
      scene.add(ambient); scene.add(keyLight); scene.add(rimLight); scene.add(fillLight);

      const lengthMap = { short:0.8, medium:1.2, long:1.6, xl:2.0 };
      const L = lengthMap[lng] || 1.2;
      const tipSharp = shp === "stiletto" ? 0.02 : shp === "almond" ? 0.12 : 0.3;
      const tipFlat  = ["square","coffin","squoval"].includes(shp);

      // ── Finger base ─────────────────────────────────────────────────────────
      const fingerGeo = new THREE.CylinderGeometry(0.32, 0.36, 2.2, 24);
      const fingerMat = new THREE.MeshStandardMaterial({
        color:0xE8C4A0, roughness:0.7, metalness:0.0 });
      const finger = new THREE.Mesh(fingerGeo, fingerMat);
      finger.position.y = -1.0;
      scene.add(finger);

      // Fingertip cap
      const capGeo = new THREE.SphereGeometry(0.32, 24, 12, 0, Math.PI*2, 0, Math.PI*0.5);
      const cap = new THREE.Mesh(capGeo, fingerMat);
      cap.position.y = 0.1;
      cap.rotation.x = Math.PI;
      scene.add(cap);

      // ── Nail plate ─────────────────────────────────────────────────────────
      // Build nail shape as a lathe / custom geometry
      const nailColor = new THREE.Color(clr || "#F9A8D4");
      let metalness = fnsh === "chrome" ? 0.95 : fnsh === "glitter" ? 0.5 : 0.1;
      let roughness  = fnsh === "matte" ? 0.95 : fnsh === "chrome" ? 0.02 : fnsh === "glitter" ? 0.3 : 0.05;

      // French tip overlay color
      const nailMat = new THREE.MeshStandardMaterial({
        color: fnsh === "french" ? 0xFFE8EC : nailColor,
        metalness, roughness,
        envMapIntensity: fnsh === "chrome" ? 2 : 1,
      });

      // Build nail using CylinderGeometry segments
      const nailGeo = new THREE.CylinderGeometry(
        tipSharp * 0.3 + (tipFlat ? 0.28 : 0.0),  // top radius
        0.28,                                        // bottom radius
        L, 20, 8, false
      );

      // Deform into curved nail plate shape
      const positions = nailGeo.attributes.position;
      for (let i = 0; i < positions.count; i++) {
        const x = positions.getX(i);
        const y = positions.getY(i);
        const z = positions.getZ(i);
        // Flatten to nail plate, add curvature
        const t = (y + L/2) / L; // 0=base, 1=tip
        const newZ = z * 0.12 + Math.sin(x * 2.2) * 0.04 + 0.02;
        // Coffin flat tip shape
        const edgeX = tipFlat && t > 0.7 ? Math.min(x, 0.28 * (1 - t*0.3)) : x;
        positions.setXYZ(i, edgeX, y * 0.25, newZ);
      }
      nailGeo.computeVertexNormals();

      const nail = new THREE.Mesh(nailGeo, nailMat);
      nail.position.y = 0.24;
      nail.position.z = 0.28;
      nail.rotation.x = -0.15;
      scene.add(nail);

      // French tip white overlay
      if (fnsh === "french") {
        const tipGeo = new THREE.CylinderGeometry(0.28, 0.22, 0.25, 20);
        const tipMat = new THREE.MeshStandardMaterial({color:0xFFFFFF, roughness:0.05, metalness:0.1});
        const tipMesh = new THREE.Mesh(tipGeo, tipMat);
        tipMesh.position.y = 0.24 + L*0.25*0.35;
        tipMesh.position.z = 0.28;
        tipMesh.scale.set(1,0.15,0.8);
        scene.add(tipMesh);
      }

      // Nail surface gloss layer
      if (fnsh === "gel" || fnsh === "chrome") {
        const glossGeo = new THREE.CylinderGeometry(
          tipSharp * 0.3 + (tipFlat?0.285:0.005), 0.285, L, 20, 8, false);
        const glossMat = new THREE.MeshStandardMaterial({
          color:0xffffff, transparent:true, opacity:0.12,
          roughness:0, metalness:0.1 });
        const gloss = new THREE.Mesh(glossGeo, glossMat);
        gloss.position.copy(nail.position);
        gloss.rotation.copy(nail.rotation);
        gloss.scale.set(1,0.25,1);
        scene.add(gloss);
      }

      // Ground plane
      const groundGeo = new THREE.PlaneGeometry(3, 3);
      const groundMat = new THREE.MeshStandardMaterial({color:0x071510, roughness:0.8});
      const ground = new THREE.Mesh(groundGeo, groundMat);
      ground.rotation.x = -Math.PI/2;
      ground.position.y = -2.1;
      scene.add(ground);
    }

    threeRef.current.buildNail = buildNail;
    threeRef.current.scene    = scene;
    threeRef.current.camera   = camera;
    threeRef.current.renderer = renderer;
    threeRef.current.pivot    = new THREE.Group();
    scene.add(threeRef.current.pivot);

    buildNail(shape, length, analysis?.primaryColor || "#F9A8D4", finish);

    // ── Animation loop ────────────────────────────────────────────────────────
    let animId;
    function animate() {
      animId = requestAnimationFrame(animate);
      scene.rotation.y = threeRef.current.rotY || 0;
      scene.rotation.x = threeRef.current.rotX || 0.3;
      renderer.render(scene, camera);
    }
    animate();
    threeRef.current.animId = animId;

    return () => {
      cancelAnimationFrame(animId);
      renderer.dispose();
    };
  }, [mountRef.current]);

  // Update nail when controls change
  React.useEffect(() => {
    if (threeRef.current.buildNail) {
      threeRef.current.buildNail(shape, length, analysis?.primaryColor || "#F9A8D4", finish);
    }
  }, [shape, length, finish, analysis]);

  // Sync rotation
  React.useEffect(() => {
    threeRef.current.rotX = rotX;
    threeRef.current.rotY = rotY;
  }, [rotX, rotY]);

  // ── Mouse/touch drag to rotate ─────────────────────────────────────────────
  function onDragStart(e) {
    dragRef.current.active = true;
    dragRef.current.lastX = e.clientX || e.touches?.[0]?.clientX || 0;
    dragRef.current.lastY = e.clientY || e.touches?.[0]?.clientY || 0;
  }
  function onDragMove(e) {
    if (!dragRef.current.active) return;
    const cx = e.clientX || e.touches?.[0]?.clientX || 0;
    const cy = e.clientY || e.touches?.[0]?.clientY || 0;
    const dx = cx - dragRef.current.lastX;
    const dy = cy - dragRef.current.lastY;
    setRotY(r => r + dx * 0.012);
    setRotX(r => Math.max(-0.8, Math.min(0.8, r + dy * 0.012)));
    dragRef.current.lastX = cx;
    dragRef.current.lastY = cy;
  }
  function onDragEnd() { dragRef.current.active = false; }

  // ── AI photo analysis ──────────────────────────────────────────────────────
  async function analyzeNailArt() {
    if (!photoFile) return;
    setAnalyzing(true); setLogLines([]); setAnalysis(null);
    for (let i = 0; i < SCAN_LOG.length; i++) {
      await new Promise(r => setTimeout(r, 460));
      setLogLines(l => [...l, SCAN_LOG[i]]);
    }
    try {
      const b64 = await new Promise((res, rej) => {
        const reader = new FileReader();
        reader.onload = () => res(reader.result.split(",")[1]);
        reader.onerror = rej;
        reader.readAsDataURL(photoFile);
      });
      const resp = await fetch(CLAUDE_PROXY_URL, {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({
          model:"claude-sonnet-4-6", max_tokens:600,
          system:"You are an expert nail technician AI. Analyze nail art photos and return JSON only — no markdown.",
          messages:[{ role:"user", content:[
            {type:"image", source:{type:"base64", media_type: photoFile.type||"image/jpeg", data:b64}},
            {type:"text", text:'Analyze this nail art. Return ONLY valid JSON: {"primaryColor":"hex color","accentColor":"hex color","technique":"string","finish":"gel|matte|chrome|glitter|french","complexity":"simple|moderate|complex","artStyle":"string","colors":["hex1","hex2","hex3"],"description":"string","proTip":"string","recommendedShape":"square|squoval|oval|almond|coffin|stiletto","estimatedTime":"string","priceRange":"string"}'}
          ]}]
        })
      });
      const d = await resp.json();
      const raw = d.content?.map(b=>b.text||"").join("").replace(/```json|```/g,"").trim();
      const parsed = JSON.parse(raw);
      setAnalysis(parsed);
      setFinish(parsed.finish || "gel");
      setShape(parsed.recommendedShape || shape);
    } catch {
      setAnalysis({
        primaryColor:"#F9A8D4", accentColor:"#FFFFFF",
        technique:"Press-on / Natural Nail Art", finish:"gel",
        complexity:"moderate", artStyle:"Floral / Minimal",
        colors:["#F9A8D4","#FFFFFF","#FFE4E1"],
        description:"AI analysis unavailable — design applied manually.",
        proTip:"Use a thin brush for fine detail work. Cure each layer fully.",
        recommendedShape:"almond", estimatedTime:"60–90 min", priceRange:"$55–85",
      });
      setFinish("gel");
    }
    setAnalyzing(false);
  }

  return (
    <div style={{flex:1,display:"flex",flexDirection:"column",gap:"12px"}}>
      {/* Photo upload */}
      <div>
        <input ref={fileRef} type="file" accept="image/*" style={{display:"none"}}
          onChange={e=>{
            const f=e.target.files[0];
            if(f){setPhotoFile(f);setPhoto(URL.createObjectURL(f));setAnalysis(null);}
          }}/>
        <div onClick={()=>fileRef.current?.click()}
          style={{borderRadius:"14px",overflow:"hidden",cursor:"pointer",
            border:`2px dashed ${photo?"rgba(39,174,120,0.5)":"rgba(255,255,255,0.15)"}`,
            background:photo?"transparent":"rgba(255,255,255,0.04)",
            minHeight:"120px",display:"flex",alignItems:"center",justifyContent:"center",position:"relative"}}>
          {photo
            ? <><img src={photo} alt="nail art" style={{width:"100%",maxHeight:"180px",objectFit:"cover"}}/>
                <div style={{position:"absolute",bottom:"8px",right:"8px",background:"rgba(0,0,0,0.7)",
                  borderRadius:"8px",padding:"4px 10px",fontSize:"9px",color:MINT,fontWeight:"800"}}>
                  Tap to change
                </div></>
            : <div style={{textAlign:"center",padding:"20px"}}>
                <div style={{fontSize:"32px",marginBottom:"8px"}}>💅</div>
                <div style={{fontSize:"12px",color:"#fff",fontWeight:"800",marginBottom:"4px"}}>Upload Nail Art Inspo</div>
                <div style={{fontSize:"10px",color:"rgba(255,255,255,0.4)"}}>Photo, screenshot, or design reference</div>
              </div>}
        </div>
      </div>

      {photo && !analysis && !analyzing && (
        <button onClick={analyzeNailArt}
          style={{width:"100%",background:`linear-gradient(135deg,${PINK},#A21753)`,
            color:"#fff",border:"none",padding:"12px",borderRadius:"12px",
            fontSize:"13px",fontWeight:"900",cursor:"pointer"}}>
          🔍 Analyze Design + Build 3D Preview
        </button>
      )}

      {/* Scan log */}
      {analyzing && (
        <div style={{background:"rgba(255,255,255,0.04)",border:"1px solid rgba(39,174,120,0.15)",
          borderRadius:"12px",padding:"12px",fontFamily:"'Courier New',monospace"}}>
          {logLines.map((l,i)=>(
            <div key={i} style={{fontSize:"11px",marginBottom:"4px",
              color:i===logLines.length-1?"#86EFAC":"rgba(255,255,255,0.45)"}}>{l}</div>
          ))}
        </div>
      )}

      {/* Analysis result card */}
      {analysis && (
        <div style={{background:"rgba(219,39,119,0.08)",border:"1px solid rgba(219,39,119,0.3)",
          borderRadius:"12px",padding:"12px"}}>
          <div style={{fontSize:"9px",letterSpacing:"2px",color:PINK,fontWeight:"800",marginBottom:"8px"}}>
            AI DESIGN ANALYSIS
          </div>
          <div style={{fontSize:"13px",fontWeight:"800",color:"#fff",marginBottom:"4px"}}>{analysis.artStyle}</div>
          <div style={{fontSize:"11px",color:"rgba(255,255,255,0.65)",marginBottom:"8px",lineHeight:"1.5"}}>{analysis.description}</div>
          <div style={{display:"flex",gap:"6px",flexWrap:"wrap",marginBottom:"8px"}}>
            {(analysis.colors||[]).map(c=>(
              <div key={c} style={{width:"22px",height:"22px",borderRadius:"50%",background:c,
                border:"2px solid rgba(255,255,255,0.3)"}}/>
            ))}
            <span style={{fontSize:"10px",color:"rgba(255,255,255,0.5)",alignSelf:"center",marginLeft:"4px"}}>
              {analysis.technique}
            </span>
          </div>
          <div style={{display:"flex",gap:"8px",fontSize:"10px"}}>
            <span style={{color:GOLD}}>⏱ {analysis.estimatedTime}</span>
            <span style={{color:MINT}}>💰 {analysis.priceRange}</span>
            <span style={{color:"rgba(255,255,255,0.5)"}}>
              {analysis.complexity === "complex" ? "⭐ Specialist" : analysis.complexity === "moderate" ? "✦ Intermediate" : "• Beginner"}
            </span>
          </div>
          {analysis.proTip && (
            <div style={{marginTop:"8px",background:"rgba(201,168,76,0.1)",border:"1px solid rgba(201,168,76,0.3)",
              borderRadius:"8px",padding:"8px 10px",fontSize:"10px",color:"#FCD34D",lineHeight:"1.5"}}>
              💡 Pro Tip: {analysis.proTip}
            </div>
          )}
        </div>
      )}

      {/* ── THREE.JS 3D NAIL CANVAS ── */}
      <div>
        <div style={{fontSize:"10px",letterSpacing:"2px",color:"rgba(255,255,255,0.4)",
          fontWeight:"800",marginBottom:"8px"}}>
          3D PREVIEW — DRAG TO ROTATE
        </div>
        <div
          ref={mountRef}
          onMouseDown={onDragStart} onMouseMove={onDragMove} onMouseUp={onDragEnd} onMouseLeave={onDragEnd}
          onTouchStart={e=>onDragStart(e.touches[0])} onTouchMove={e=>{e.preventDefault();onDragMove(e);}}
          onTouchEnd={onDragEnd}
          style={{borderRadius:"16px",overflow:"hidden",background:"#0A1A10",
            border:"1px solid rgba(39,174,120,0.2)",cursor:"grab",userSelect:"none",
            height:"260px",touchAction:"none"}}
        />
        <div style={{textAlign:"center",fontSize:"9px",color:"rgba(255,255,255,0.25)",marginTop:"4px"}}>
          Drag to rotate · Controls below change shape and finish
        </div>
      </div>

      {/* Shape selector */}
      <div>
        <div style={{fontSize:"10px",letterSpacing:"2px",color:"rgba(255,255,255,0.4)",fontWeight:"800",marginBottom:"6px"}}>
          NAIL SHAPE
        </div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:"5px"}}>
          {SHAPES.map(s=>(
            <button key={s.id} onClick={()=>setShape(s.id)}
              style={{background:shape===s.id?"rgba(219,39,119,0.2)":"rgba(255,255,255,0.05)",
                border:`1px solid ${shape===s.id?"rgba(219,39,119,0.6)":"rgba(255,255,255,0.1)"}`,
                color:shape===s.id?"#F9A8D4":"rgba(255,255,255,0.5)",
                padding:"7px 4px",borderRadius:"8px",fontSize:"10px",fontWeight:"700",cursor:"pointer"}}>
              {s.label}
            </button>
          ))}
        </div>
      </div>

      {/* Length + Finish */}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"10px"}}>
        <div>
          <div style={{fontSize:"10px",letterSpacing:"2px",color:"rgba(255,255,255,0.4)",fontWeight:"800",marginBottom:"6px"}}>LENGTH</div>
          {LENGTHS.map(l=>(
            <button key={l.id} onClick={()=>setLength(l.id)}
              style={{display:"block",width:"100%",background:length===l.id?"rgba(39,174,120,0.2)":"rgba(255,255,255,0.04)",
                border:`1px solid ${length===l.id?MINT:"rgba(255,255,255,0.08)"}`,
                color:length===l.id?MINT:"rgba(255,255,255,0.5)",
                padding:"6px 10px",borderRadius:"8px",fontSize:"11px",fontWeight:"700",
                cursor:"pointer",marginBottom:"4px",textAlign:"left"}}>
              {l.label}
            </button>
          ))}
        </div>
        <div>
          <div style={{fontSize:"10px",letterSpacing:"2px",color:"rgba(255,255,255,0.4)",fontWeight:"800",marginBottom:"6px"}}>FINISH</div>
          {FINISHES.map(f=>(
            <button key={f.id} onClick={()=>setFinish(f.id)}
              style={{display:"block",width:"100%",background:finish===f.id?"rgba(201,168,76,0.2)":"rgba(255,255,255,0.04)",
                border:`1px solid ${finish===f.id?GOLD:"rgba(255,255,255,0.08)"}`,
                color:finish===f.id?GOLD:"rgba(255,255,255,0.5)",
                padding:"6px 10px",borderRadius:"8px",fontSize:"11px",fontWeight:"700",
                cursor:"pointer",marginBottom:"4px",textAlign:"left"}}>
              {f.label}
            </button>
          ))}
        </div>
      </div>

      {/* Save / Share */}
      <button onClick={()=>setSaved(true)}
        style={{width:"100%",background:saved?`rgba(39,174,120,0.2)`:`linear-gradient(135deg,${GOLD},#A07830)`,
          color:saved?MINT:FOREST,border:saved?`1px solid ${MINT}`:"none",
          padding:"13px",borderRadius:"12px",fontSize:"13px",fontWeight:"900",cursor:"pointer"}}>
        {saved ? "✓ Saved to Client Profile" : "💾 Save Render to Client Profile"}
      </button>

      {saved && (
        <div style={{background:"rgba(39,174,120,0.08)",border:"1px solid rgba(39,174,120,0.25)",
          borderRadius:"10px",padding:"10px 12px",fontSize:"10px",color:MINT,lineHeight:"1.6"}}>
          ✓ 3D render saved · Attach to bid ticket with Style ID when posting
        </div>
      )}
    </div>
  );
}



function NailTechTab() {
  const [view, setView] = useState("services");
  const [activeCat, setActiveCat] = useState("all");
  const [selected, setSelected] = useState(null);
  const [tutorialStyle, setTutorialStyle] = useState(null);
  const [aiQ, setAiQ] = useState(""); const [aiHistory, setAiHistory] = useState([]); const [aiLoading, setAiLoading] = useState(false);
  const [tutoActive, setTutoActive] = useState(false);
  const [currentStep, setCurrentStep] = useState(0);
  const [stepChecked, setStepChecked] = useState({});
  const [clientNotes, setClientNotes] = useState("");
  const [colorInput, setColorInput] = useState("");
  const [colorResult, setColorResult] = useState(""); const [colorLoading, setColorLoading] = useState(false);

  const filtered = NAIL_SERVICES.filter(s => activeCat === "all" || s.cat === activeCat);
  const NAV = [["services","Services"],["tutorial","Step-by-Step"],["health","Nail Health"],["color","Color AI"],["ai","AI Coach"],["render","💅 3D Render"]];

  async function askNailAI() {
    if (!aiQ.trim()) return;
    setAiLoading(true);
    const msgs = [...aiHistory, {role:"user", content:aiQ}];
    const sys = `You are an expert licensed nail technician AI coach for Love That Idea. You specialize in nail services including manicures, pedicures, gel, acrylic, PolyGel, nail art, and client safety. Give specific, technically accurate guidance on nail techniques, product chemistry, sanitation, and client care. Under 200 words.`;
    try {
      const res = await fetch(CLAUDE_PROXY_URL, {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({model:"claude-sonnet-4-20250514", max_tokens:700, system:sys, messages:msgs})
      });
      const d = await res.json();
      const ans = d.content ? d.content.map(b=>b.text||"").join("") : "";
      setAiHistory([...msgs, {role:"assistant",content:ans}]);
    } catch(e) { setAiHistory(prev=>[...prev,{role:"assistant",content:"Connection error."}]); }
    setAiQ(""); setAiLoading(false);
  }

  async function getColorMatch() {
    if (!colorInput.trim()) return;
    setColorLoading(true); setColorResult("");
    try {
      const res = await fetch(CLAUDE_PROXY_URL, {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({model:"claude-sonnet-4-20250514", max_tokens:400, system:"You are an expert nail color consultant. Recommend specific nail polish shades, finishes, and combinations based on the client description. Mention specific popular brand shades when relevant. Under 150 words.",
          messages:[{role:"user",content:`Client description: ${colorInput}. Recommend the perfect nail color, finish, and any nail art ideas.`}]})
      });
      const d = await res.json();
      setColorResult(d.content ? d.content.map(b=>b.text||"").join("") : "");
    } catch(e) { setColorResult("Connection error. Try again."); }
    setColorLoading(false);
  }

  const catColor = (cat) => NAIL_CATS.find(c=>c.id===cat)?.color || C.mint;

  return (
    <div style={{flex:1,display:"flex",flexDirection:"column",overflow:"hidden",background:C.bg}}>
      <div style={{background:"linear-gradient(135deg,#FDF2F8,#FCE7F3)",borderBottom:`1px solid #F9A8D4`,padding:"14px 20px",display:"flex",alignItems:"center",gap:"14px",flexShrink:0}}>
        <div style={{fontSize:"32px"}}>💅</div>
        <div>
          <div style={{fontSize:"20px",fontWeight:"900",color:"#BE185D",fontFamily:"'Cormorant Garamond',serif"}}>Nail Tech Studio</div>
          <div style={{fontSize:"12px",color:"#DB2777"}}>Services, Tutorials, AI Coach, Nail Health and Color Consultation</div>
        </div>
        <div style={{marginLeft:"auto",display:"flex",gap:"6px"}}>
          {NAV.map(([v,l])=>(
            <button key={v} onClick={()=>setView(v)} style={{background:view===v?"#DB2777":"rgba(219,39,119,0.1)",color:view===v?"#fff":"#DB2777",border:`1px solid ${view===v?"#DB2777":"#F9A8D4"}`,padding:"7px 14px",borderRadius:"20px",fontSize:"11px",fontWeight:"700",cursor:"pointer"}}>{l}</button>
          ))}
        </div>
      </div>

      <div style={{flex:1,overflowY:"auto",padding:"20px"}}>

        {view === "services" && (
          <div>
            <div style={{display:"flex",gap:"8px",marginBottom:"16px",flexWrap:"wrap"}}>
              {NAIL_CATS.map(cat=>(
                <button key={cat.id} onClick={()=>setActiveCat(cat.id)} style={{background:activeCat===cat.id?cat.color:"#F9F9F9",color:activeCat===cat.id?"#fff":C.muted,border:`1px solid ${activeCat===cat.id?cat.color:C.dim}`,padding:"7px 16px",borderRadius:"20px",fontSize:"12px",fontWeight:"700",cursor:"pointer"}}>{cat.label}</button>
              ))}
            </div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(280px,1fr))",gap:"14px"}}>
              {filtered.map(svc=>(
                <div key={svc.id} onClick={()=>setSelected(selected?.id===svc.id?null:svc)}
                  style={{background:C.white,border:`2px solid ${selected?.id===svc.id?catColor(svc.cat):C.border}`,borderRadius:"14px",overflow:"hidden",cursor:"pointer",transition:"all 0.2s",boxShadow:selected?.id===svc.id?`0 4px 20px ${catColor(svc.cat)}22`:"0 2px 8px rgba(0,0,0,0.06)"}}>
                  <div style={{height:"4px",background:catColor(svc.cat)}} />
                  <div style={{padding:"16px"}}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:"8px"}}>
                      <div style={{display:"flex",gap:"10px",alignItems:"center"}}>
                        <span style={{fontSize:"24px"}}>{svc.icon}</span>
                        <div>
                          <div style={{fontSize:"14px",fontWeight:"800",color:C.text}}>{svc.name}</div>
                          <div style={{fontSize:"11px",color:C.muted}}>{svc.time} - {svc.price}</div>
                        </div>
                      </div>
                      <span style={{background:catColor(svc.cat)+"18",color:catColor(svc.cat),fontSize:"9px",padding:"3px 9px",borderRadius:"20px",fontWeight:"800"}}>{svc.difficulty}</span>
                    </div>
                    <div style={{fontSize:"12px",color:C.muted,lineHeight:"1.6",marginBottom:"10px"}}>{svc.desc}</div>
                    <button onClick={e=>{e.stopPropagation();setTutorialStyle(svc);setCurrentStep(0);setStepChecked({});setView("tutorial");}}
                      style={{width:"100%",background:"linear-gradient(135deg,#DB2777,#9D174D)",color:"#fff",border:"none",padding:"9px",borderRadius:"8px",fontSize:"12px",fontWeight:"800",cursor:"pointer"}}>
                      Start Step-by-Step Tutorial
                    </button>
                  </div>
                  {selected?.id===svc.id && (
                    <div style={{borderTop:`1px solid ${C.dim}`,padding:"14px",background:"#FDF2F8"}}>
                      <div style={{fontSize:"10px",letterSpacing:"2px",color:"#DB2777",fontWeight:"700",marginBottom:"8px"}}>STEP OVERVIEW</div>
                      {svc.steps.map((s,i)=>(
                        <div key={i} style={{display:"flex",gap:"8px",fontSize:"12px",color:C.sub,marginBottom:"5px",lineHeight:"1.5"}}>
                          <span style={{color:"#DB2777",fontWeight:"800",flexShrink:0}}>{i+1}.</span>{s.slice(0,80)}{s.length>80?"...":""}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}

        {view === "tutorial" && (
          <div>
            {!tutorialStyle ? (
              <div style={{textAlign:"center",padding:"60px 20px"}}>
                <div style={{fontSize:"40px",marginBottom:"12px"}}>💅</div>
                <div style={{fontSize:"18px",fontWeight:"800",color:C.text,marginBottom:"6px"}}>Select a service from the Services tab</div>
                <button onClick={()=>setView("services")} style={{background:"linear-gradient(135deg,#DB2777,#9D174D)",color:"#fff",border:"none",padding:"11px 24px",borderRadius:"10px",fontSize:"13px",fontWeight:"800",cursor:"pointer"}}>Browse Services</button>
              </div>
            ) : (
              <div style={{maxWidth:"700px",margin:"0 auto"}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:"20px"}}>
                  <div>
                    <div style={{fontSize:"10px",letterSpacing:"3px",color:"#DB2777",fontWeight:"800",marginBottom:"4px"}}>STEP-BY-STEP TUTORIAL</div>
                    <div style={{fontSize:"22px",fontWeight:"900",color:C.text}}>{tutorialStyle.icon} {tutorialStyle.name}</div>
                    <div style={{fontSize:"12px",color:C.muted}}>{tutorialStyle.time} - {tutorialStyle.price}</div>
                  </div>
                  <button onClick={()=>setTutorialStyle(null)} style={{background:C.white,border:`1px solid ${C.border}`,color:C.muted,padding:"8px 16px",borderRadius:"8px",fontSize:"12px",cursor:"pointer"}}>Change Service</button>
                </div>
                <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"16px",overflow:"hidden",marginBottom:"16px"}}>
                  <div style={{height:"5px",background:"linear-gradient(90deg,#DB2777,#9D174D)"}} />
                  <div style={{padding:"16px 20px",borderBottom:`1px solid ${C.dim}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                    <div style={{fontSize:"13px",fontWeight:"700",color:C.text}}>Progress</div>
                    <div style={{fontSize:"12px",color:"#DB2777",fontWeight:"700"}}>{Object.values(stepChecked).filter(Boolean).length}/{tutorialStyle.steps.length} steps done</div>
                  </div>
                  <div style={{height:"6px",background:C.dim,overflow:"hidden"}}>
                    <div style={{height:"100%",width:`${(Object.values(stepChecked).filter(Boolean).length/tutorialStyle.steps.length)*100}%`,background:"linear-gradient(90deg,#DB2777,#9D174D)",transition:"width 0.4s"}} />
                  </div>
                  <div style={{padding:"16px 20px"}}>
                    {tutorialStyle.steps.map((step,i)=>(
                      <div key={i} style={{display:"flex",gap:"14px",alignItems:"flex-start",padding:"12px 0",borderBottom:i<tutorialStyle.steps.length-1?`1px solid ${C.dim}`:"none"}}>
                        <button onClick={()=>setStepChecked(prev=>({...prev,[i]:!prev[i]}))}
                          style={{width:"28px",height:"28px",borderRadius:"50%",background:stepChecked[i]?"#DB2777":C.bg,border:`2px solid ${stepChecked[i]?"#DB2777":C.border}`,color:"#fff",fontSize:"12px",cursor:"pointer",flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",transition:"all 0.2s"}}>
                          {stepChecked[i]?"✓":""}
                        </button>
                        <div style={{flex:1}}>
                          <div style={{display:"flex",gap:"8px",alignItems:"center",marginBottom:"4px"}}>
                            <span style={{background:"#FDF2F8",color:"#DB2777",fontSize:"10px",padding:"2px 8px",borderRadius:"20px",fontWeight:"800"}}>Step {i+1}</span>
                            {stepChecked[i] && <span style={{fontSize:"10px",color:"#059669",fontWeight:"700"}}>Complete</span>}
                          </div>
                          <div style={{fontSize:"13px",color:stepChecked[i]?C.muted:C.text,textDecoration:stepChecked[i]?"line-through":"none",lineHeight:"1.7"}}>{step}</div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
                <div style={{background:"#FDF2F8",border:"1px solid #F9A8D4",borderRadius:"12px",padding:"14px 18px"}}>
                  <div style={{fontSize:"10px",letterSpacing:"2px",color:"#DB2777",fontWeight:"700",marginBottom:"8px"}}>CLIENT NOTES</div>
                  <textarea value={clientNotes} onChange={e=>setClientNotes(e.target.value)} placeholder="Note client preferences, allergies, nail condition, polish choice..." rows={3}
                    style={{width:"100%",background:C.white,border:`1px solid #F9A8D4`,color:C.text,padding:"10px 12px",borderRadius:"8px",fontSize:"13px",boxSizing:"border-box",resize:"none"}} />
                </div>
              </div>
            )}
          </div>
        )}

        {view === "health" && (
          <div>
            <div style={{fontSize:"22px",fontWeight:"900",color:C.text,marginBottom:"4px"}}>Nail Health and Safety</div>
            <div style={{fontSize:"13px",color:C.muted,marginBottom:"20px"}}>Know when to serve and when to refer. Client safety is always the priority.</div>
            <div style={{background:"#FEF2F2",border:"2px solid #FECACA",borderRadius:"14px",padding:"16px 20px",marginBottom:"20px"}}>
              <div style={{fontSize:"13px",fontWeight:"800",color:"#DC2626",marginBottom:"8px"}}>GOLDEN RULE: When in doubt, don't. Always refer to a physician.</div>
              <div style={{fontSize:"12px",color:"#7F1D1D",lineHeight:"1.7"}}>Licensed nail technicians are not medical professionals. Never perform services on clients with open wounds, active infections, or conditions you are uncertain about. Referring a client protects both them and your license.</div>
            </div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(320px,1fr))",gap:"14px"}}>
              {NAIL_HEALTH.map(h=>(
                <div key={h.condition} style={{background:C.white,border:`2px solid ${h.color}33`,borderRadius:"14px",overflow:"hidden"}}>
                  <div style={{height:"4px",background:h.color}} />
                  <div style={{padding:"16px"}}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:"8px"}}>
                      <div style={{fontSize:"14px",fontWeight:"800",color:h.color}}>{h.condition}</div>
                      {h.urgent && <span style={{background:"#FEF2F2",color:"#DC2626",fontSize:"9px",padding:"3px 9px",borderRadius:"20px",fontWeight:"800"}}>REFUSE SERVICE</span>}
                    </div>
                    <div style={{fontSize:"12px",color:C.muted,marginBottom:"10px",fontStyle:"italic"}}>Signs: {h.signs}</div>
                    <div style={{background:h.urgent?"#FEF2F2":C.bg,border:`1px solid ${h.color}33`,borderRadius:"8px",padding:"10px 12px",fontSize:"12px",color:h.urgent?"#7F1D1D":C.sub,lineHeight:"1.6"}}>{h.action}</div>
                  </div>
                </div>
              ))}
            </div>
            <div style={{marginTop:"20px",background:C.white,border:`1px solid ${C.border}`,borderRadius:"14px",padding:"18px"}}>
              <div style={{fontSize:"14px",fontWeight:"800",color:C.text,marginBottom:"14px"}}>Sanitation Standards</div>
              {[["Implements","Use hospital-grade disinfectant (Barbicide or EPA-registered) for all non-porous metal tools. 10+ minutes immersion. Single-use files and buffers per client."],["Foot Spas","Drain, clean, disinfect, and flush foot spa basin after every client. Monthly biofilm purge required per state board."],["Product Hygiene","Never double-dip brushes back into bottles. Decant into dappen dish. Store monomer in sealed containers."],["Hand Hygiene","Wash hands before and after every client. Gloves recommended for acrylic application."]].map(([title,desc])=>(
                <div key={title} style={{display:"flex",gap:"12px",alignItems:"flex-start",padding:"10px 0",borderBottom:`1px solid ${C.dim}`}}>
                  <span style={{color:"#DB2777",fontWeight:"900",fontSize:"14px",flexShrink:0}}>✓</span>
                  <div>
                    <div style={{fontSize:"13px",fontWeight:"700",color:C.text}}>{title}</div>
                    <div style={{fontSize:"12px",color:C.muted,marginTop:"2px",lineHeight:"1.6"}}>{desc}</div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === "color" && (
          <div style={{maxWidth:"600px"}}>
            <div style={{display:"flex",alignItems:"center",gap:"10px",marginBottom:"4px"}}><div style={{fontSize:"22px",fontWeight:"900",color:C.text}}>AI Color Consultation</div><ClaudeBadge size="md" style={{background:"linear-gradient(135deg,#DB2777,#9D174D)"}} /></div>
            <div style={{fontSize:"13px",color:C.muted,marginBottom:"20px"}}>Describe your client and their occasion. Claude recommends the perfect nail color, finish, and art ideas.</div>
            <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"16px",padding:"20px",marginBottom:"16px"}}>
              <textarea value={colorInput} onChange={e=>setColorInput(e.target.value)} placeholder="e.g. Client has warm olive skin, brown eyes, going to a summer wedding as bridesmaid in dusty rose dress. Prefers gel, medium length, nothing too flashy..." rows={4}
                style={{width:"100%",background:C.bg,border:`1.5px solid ${C.border}`,color:C.text,padding:"10px 12px",borderRadius:"8px",fontSize:"13px",boxSizing:"border-box",resize:"none",marginBottom:"12px"}} />
              <button onClick={getColorMatch} disabled={colorLoading||!colorInput.trim()} style={{width:"100%",background:colorLoading||!colorInput.trim()?C.dim:"linear-gradient(135deg,#DB2777,#9D174D)",color:colorLoading||!colorInput.trim()?C.muted:"#fff",border:"none",padding:"12px",borderRadius:"10px",fontSize:"14px",fontWeight:"800",cursor:colorLoading||!colorInput.trim()?"not-allowed":"pointer"}}>
                {colorLoading?"Getting recommendation...":"Get AI Color Recommendation"}
              </button>
              {colorResult && (
                <div style={{marginTop:"14px",background:"#FDF2F8",border:"1px solid #F9A8D4",borderRadius:"10px",padding:"14px",fontSize:"13px",color:C.sub,lineHeight:"1.8"}}>
                  <div style={{fontSize:"10px",letterSpacing:"2px",color:"#DB2777",fontWeight:"700",marginBottom:"8px"}}>AI COLOR RECOMMENDATION</div>
                  {colorResult}
                </div>
              )}
            </div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"10px"}}>
              {[["Skin Tone Guide","Warm tones: nudes, corals, oranges, warm reds. Cool tones: mauve, berry, cool pinks, bluish reds. Neutral: almost anything works.","#DB2777"],["Finish Types","Cream: classic opaque. Shimmer: subtle sparkle. Glitter: bold sparkle. Matte: trendy flat. Chrome: mirror effect. Jelly: sheer glass nails.","#7C3AED"],["Trending Now","Glazed donut nails, chrome gel, soft minimal French, abstract nail art, coastal grandmother vibe, red nails all year.","#0891B2"],["Nail Shape Guide","Round: low maintenance. Oval: feminine. Almond: elegant. Stiletto: dramatic. Square: classic. Coffin: trendy bold.","#D97706"]].map(([title,desc,color])=>(
                <div key={title} style={{background:C.white,border:`1px solid ${color}33`,borderRadius:"12px",padding:"14px"}}>
                  <div style={{fontSize:"12px",fontWeight:"800",color,marginBottom:"6px"}}>{title}</div>
                  <div style={{fontSize:"11px",color:C.muted,lineHeight:"1.6"}}>{desc}</div>
                </div>
              ))}
            </div>
          </div>
        )}

        {view === "ai" && (
          <div style={{maxWidth:"680px"}}>
            <div style={{display:"flex",alignItems:"center",gap:"10px",marginBottom:"4px"}}><div style={{fontSize:"22px",fontWeight:"900",color:C.text}}>Nail Tech AI Coach</div><ClaudeBadge size="md" style={{background:"linear-gradient(135deg,#DB2777,#9D174D)"}} /></div>
            <div style={{fontSize:"13px",color:C.muted,marginBottom:"14px"}}>Ask anything about nail services, products, client care, or techniques.</div>
            <div style={{display:"flex",gap:"6px",flexWrap:"wrap",marginBottom:"14px"}}>
              {["How to fix a lifting gel?","Monomer vs dip powder - when to use?","Client has thin nails - best approach?","How to do a proper ombre?","Why is my acrylic bubbling?","Best way to remove gel without damage?"].map(q=>(
                <button key={q} onClick={()=>setAiQ(q)} style={{background:C.white,border:"1px solid #F9A8D4",color:"#DB2777",padding:"6px 13px",borderRadius:"20px",fontSize:"11px",cursor:"pointer",fontWeight:"600"}}>{q}</button>
              ))}
            </div>
            <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:"14px",padding:"14px",minHeight:"280px",maxHeight:"400px",overflowY:"auto",marginBottom:"12px",display:"flex",flexDirection:"column",gap:"10px"}}>
              {aiHistory.length===0 && <div style={{textAlign:"center",color:C.muted,padding:"40px 0"}}><div style={{fontSize:"32px",marginBottom:"10px"}}>💅</div><div>Ask your nail tech coaching question</div></div>}
              {aiHistory.map((m,i)=>(
                <div key={i} style={{display:"flex",justifyContent:m.role==="user"?"flex-end":"flex-start", minWidth:0 }}>
                  <div style={{maxWidth:"85%",padding:"10px 14px",borderRadius:m.role==="user"?"16px 16px 4px 16px":"16px 16px 16px 4px",background:m.role==="user"?"linear-gradient(135deg,#DB2777,#9D174D)":C.bg,color:m.role==="user"?"#fff":C.text,fontSize:"13px",wordBreak:"break-word",overflowWrap:"break-word",whiteSpace:"pre-wrap",lineHeight:"1.7",border:m.role==="assistant"?`1px solid ${C.border}`:"none"}}>
                    {m.content}
                  </div>
                </div>
              ))}
              {aiLoading && <div style={{display:"flex",gap:"5px",padding:"10px",background:C.bg,border:`1px solid ${C.border}`,borderRadius:"12px",width:"fit-content"}}>{[0,1,2].map(i=><div key={i} style={{width:"7px",height:"7px",borderRadius:"50%",background:"#DB2777",animation:`pulse 1s ease ${i*.2}s infinite`}}/>)}</div>}
            </div>
            <div style={{display:"flex",gap:"8px"}}>
              <input value={aiQ} onChange={e=>setAiQ(e.target.value)} onKeyDown={e=>e.key==="Enter"&&askNailAI()} placeholder="Ask about nail techniques, products, client care..." style={{flex:1,background:C.white,border:`1.5px solid ${C.border}`,color:C.text,padding:"11px 14px",borderRadius:"10px",fontSize:"13px"}} />
              <button onClick={askNailAI} disabled={aiLoading} style={{background:aiLoading?C.dim:"linear-gradient(135deg,#DB2777,#9D174D)",color:"#fff",border:"none",padding:"11px 20px",borderRadius:"10px",fontSize:"13px",fontWeight:"800",cursor:aiLoading?"not-allowed":"pointer"}}>Ask</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

