function haversineDistance(lat1, lon1, lat2, lon2) {
  const R = 3958.8; // Earth radius in miles
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat/2)**2 +
            Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) *
            Math.sin(dLon/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

// ── ETA calculation — urban average 22mph, express 35mph ─────────────────────
function calcETAMinutes(distanceMiles, mode = "urban") {
  const speed = mode === "express" ? 35 : 22;
  return Math.round((distanceMiles / speed) * 60) + 5; // +5 min buffer
}

// ── Arrival risk scoring ──────────────────────────────────────────────────────
// Returns: { level:"green"|"yellow"|"red", label:string, buffer:number }
function calcArrivalRisk(etaMinutes, requestedTimeStr, prepMinutes = 0) {
  const now = new Date();
  let requestedDate = new Date();

  // Parse "Today 2:00 PM" or "Tomorrow 11:00 AM"
  if (requestedTimeStr) {
    const parts = requestedTimeStr.replace("Today","").replace("Tomorrow","").trim().split(" ");
    const [time, meridiem] = parts;
    let [hr, min] = time.split(":").map(Number);
    if (meridiem === "PM" && hr !== 12) hr += 12;
    if (meridiem === "AM" && hr === 12) hr = 0;
    requestedDate.setHours(hr, min, 0, 0);
    if (requestedTimeStr.includes("Tomorrow")) {
      requestedDate.setDate(requestedDate.getDate() + 1);
    }
  }

  const minutesUntilNeeded = (requestedDate - now) / 60000;
  const totalNeeded = etaMinutes + prepMinutes;
  const buffer = minutesUntilNeeded - totalNeeded;

  if (buffer >= 30) return { level:"green",  label:"On Time",      buffer: Math.round(buffer) };
  if (buffer >= 10) return { level:"yellow", label:"Cutting Close", buffer: Math.round(buffer) };
  return               { level:"red",    label:"At Risk",      buffer: Math.round(buffer) };
}

// ── ArrivalRiskBadge component ────────────────────────────────────────────────
function ArrivalRiskBadge({ risk, etaMinutes, distanceMiles, compact=false }) {
  if (!risk) return null;
  const colors = { green:"#27AE78", yellow:"#D97706", red:"#DC2626" };
  const bg     = { green:"rgba(39,174,120,0.12)", yellow:"rgba(217,119,6,0.12)", red:"rgba(220,38,38,0.12)" };
  const icons  = { green:"✅", yellow:"⚡", red:"🔴" };
  const C = colors[risk.level];

  if (compact) {
    return (
      <span style={{display:"inline-flex",alignItems:"center",gap:"3px",
        background:bg[risk.level],border:`1px solid ${C}44`,
        borderRadius:"20px",padding:"2px 8px",fontSize:"9px",fontWeight:"800",color:C}}>
        {icons[risk.level]} {distanceMiles?.toFixed(1)}mi · {etaMinutes}min
      </span>
    );
  }

  return (
    <div style={{background:bg[risk.level],border:`1.5px solid ${C}44`,
      borderRadius:"10px",padding:"8px 12px",display:"flex",gap:"10px",alignItems:"center"}}>
      <div style={{fontSize:"20px"}}>{icons[risk.level]}</div>
      <div style={{flex:1}}>
        <div style={{fontSize:"11px",fontWeight:"800",color:C}}>{risk.label}</div>
        <div style={{fontSize:"10px",color:"rgba(255,255,255,0.55)"}}>
          {distanceMiles?.toFixed(1)} miles away · ~{etaMinutes} min drive
          {risk.buffer > 0
            ? ` · ${risk.buffer} min buffer`
            : ` · ${Math.abs(risk.buffer)} min over time`}
        </div>
      </div>
    </div>
  );
}

